const char* GateName(UnprunedGate g)
{
    for (const auto& n : kGateNames) { if (n.second == g) { return n.first; } }
    return "?";
}

// Gate PROBE: skip sweeping gates that have no live decision point for a deck. When enabled, every
// DecisionUnpruned(gate) callsite that actually EXECUTES ORs its gate into a global mask (across all
// threads/games of a run). A gate never queried has no reachable callsite for this deck (no matching
// cards / no rituals / no dig source / ...), so opening it provably changes nothing -- skip it. A gate
// that IS queried may still be neutral, but can only be cleared by actually sweeping it. The `&&`/`||`
// short-circuits at the callsites mean the query only fires when the gate's guard condition holds
// (e.g. Ponder only when a cast_reorder card exists), so "queried" is a faithful "live for this deck".
static std::atomic<bool>     g_gate_probe{false};
static std::atomic<uint32_t> g_gates_queried{0};

void     SetGateProbe(bool on) { g_gate_probe.store(on); if (on) { g_gates_queried.store(0); } }
uint32_t QueriedGatesMask()    { return g_gates_queried.load(); }
bool     GateProbeArmed()      { return g_gate_probe.load(std::memory_order_relaxed); }

// Parse MTG_UNPRUNE=<comma/space/;/| separated gate names> once into a bitmask over UnprunedGate.
// "all" (or the legacy MTG_UNPRUNED) sets every bit. Unknown tokens are ignored. Case-insensitive.
static uint32_t ParseUnpruneMask()
{
    const char* e = std::getenv("MTG_UNPRUNE");
    if (!e) { return 0; }
    std::string s = e;
    for (char& c : s) { c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
                        if (c == ',' || c == ';' || c == '|') { c = ' '; } }
    auto bit = [](UnprunedGate g) { return 1u << static_cast<int>(g); };
    uint32_t mask = 0;
    std::size_t pos = 0;
    while (pos < s.size())
    {
        while (pos < s.size() && s[pos] == ' ') { ++pos; }
        std::size_t end = s.find(' ', pos);
        if (end == std::string::npos) { end = s.size(); }
        std::string tok = s.substr(pos, end - pos);
        pos = end;
        if (tok.empty()) { continue; }
        if (tok == "all")
        { mask = static_cast<uint32_t>((std::uint64_t{1} << static_cast<int>(UnprunedGate::_Count)) - 1u); continue; }
        for (const auto& n : kGateNames) { if (tok == n.first) { mask |= bit(n.second); break; } }
    }
    return mask;
}

static uint32_t UnpruneMask()
{
    static const uint32_t m = ParseUnpruneMask();
    return m;
}

bool DecisionUnpruned()
{
    static const bool v = EnvOn("MTG_UNPRUNED");
    if (!v) { return false; }
    if (g_unpruned_suppressed) { return false; }     // the hand-back plays the SHIPPED search (GameLogger.h)
    if (UnpruneHumanSuppressed()) { return false; }
    return true;
}

// Gates HUMAN PLAY must not open, even under MTG_UNPRUNED. The general rule for un-pruning in the
// play viewer is "the human, not a heuristic, owns the decision" -- but that only applies to a gate
// whose decision the human actually makes THROUGH THE PLAN. TrickTarget is not one: a solo-target
// trick's target is re-asked at RESOLUTION off the board (ResolveSoloTargetTrick's chooser offers
// EVERY own creature, deliberately ignoring TrickTargetCandidates), so opening the gate adds nothing
// the human can pick -- it only fans one enumerated plan per legal target, which
//   (a) re-asks the same target as a redundant "choose the sub-decision" dialog BEFORE the board
//       click the human actually uses (viewer issue #2), and
//   (b) multiplies the plan odometer on exactly the boards this deck builds: measured on
//       Mirrorwing s22 gi21 T4, one committed segment went 30ms -> 2.1s -> 21s -> 31s -> past the
//       viewer's 120s step timeout ("the game timed out", viewer issues #4/#8/#11). With the gate
//       pruned the same eleven segments run 33-74ms each.
// MTG_HUMAN_TRICK_UNPRUNE=1 restores the old behaviour (the definitive with/without A/B still runs
// autonomously, where MTG_HUMAN_PLAY is unset and this exemption is inert).
static bool UnpruneHumanExempt(UnprunedGate g)
{
    static const bool hp      = EnvSet("MTG_HUMAN_PLAY");
    static const bool restore = EnvOn("MTG_HUMAN_TRICK_UNPRUNE");
    if (!hp || restore) { return false; }
    return g == UnprunedGate::TrickTarget;
}

bool DecisionUnpruned(UnprunedGate g)
{
    // Gate probe: record that this gate has a REACHABLE callsite for the current deck (see the probe
    // comment above). Cheap relaxed OR, only when probing; normal runs pay one predictable branch.
    if (g_gate_probe.load(std::memory_order_relaxed))
    { g_gates_queried.fetch_or(1u << static_cast<int>(g), std::memory_order_relaxed); }
    if (UnpruneHumanExempt(g)) { return false; }     // human play never opens this gate (see above)
    if (g_unpruned_suppressed) { return false; }     // hand-back: shipped gates, mask included
    if (DecisionUnpruned()) { return true; }         // global MTG_UNPRUNED opens every gate
    if (UnpruneHumanSuppressed()) { return false; }  // selective mode honours the same suppression
    return (UnpruneMask() >> static_cast<int>(g)) & 1u;
}

std::vector<std::string> RankedTutorCandidates(const DecisionProvider& prov, const GameState& s,
                                               int controller, const CardParams& pp)
{
    std::vector<std::string> full = prov.TutorCandidates(s, controller, pp);
    if (!HumanPlayActive() || !DecisionUnpruned(UnprunedGate::Tutor) || full.size() <= 1) { return full; }
    std::vector<std::string> ranked;
    {
        const bool saved = g_unpruned_suppressed;
        g_unpruned_suppressed = true;                 // the shipped (pruned) ranking
        ranked = prov.TutorCandidates(s, controller, pp);
        g_unpruned_suppressed = saved;
    }
    std::vector<std::string> out;
    out.reserve(full.size());
    for (const std::string& n : ranked)
    {
        if (std::find(full.begin(), full.end(), n) != full.end()
            && std::find(out.begin(), out.end(), n) == out.end()) { out.push_back(n); }
    }
    for (const std::string& n : full)
    { if (std::find(out.begin(), out.end(), n) == out.end()) { out.push_back(n); } }
    return out;
}

bool UseLearnedEval()
{
    static const bool v = EnvOn("MTG_EVAL_MODEL");
    return v;
}

bool UseValueModel()
{
    // ADOPTED default-ON (2026-07-11): the learned value leaf is LP-neutral-within-noise (6-seed d5, TH even
    // net-better) + 1.1-2.7x faster once paired with the hybrid redo + start-gate relaxation (see
    // learned-d0-policy.md). It only engages when a deck ships <deck>.value.json (else m_value_model is
    // empty -> plain search), so decks without a sidecar (e.g. Hinata) are unaffected. Override OFF with
    // MTG_VALUE_MODEL=0/off/no/none/false for A/B against the pure heuristic leaf.
    // Per-job override first (see ValueArm.h): a pooled batch carries H and V jobs in ONE process,
    // so the arm cannot come from a process-wide static. Unset (-1) => the env default below, which
    // keeps every non-batch path byte-identical.
    if (valuearm::t_arm.value_model >= 0) { return valuearm::t_arm.value_model != 0; }
    // Per-deck emulated ladder committing on the HEURISTIC (value_play.ladder == "emulated", commit not
    // "model"): the model is attached for the ladder's warm-ups only (g_force_value_leaf), never as the
    // play leaf -- so the hybrid must not engage. Committing on the model (t_deck_ladder 2) is a value
    // line like the shipped ladder's, and the hybrid's trust escalation must see it.
    if (valuearm::t_deck_ladder == 1) { return false; }
    static const bool v = []{
        const char* e = std::getenv("MTG_VALUE_MODEL");
        if (e && *e)
        {
            const std::string s = e;
            if (s == "0" || s == "off" || s == "no" || s == "none" || s == "false") { return false; }
        }
        return true;
    }();
    return v;
}

// Stage 6: the search tree calls the provider for every deck decision; here the GENERIC
// defaults are minimal (a deck-agnostic baseline) and each archetype subclass holds its
// own heuristics. Archetype detection (SelectDecisionProvider) routes each deck to its
// provider. Byte-identical to the pre-refactor engine: every archetype hook is exclusive
// to one deck family (verified), so a Generic default is only ever exercised by decks
// that don't use that hook.

// ---- GenericProvider: deck-agnostic baseline --------------------------------

// The generic tutor list (see GenericProvider::TutorCandidates below), optionally NONLANDS FIRST
// (library order within each half) -- the Prevent Damage ordering, built in the same walk rather than
// by a second pass that re-looked-up every name by string. Distinct names are tracked by their
// INTERNED pointer (canonical: pointer equality == string equality), a linear scan over <= ~25
// entries instead of a std::unordered_set<std::string> that hashed and heap-allocated every card of
// the zone -- this list is rebuilt on every greedy tutor resolution inside the search's rollouts
// (Prevent Damage perf, 2026-09-28: 5.7% of a d5 game). Same names, same order: byte-identical.
// `defs` (optional): each returned name's definition, index-aligned -- the walk already holds it, and
// a caller that re-reads definitions per rule (Prevent Damage's Wish / Beseech doctrine) would
// otherwise re-hash every name string for each of them.
static std::vector<std::string> GenericTutorList(const GameState& s, int controller,
                                                 const CardParams& pp, bool nonlands_first,
                                                 std::vector<const CardDefinition*>* defs = nullptr)
{
    const Player& ap = s.players[controller];
    // A WISH searches OUTSIDE THE GAME (the sideboard); every other tutor searches the library.
    // Only the zone differs -- type filter, colour filter and ranking are shared.
    // A REGROWTH (tutor_from_graveyard) searches the GRAVEYARD -- same rule, third zone.
    const std::vector<Card>* wish_pool = pp.wish_from_sideboard  ? &ap.sideboard
                                       : pp.tutor_from_graveyard ? &ap.graveyard : nullptr;
    std::vector<std::string>        all;
    std::vector<std::string>        lands;   // nonlands_first only: the second half
    std::vector<const CardDefinition*> land_defs;
    std::vector<const std::string*> seen;
    if (defs != nullptr) { defs->clear(); }
    // Beseech the Queen's land-count cap (0 slack = no param, and no hand walk).
    const int land_slack = pp.tutor_max_mv_is_lands ? TutorLandCapSlack(s, controller) : 0;
    for (const Card& lc : TutorZoneView(ap, wish_pool))
    {
        const CardDefinition* def = CardDatabase::Instance().LookupCached(lc);
        const Card&           card = def ? def->card : lc;
        // Empty tutor_types == no restriction ("search for a card", e.g. Gamble): every card is
        // a legal target. A non-empty filter keeps only the matching types (Idyllic/Enlightened).
        bool type_ok = pp.tutor_types.empty();
        for (const std::string& t : pp.tutor_types)
        { if (CardMatchesTypeName(card, t)) { type_ok = true; break; } }
        if (!CardHasColorNamed(card, pp.tutor_color)) { type_ok = false; }   // Natural Order: green only
        if (!TutorNumericFilterOk(card, pp)) { type_ok = false; }   // Ranger/Recruiter MV/toughness
        if (!TutorLandCapOk(s, controller, card, pp, land_slack)) { type_ok = false; }   // Beseech
        if (!type_ok) { continue; }
        const std::string* key = &lc.m_name.str();
        if (std::find(seen.begin(), seen.end(), key) != seen.end()) { continue; }
        seen.push_back(key);
        // The Prevent Damage partition's own predicate: its name's definition is a land.
        const bool to_lands = nonlands_first && def != nullptr && def->card.IsLand();
        (to_lands ? lands : all).push_back(lc.m_name);
        if (defs != nullptr) { (to_lands ? land_defs : *defs).push_back(def); }
    }
    if (nonlands_first)
    {
        all.insert(all.end(), lands.begin(), lands.end());
        if (defs != nullptr) { defs->insert(defs->end(), land_defs.begin(), land_defs.end()); }
    }
    return all;
}

std::vector<std::string>
GenericProvider::TutorCandidates(const GameState& s, int controller, const CardParams& pp) const
{
    // Search-primary default: return EVERY legal tutor target (distinct library card names
    // matching the tutor's type filter) and let the search pick the best. There is no
    // deck-agnostic tutor heuristic worth encoding (the only narrowing logic -- enabler vs.
    // wincon -- is antilife-specific, so it lives in AntiLifegainProvider). A deck that needs
    // its tutor narrowed for perf adds a provider override via the analyze-deck workflow;
    // until then the general search decides, never whiffs. (Previously returned {} -> a
    // generic tutor silently fetched nothing.)
    std::vector<std::string> all = GenericTutorList(s, controller, pp, /*nonlands_first=*/false);
    // RANKED DEFAULT for put-onto-battlefield tutors (MTG_TUTOR_RANKED_DEFAULT, default off --
    // A/B lever, st993): the tutor-axis width prune and the tc=-1 base pick both assume this
    // list is BEST-FIRST ("the provider orders candidates best-first" -- TutorAxisWidth), but
    // library order is SHUFFLE order. st993's T4 Natural Order drew a library where Craterhoof
    // Behemoth sat 6th of 11 distinct names under width 5: neither the greedy default (which
    // fetched Llanowar Elves) nor any searched variant could reach the deck's win condition, so
    // no projection anywhere priced the T4 kill. For a tutor that CHEATS a card onto the
    // battlefield, mana value is the value being cheated -- rank MV descending (name ascending
    // for a total, shuffle-independent order). The searched variants then simulate the real
    // outcomes; the ranking only has to put the contenders inside the width, not pick the winner.
    static const bool s_ranked = EnvOn("MTG_TUTOR_RANKED_DEFAULT");
    if (s_ranked && pp.tutor_to_battlefield_single)
    {
        std::stable_sort(all.begin(), all.end(),
            [](const std::string& a, const std::string& b)
            {
                const CardDefinition* da = CardDatabase::Instance().Lookup(a);
                const CardDefinition* db = CardDatabase::Instance().Lookup(b);
                const int ma = da ? da->card.m_mana_cost.ManaValue() : 0;
                const int mb = db ? db->card.m_mana_cost.ManaValue() : 0;
                if (ma != mb) { return ma > mb; }
                return a < b;
            });
    }
    return all;
}

std::vector<std::string>
GenericProvider::FetchCandidates(const GameState& s, int controller, const CardParams& fetch_pp) const
{
    // Search-primary default: return EVERY legal fetch target (distinct library land names
    // whose subtypes match the fetchland) and let the search pick. The color-fixing heuristic
    // in ::FetchCandidates is tuned to a specific 4-colour shell (its tiebreaks favour that
    // deck's doubled colours), so it is NOT a safe deck-agnostic default; it stays an archetype
    // override. A generic fetchland deck thus searches its fetch targets rather than whiffing.
    // (Previously returned {} -> a generic fetch paid 1 life and fetched nothing.)
    const Player& ap = s.players[controller];
    std::vector<std::string>        all;
    std::unordered_set<std::string> seen;
    for (const Card& lc : ap.library)
    {
        const CardDefinition* d    = CardDatabase::Instance().LookupCached(lc);
        const Card&           card = d ? d->card : lc;
        if (!card.IsLand()) { continue; }
        bool match = false;
        for (const std::string& want : fetch_pp.fetch_land_types)
        {
            for (const std::string& cs : card.m_subtypes) { if (cs == want) { match = true; break; } }
            if (match) { break; }
        }
        if (match && seen.insert(lc.m_name).second) { all.push_back(lc.m_name); }
    }
    return all;
}

bool GenericProvider::CanAutoFireAltPayload(const GameState&, int, const CardDefinition&) const
{
    return false;   // no free alt-cost payloads in a generic deck.
}

// ---- The GENERIC dig gate (cycling / sacrifice-to-draw) --------------------------------------
//
// USER 2026-09-29: *"Cycling shouldn't be unreachable should it? ... It shouldn't be unreachable,
// but could perhaps be dropped heuristically most of the time."* and *"That should not be
// inaccessible."*
//
// WHAT WAS WRONG. These three hooks used to `return false` unconditionally, and
// AIEngine::UseSurplusLandAbilities / the rollout dig loop / the searched dig axis all bail on the
// first of them. So a deck whose provider did not opt in was NEVER OFFERED a cycle or a
// sacrifice-to-draw by the autonomous engine -- not rejected by a heuristic, never enumerated at
// all. `cycling_cost` is parsed, priced (EffectiveCyclingCost) and fully implemented; the two
// TurnSolver cycling sites are human-play P3/P6, so a person playing through the viewer WAS offered
// the cycle and only the engine was not. The sharpest form: Auras can crack its Horizon Canopy and
// Pirates cannot crack its Fiery Islet, identical `sacrifice_draw_cost: "{1}"` lands, differing
// only in which provider happened to override this. See docs/design/generic-dig-gate.md.
//
// The failure mode was invisible and it corrupts MEASUREMENT, not just play: the card is
// implemented, the parameter parses, the tests pass, and a screen of the card silently prices it
// AS IF THE ABILITY DID NOT EXIST (WhiteKnights round N2 recorded "cycling's option value ...
// cancels to within noise" for a measurement in which cycling never fired once).
//
// `::HasAnyDigSource` is already deck-agnostic and already scans both zones, so there is no new
// detection logic here -- the generic provider simply stops declining to ask. Every deck with no
// cycler and no untapped sac-draw permanent is byte-identical BY CONSTRUCTION (the detector returns
// exactly what the stub returned), which is what makes this safe to validate rather than argue.
//
// MTG_GENERIC_DIG=0 restores the old stubs as a byte-identical A/B escape hatch.
bool GenericProvider::HasAnyDigSource (const GameState& s) const
{
    static const bool on = EnvOn("MTG_GENERIC_DIG", true);
    return on && ::HasAnyDigSource(s);
}

// The DEFAULT/HORIZON heuristic. THE RULE IS THE USER'S, 2026-09-29, in two sentences:
// *"We shouldn't cycle when we have a lot of useful things in hand"* and *"It's mostly to find
// something useful when you have none."* So the generic default is exactly the EMPTY-OF-GAS case
// and nothing else -- not a flood-value dig, not a "spend a surplus land for a card" dig. Digging
// is the line of last resort, taken when there is no line.
//
// This is deliberately NARROWER than AurasProvider's measured gate, which also fires on surplus
// lands alone (>= 4 lands, gas or no gas). That is fine and is the point of a per-deck override:
// Auras' dig source is a land ALREADY IN PLAY whose only other use is mana, so spending it while
// flooded is near-free there. Generalising that to every deck would cycle away a card we could be
// casting, which is what the user just ruled out.
//
// The shared `::ShouldConsiderDig` is NOT reused either: it is Treasure Hunt's gate (Land's Edge
// ammo, retrace engines, cast-the-draw-engine-instead) and reduces, for a deck holding none of
// those, to "dig whenever you control 2 lands" -- which would cycle a creature away on sight.
bool GenericProvider::ShouldConsiderDig(const GameState& s) const
{
    if (!HasAnyDigSource(s)) { return false; }
    // Unpruned audit: consider a dig whenever a dig source exists, instead of this judgement.
    if (DecisionUnpruned(UnprunedGate::Dig)) { return true; }

    const Player& ap = s.ActivePlayer();

    int lands = 0;
    bool sac_in_play      = false;   // any untapped sac-draw permanent we control
    bool sac_src_is_land  = false;   // ...and it is a LAND, so digging with it costs us a land
    for (const Permanent& p : s.battlefield)
    {
        if (p.controller_index != s.active_player_index) { continue; }
        if (p.card.IsLand()) { ++lands; }
        if (p.tapped) { continue; }
        const CardDefinition* d = CardDatabase::Instance().LookupCached(p.card);
        if (d && d->params.sacrifice_draw_cost.has_value())
        {
            sac_in_play = true;
            if (d->card.IsLand()) { sac_src_is_land = true; }
        }
    }
    // Never strand ourselves on mana, measured AFTER the dig: a sac-draw LAND is one of the lands
    // just counted, so digging with it leaves `lands - 1`. Checking the pre-dig count would let a
    // two-land board sacrifice its way down to one -- the exact failure the floor exists to stop.
    if (lands - (sac_src_is_land ? 1 : 0) < 2) { return false; }

    // "A lot of useful things in hand" == anything castable. One castable nonland is enough to
    // prefer casting it: the mana a dig would spend is the mana that card needs, and the card the
    // dig would throw away may BE that card. Deliberately MV-only (no colour check), matching the
    // rest of the provider's cheap castability probes -- erring toward NOT digging is the safe
    // direction for a gate whose whole job is to stay out of the way.
    for (const Card& c : ap.hand)
    {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(c);
        if (!d || d->card.IsLand()) { continue; }
        if (d->card.m_mana_cost.ManaValue() <= lands) { return false; }
    }

    // Nothing castable. Two carve-outs remain, BOTH about not cycling away a land we still need as
    // a land -- because a land you have not made your drop with yet is one of the "useful things in
    // hand" the rule is protecting, it just pays off a turn later than a spell does:
    //
    //   (a) the land drop is still OPEN this turn -- play it instead; a land in play may make the
    //       hand's uncastable spells castable, which is the dig's own goal reached without paying;
    //   (b) it is the LAST land in hand -- cycling it gives up NEXT turn's drop too. MEASURED, and
    //       this is the clause the overnight tier bought: without it fivecolour ran +0.0094 (d3) /
    //       +0.0092 (d5) on 8 of 8 searched cells, while IMPROVING at d0 (-0.0050) -- the shape of
    //       a heuristic that is right about the card and wrong about the mana. All of that deck's
    //       digs were hand-cycled Triomes at {3}, i.e. tapping out early in a five-colour manabase
    //       to draw one card and skip a land drop. th and pirates gained at every depth throughout.
    //
    // A sac-draw permanent already in play competes with neither drop, so it is exempt from both.
    if (!sac_in_play)
    {
        bool cycling_nonland = false;
        int  lands_in_hand   = 0;
        for (const Card& c : ap.hand)
        {
            const CardDefinition* d = CardDatabase::Instance().LookupCached(c);
            if (!d) { continue; }
            if (d->card.IsLand()) { ++lands_in_hand; continue; }
            if (d->params.cycling_cost.has_value()) { cycling_nonland = true; }
        }
        if (!cycling_nonland
            && (ap.lands_played_this_turn < ap.LandDropsAvailable() || lands_in_hand <= 1))
        { return false; }
    }
    return true;
}

std::string GenericProvider::SelectDigSource(const GameState& s, const ManaPool& pool,
                                             bool& out_is_sac) const
{
    out_is_sac = false;
    if (!HasAnyDigSource(s)) { return {}; }
    // The shared helper, exactly as AurasProvider and TreasureHuntProvider use it: cheapest-first
    // is NOT what it does -- it takes the first AFFORDABLE source in zone order, hand cycling
    // before battlefield sac-draw, which is deterministic and keeps the executor, the rollout and
    // the human-play offer probe reading one ranking. A deck that wants a real ranking overrides
    // this the way FluctuatorProvider does.
    return ::SelectDigSource(s, pool, out_is_sac);
}

int GenericProvider::LandsEdgeFireCount(const GameState&, int) const
{
    return 0;   // only Land's Edge decks activate this; archetype overrides.
}

bool GenericProvider::WantVialCharge(const GameState& s, const Permanent& vial) const
{
    // The hand-aware charge policy is the ROOT default, not an archetype opt-in (adopted 2026-08-18,
    // user-directed). The previous `return false` was NOT a guard: every call site already gates on
    // params.upkeep_adds_charge (AIEngine::ChargeRemainingVialsHeuristic, AIEngine::DecideVialCharge,
    // TurnSolver's SimulateBeginningPhase), so this hook is only ever consulted for a real charge
    // permanent and is inert for every deck without one. Its only live effect was to FREEZE the Vial
    // in any deck routed to a non-VialProvider archetype -- Goblins (4x Aether Vial) never gained a
    // counter in its life, and Minotaur is the same latent case.
    //
    // It also poisoned the search: the ROLLOUT models future upkeeps through this same hook, so both
    // arms of the old out-of-band probe rolled out under "never charge again" and tied at every
    // upkeep (`win(heur)=9 win(alt)=9`), leaving the Vial at 0 counters forever. Held-out measurement
    // of the fix: goblins -0.2095 summed over 12 cases (342 games faster, 9 slower over 16,000);
    // knights/slivers byte-identical (they already routed to VialProvider, which had this policy).
    // See docs/design/searched-vial-charge.md.
    return ::WantVialCharge(s, vial);
}

bool GenericProvider::ScryKeepOnTop(const GameState& s, const Card& top_card) const
{
    // Generic scry/surveil keep: keep nonland spells; keep a land only while fewer than
    // two lands are in play. (The Treasure Hunt provider adds the DrawUntilNonland clause.)
    const CardDefinition* tdef = CardDatabase::Instance().LookupCached(top_card);
    bool is_land = tdef ? tdef->card.IsLand() : top_card.IsLand();
    if (!is_land) { return true; }
    int lands_in_play = 0;
    for (const Permanent& p : s.battlefield)
    {
        if (p.controller_index == s.active_player_index && p.card.IsLand()) { ++lands_in_play; }
    }
    return lands_in_play < 2;
}

bool GenericProvider::CastEnablerFirst(const GameState&, const std::string& card_name) const
{
    // Param-derived ENABLES edge (docs/design/card-dependency-map.md): a lifegain->loss
    // enabler casts + resolves before its payloads so a same-turn payload sees the flip
    // active. Was an AntiLifegainProvider override; the test is a pure card-parameter check
    // with no archetype knowledge, so it belongs here (identical set, ordering audit item 3:
    // the generic default now agrees with the generic CastOrderRank 0 tier below).
    return ::IsLifegainToLossCard(card_name);
}

bool GenericProvider::DiscardLandsFirst(const GameState&) const
{
    return false;   // generic: discard the highest-MV card, not lands.
}

// The BASE cleanup-discard rule for every provider (see DecisionProvider::CleanupDiscardCandidates).
// Lives on the base class, not GenericProvider, because it is the shared default an archetype
// narrows or widens rather than a generic-deck-only answer.
//
// Returns the FULL ranking now, not just the winner -- index 0 is still the historical single pick,
// so this stays byte-identical for every caller that takes the front. The tail is what lets
// AIEngine::ChooseDiscard tie-break among win-optimal discards and what the searched rollout axis
// fans out over. Must NOT call SelectCleanupDiscardIndex: that routes through this hook (so a
// provider override reaches every caller), which would recurse.
// Does shedding a card from HAND pay for itself right now?
//
// The duplicate-legend prune below rests on the cast being a TIE -- the copy dies to the legend
// rule, the board is unchanged -- and that rests in turn on an UNSTATED premise: that the card
// leaving hand is worth nothing. For a deck whose payoff is a hand-size condition it is worth a
// great deal. Neheb, the Worthy gives "Minotaurs you control get +2/+0" only while its controller
// holds one or fewer cards (hand_size_anthem_max), so while that anthem is OFF the spare Neheb is
// not a tie at all: it converts a stranded card into a board-wide pump, and the duplicate dying to
// the legend rule is the POINT rather than the cost.
//
// (User-reported from logs/play/rejections/Minotaur_cod_s3_gi2_t5.json: hand of three, a Neheb and
// a Ragemonger already in play, and the two Minotaur casts leave exactly one card -- switching the
// anthem on across the whole board. The prune dropped that line as pointless.)
//
// PARAM-DRIVEN, never keyed on a card name, so any future hand-size payoff gets this for free and a
// deckbuilding swap that drops Neheb loses it automatically. Inert everywhere else: no other card
// in cards.json carries hand_size_anthem_max, so this scan finds nothing and the prune is exactly
// as before for every other deck.
//
// Deliberately NOT "does THIS cast cross the threshold". The hook is asked about one card at a
// time, while crossing the threshold usually takes the turn's whole cast sequence (two casts, in
// the reported game) -- so a single-cast crossing test would prune precisely the line that
// motivated the fix. Being generous costs one extra plan variant in the states where an anthem is
// live but unmet; being strict costs a real line, and this hook's own comment records that the
// failure direction that matters is pruning a GOOD cast.
static bool HandShedIsPayoff(const GameState& s, int controller)
{
    const int hand_size = static_cast<int>(s.players[controller].hand.size());
    for (const Permanent& p : s.battlefield)
    {
        if (p.controller_index != controller) { continue; }
        const CardDefinition* d = CardDatabase::Instance().LookupCached(p.card);
        if (!d || d->params.hand_size_anthem_max < 0) { continue; }
        // A gate with no bonus behind it is not a payoff.
        if (d->params.hand_size_anthem_power == 0 && d->params.hand_size_anthem_tough == 0)
        { continue; }
        // Anthem currently OFF and the hand is what is holding it off -> shedding pays.
        if (hand_size > d->params.hand_size_anthem_max) { return true; }
    }
    return false;
}

// Would a creature with THIS card's types entering under our control -- or dying, which is what the
// legend rule immediately does to one of the two copies -- cause anything at all?
//
// The duplicate-legend prune's whole premise is that the cast is a TIE: the copy resolves, the
// legend rule kills one, the board is unchanged. That premise is a claim about the BOARD, and the
// template whitelist cannot see the board. Two decks in this repo break it outright:
//
//   * Angels. A second Lyra Dawnbringer (template lord_effect, so whitelisted) entering is
//     "another Angel", so Righteous Valkyrie gains life equal to its TOUGHNESS, Bishop of Wings
//     gains 4 and each Seraph Sanctuary gains 1 -- and per the official Archangel of Thune ruling
//     those are SEPARATE life-gain events (CR 119.10), each of which puts a +1/+1 counter on the
//     whole team through every Archangel of Thune and every Lyra, Archangel of Dawn. Then the
//     legend-rule death is an Angel dying, so Bishop of Wings leaves a 1/1 flying Spirit behind.
//   * Dragons / Dragonstorm. A second Lathliss, Dragon Queen (template vanilla_creature, so
//     whitelisted) is "another nontoken Dragon you control", so the RESIDENT Lathliss creates a
//     5/5 flier. The duplicate cast buys a 5/5 for {4}{R}{R} and the legend rule is just the price.
//
// Note what that second case shows: `vanilla_creature` is NOT "a body and nothing else". It is the
// base template that params decorate, and Lathliss carries a full enter-watcher in params. So the
// template test was never a sound proxy for enter-inertness even for the card itself.
//
// ENUMERATED IN THE GENEROUS DIRECTION ON PURPOSE, and subtype filters are honoured but never
// required: a field missed here costs one extra plan variant in a state where nothing fires, while
// the behaviour it replaces cost a real line. Same failure-direction argument the hook comment in
// DecisionProvider.h already makes -- it just applied it to the wrong question.
static bool DuplicateEntryOrDeathHasUpside(const GameState& s, int controller,
                                           const CardDefinition& def)
{
    auto one = [&](const std::string& want)
    {
        if (want.empty()) { return true; }               // unfiltered watcher -> fires on anything
        for (const std::string& cs : def.card.m_subtypes) { if (cs == want) { return true; } }
        return false;
    };
    auto any = [&](const std::vector<std::string>& want)
    {
        if (want.empty()) { return true; }
        for (const std::string& w : want) { if (one(w)) { return true; } }
        return false;
    };
    for (const Permanent& p : s.battlefield)
    {
        if (p.controller_index != controller) { continue; }
        const CardDefinition* d = CardDatabase::Instance().LookupCached(p.card);
        if (!d) { continue; }
        const CardParams& wp = d->params;
        // --- fires when another creature we control ENTERS ---
        if (wp.any_creature_enters_lifegain > 0) { return true; }
        if (any(wp.enters_watch_subtypes)
            && (wp.own_creature_enters_lifegain > 0
                || wp.own_creature_enters_lifegain_toughness
                || wp.own_creature_enters_self_counters > 0
                || wp.own_creature_enters_draw > 0
                || wp.own_creature_enters_opp_life_loss > 0))   // Forerunner of the Coalition
        { return true; }
        // Giada-class CR 614 as-enters replacement (counters on the entering Angel).
        if (wp.other_subtype_enters_counters_per_each > 0
            && one(wp.other_subtype_enters_counters_subtype))
        { return true; }
        // Metallic Mimic: a duplicate of a card carrying Mimic's CHOSEN type enters with a counter.
        if (wp.other_chosen_subtype_enters_counters > 0
            && def.card.m_subtypes.HasId(p.chosen_subtype_id))
        { return true; }
        // Lathliss-class "whenever another <subtype> you control enters, create a token".
        if (wp.etb_other_subtype_creates_tokens && one(wp.etb_token_requires_subtype))
        { return true; }
        // --- fires when a creature we control DIES; the legend rule is a death ---
        if (wp.own_creature_dies_lifegain > 0) { return true; }
        if ((wp.dies_trigger_creates_tokens > 0 || wp.dies_trigger_damage > 0
             || wp.dies_trigger_impulse_exile)
            && one(wp.dies_watch_subtype))
        { return true; }
    }
    return false;
}

// Prune casting a legendary permanent we already control a copy of, when that card does nothing on
// entry. See the hook comment in DecisionProvider.h for why the whitelist is positive rather than
// an etb_* enumeration (the failure direction matters: a missed field would prune a GOOD cast).
int DecisionProvider::EtbDestroyK(const GameState& s, int controller, const CardDefinition& def) const
{
    return ::ProjectEtbDestroyK(s, controller, def);
}

int DecisionProvider::SacExpendabilityRank(const GameState& s, const Permanent& v, int source_id,
                                           const std::vector<int>* doomed_creators) const
{
    (void)s;
    return ::DefaultSacExpendabilityRank(v, source_id, doomed_creators);
}

std::vector<std::string> DecisionProvider::ActivationDiscardCandidates(
    const GameState& s, const CardDefinition& src_def, const std::vector<std::string>& names) const
{
    (void)src_def;
    // The provider's own cleanup ranking (most expendable first), mapped onto the classes by first
    // appearance; a name the ranking never lists keeps its hand order at the back. Order only.
    const std::vector<int> rank = CleanupDiscardCandidates(s, nullptr);
    const Player& ap = s.players[s.active_player_index];
    std::vector<std::string> out;
    out.reserve(names.size());
    for (const int hi : rank)
    {
        if (hi < 0 || hi >= static_cast<int>(ap.hand.size())) { continue; }
        const std::string& nm = ap.hand[static_cast<std::size_t>(hi)].m_name.str();
        if (std::find(names.begin(), names.end(), nm) == names.end()) { continue; }
        if (std::find(out.begin(), out.end(), nm) == out.end()) { out.push_back(nm); }
    }
    for (const std::string& nm : names)
    { if (std::find(out.begin(), out.end(), nm) == out.end()) { out.push_back(nm); } }
    return out;
}

int DecisionProvider::MadnessCastDefault(const GameState& s, int controller, const CardDefinition& def,
                                         const std::vector<MadnessOption>& opts, MadnessWindow w) const
{
    (void)s; (void)controller; (void)def; (void)w;
    return opts.empty() ? -1 : 0;   // the dominance rule (see the declaration)
}

std::vector<int> DecisionProvider::SacOutletVictimCandidates(
    const GameState& s, const Permanent& src, const std::vector<int>& reps) const
{
    std::vector<int> out = reps;
    const std::vector<int> doomed = DoomedTokenCreators(s);
    std::stable_sort(out.begin(), out.end(), [&](int a, int b)
    {
        return SacExpendabilityRank(s, s.battlefield[static_cast<std::size_t>(a)], src.card.m_number, &doomed)
             < SacExpendabilityRank(s, s.battlefield[static_cast<std::size_t>(b)], src.card.m_number, &doomed);
    });
    return out;
}

int DecisionProvider::EtbDestroyVictimClass(const GameState& s, int controller, const Permanent& q) const
{
    return ::DefaultEtbDestroyVictimClass(s, controller, q);
}

TopDisposition DecisionProvider::TopDispositionPick(const GameState& s, const std::vector<Card>& looked,
                                                    LookKind kind, int keep_decision) const
{
    return ::DefaultTopDisposition(s, looked, kind, keep_decision);
}

std::vector<std::string> DecisionProvider::ReviveCandidates(const GameState& s, int controller,
                                                            int max_power, int max_returns) const
{
    (void)max_returns;   // the consumer reads the first max_returns entries
    struct Cand { int mv; std::string nm; };
    std::vector<Cand> cands;
    for (const Card& gc : s.players[controller].graveyard)
    {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(gc);
        const Card& card = d ? d->card : gc;
        if (!card.IsCreature() || card.m_power.value_or(0) > max_power) { continue; }
        cands.push_back(Cand{card.m_mana_cost.ManaValue(), gc.m_name.str()});
    }
    std::sort(cands.begin(), cands.end(), [](const Cand& a, const Cand& b)
              { if (a.mv != b.mv) { return a.mv > b.mv; } return a.nm < b.nm; });
    std::vector<std::string> order;
    for (const Cand& c : cands) { order.push_back(c.nm); }
    return order;
}

bool DecisionProvider::OfferDuplicateLegendCast(const GameState& s, int controller,
                                                const CardDefinition& def) const
{
    // ADOPTED (user's idea, user-approved). MTG_PRUNE_DUP_LEGEND=0 restores the old behaviour.
    // MEASURED (test/dup_legend_prune_ab.sh, fresh seeds 41041..46046):
    //     hinata_d0  36000 games/arm  7.1199 -> 7.0782  -0.0417  t=-158  6/6 seeds
    //     hinata_d3/d5 -0.0058 each;  goblins_d0 +0.0000 (Muxus control);  knights_d0 +0.0000
    // ~200x the two rankings adopted the same day. It was never a modelling bug: the legend rule is
    // enforced immediately in both paths, so the duplicate dies and board value is unchanged --
    // which makes the cast a TIE, and a tie-break took it 109 times per 600 d0 games.
    static const bool s_prune = EnvOn("MTG_PRUNE_DUP_LEGEND", true);
    if (!s_prune) { return true; }

    if (!def.card.HasSupertype(Supertype::Legendary)) { return true; }
    // Enter-inert templates ONLY: a body (plus, for a lord, a continuous effect). Anything else --
    // every `custom` card, notably Muxus with its enter-reveal -- keeps being offered.
    if (def.tmpl != CardTemplate::VanillaCreature && def.tmpl != CardTemplate::LordEffect)
    { return true; }
    // A copy already on OUR battlefield is what makes the new one die on resolution. (An opponent's
    // copy is irrelevant: the legend rule is per-controller.)
    for (const Permanent& p : s.battlefield)
    {
        if (p.controller_index == controller && p.card.m_name == def.card.m_name)
        {
            // ...unless the ENTRY or the legend-rule DEATH itself has upside, in which case the
            // cast was never the tie this prune assumes (see DuplicateEntryOrDeathHasUpside above:
            // a second Lathliss is a 5/5 Dragon token, a second Lyra Dawnbringer is three life-gain
            // events, a team of +1/+1 counters and a Spirit).
            // ...unless emptying the hand is itself the payoff (see HandShedIsPayoff above): then
            // the cast is not the tie this prune assumes, and dropping it loses a real line.
            //
            // AUTONOMOUS GREEDY PLAY KEEPS THE ORIGINAL PRUNE (user, 2026-08-29: "turn it on all of
            // the time, but have d0 ignore that option"). The widened option set is only worth
            // offering where something can WEIGH it, which is SetSearchedPlay's own stated rationale
            // -- "at depth 0 an extra plan variant is not a search, it is just a different fixed rule
            // chosen by enumeration order". Measured exactly that way: at d0 the greedy scorer takes
            // the duplicate on static value and loses 3 games across smoke+regression (each of which
            // wins its original turn again at d3/d5, and none of which is budget -- d0 has no search
            // for a budget to buy); at d3/d5 the score never moved in either direction.
            //
            // HumanPlayActive() is checked FIRST and separately, because the viewer plays at
            // depth 0 BY CONSTRUCTION -- at depth > 0 the engine's bottoming/mulligan rollouts would
            // replay hypothetical games through the same external chooser and start asking the human
            // to play imaginary games (tools/play/server.js). So gating on depth alone would restore
            // exactly the rejection this fix exists to remove; the human path is d0 without being
            // greedy, since a person, not the static scorer, is choosing.
            if (!HumanPlayActive() && !g_searched_play) { return false; }
            if (DuplicateEntryOrDeathHasUpside(s, controller, def)) { return true; }
            // ...and, for searched/human play only, offer the duplicate whenever its ENTRY or its
            // legend-rule DEATH has upside (DuplicateEntryOrDeathHasUpside above: a second Lathliss
            // is a 5/5 Dragon token; a second Lyra Dawnbringer is three life-gain events, a
            // team-wide counter from every Archangel of Thune and a Bishop of Wings Spirit).
            //
            // BELOW the greedy gate, and that placement is MEASURED, not assumed. Offering it at
            // autonomous d0 too reproduced the 2026-08-29 carve-out exactly -- smoke [searched]
            // 0 slower / 1 faster / 23 play-changed, but [d0] 7 slower / 4 faster / 47
            // play-changed. Same cause the carve-out already records: at depth 0 an extra plan
            // variant is not searched, it is picked by enumeration order, and the static scorer
            // takes a body it cannot see the legend rule about to eat. Gated here, d0 stays
            // byte-identical and only the searched tiers move.
            return HandShedIsPayoff(s, controller);
        }
    }
    return true;
}

// CleanupDiscardRankingWithOrder plus the MTG_SHED_STATS firing census (ShedStats::CountPolicy): how
// often a deck policy's index 0 differs from the generic fallback's -- the ranking its =0 hatch
// restores. A byte-identical A/B on a policy is only believable next to a non-zero count. Off by
// default = one static bool read on the shipped path.
static std::vector<int> CleanupDiscardRankingCounted(const GameState& s,
                                                     const std::vector<std::string>* required_pieces,
                                                     const std::vector<int>& shed)
{
    if (ShedStats::Enabled())
    {
        const std::vector<int> out = CleanupDiscardRankingWithOrder(s, required_pieces, shed);
        const std::vector<int> gen = CleanupDiscardRanking(s, required_pieces);
        ShedStats::CountPolicy(!out.empty() && !gen.empty() && out.front() != gen.front());
        return out;
    }
    return CleanupDiscardRankingWithOrder(s, required_pieces, shed);
}

// ---- discard_dist: the shared distance-to-castable model -------------------------------------------
// docs/design/discard-distance-model.md; the API and its approximations are documented in
// DecisionProviders.h. Used by the USER-settled discard buckets behind MTG_DISCARD_DIST_MODEL.
namespace discard_dist
{
double HyperAtLeast(int N, int K, int n, int k)
{
    if (k <= 0) { return 1.0; }
    if (N <= 0 || K <= 0 || n <= 0) { return 0.0; }
    n = std::min(n, N);
    K = std::min(K, N);
    if (k > std::min(n, K)) { return 0.0; }
    auto choose = [](int a, int b) -> double
    {
        if (b < 0 || b > a) { return 0.0; }
        double r = 1.0;
        for (int i = 1; i <= b; ++i) { r = r * static_cast<double>(a - b + i) / static_cast<double>(i); }
        return r;
    };
    double hits = 0.0;
    for (int x = k; x <= std::min(n, K); ++x) { hits += choose(K, x) * choose(N - K, n - x); }
    return std::min(1.0, hits / choose(N, n));
}

static unsigned ColourBits(const CardDefinition* d)
{
    unsigned bits = 0;
    if (d == nullptr) { return 0; }
    for (Color c : d->params.produces)
    { if (c != Color::Colorless) { bits |= 1u << static_cast<int>(c); } }
    return bits;
}

LandDrop LandDropOf(const CardDefinition* d)
{
    LandDrop ld;
    if (d == nullptr) { return ld; }
    ld.mana    = std::max(1, d->params.produces_amount);
    ld.colours = ColourBits(d);
    ld.tapped  = d->params.enters_tapped;
    return ld;
}

Census BuildCensus(const GameState& s, int me)
{
    Census c;
    for (const Permanent& p : s.battlefield)
    {
        if (p.controller_index != me) { continue; }
        const CardDefinition* d = CardDatabase::Instance().LookupCached(p.card);
        if (d == nullptr) { continue; }
        const bool land = p.card.IsLand();
        if (!land && !d->params.mana_rock && d->tmpl != CardTemplate::ManaDork) { continue; }
        c.board_mana += std::max(1, d->params.produces_amount);
        const unsigned bits = ColourBits(d);
        for (int k = 0; k < 5; ++k) { if (bits & (1u << k)) { ++c.board_src[static_cast<std::size_t>(k)]; } }
    }
    const Player& pl = s.players[static_cast<std::size_t>(me)];
    c.lib_n = static_cast<int>(pl.library.size());
    for (const Card& lc : pl.library)
    {
        if (!CleanupDiscardIsLand(lc)) { continue; }
        ++c.lib_lands;
        const unsigned bits = ColourBits(CardDatabase::Instance().LookupCached(lc));
        for (int k = 0; k < 5; ++k) { if (bits & (1u << k)) { ++c.lib_src[static_cast<std::size_t>(k)]; } }
    }
    return c;
}

std::array<double, kHorizon> CastProbByTurn(const Census& c, int mana, const std::array<int, 5>& pips,
                                            const std::vector<LandDrop>& kept,
                                            const std::array<int, kHorizon>* extra,
                                            const ColourCredit* extra_src)
{
    // Kept lands are played best-first FOR THIS QUERY: a land supplying a colour the board is short of,
    // then an untapped one, then the most mana. At most kHorizon of them matter.
    unsigned short_bits = 0;
    for (int k = 0; k < 5; ++k)
    {
        if (pips[static_cast<std::size_t>(k)] > c.board_src[static_cast<std::size_t>(k)]) { short_bits |= 1u << k; }
    }
    std::array<LandDrop, kHorizon> drop{};
    int h = 0;
    {
        std::vector<char> used(kept.size(), 0);
        for (; h < kHorizon && h < static_cast<int>(kept.size()); ++h)
        {
            int best = -1;
            for (std::size_t i = 0; i < kept.size(); ++i)
            {
                if (used[i]) { continue; }
                if (best < 0) { best = static_cast<int>(i); continue; }
                const LandDrop& a = kept[i];
                const LandDrop& b = kept[static_cast<std::size_t>(best)];
                const bool ha = (a.colours & short_bits) != 0, hb = (b.colours & short_bits) != 0;
                if (ha != hb) { if (ha) { best = static_cast<int>(i); } continue; }
                if (a.tapped != b.tapped) { if (!a.tapped) { best = static_cast<int>(i); } continue; }
                if (a.mana > b.mana) { best = static_cast<int>(i); }
            }
            used[static_cast<std::size_t>(best)] = 1;
            drop[static_cast<std::size_t>(h)] = kept[static_cast<std::size_t>(best)];
        }
    }
    std::array<double, kHorizon> out{};
    double prev = 0.0;
    for (int t = 1; t <= kHorizon; ++t)
    {
        const int played = std::min(t, h);          // kept lands played on turns 1..played
        int mana_t = c.board_mana + (extra != nullptr ? (*extra)[static_cast<std::size_t>(t - 1)] : 0);
        std::array<int, 5> col_t = c.board_src;
        if (extra_src != nullptr)
        {
            for (int k = 0; k < 5; ++k)
            { col_t[static_cast<std::size_t>(k)] += (*extra_src)[static_cast<std::size_t>(t - 1)][static_cast<std::size_t>(k)]; }
        }
        for (int i = 0; i < played; ++i)
        {
            const LandDrop& ld = drop[static_cast<std::size_t>(i)];
            if (i + 1 == t && ld.tapped) { continue; }   // played this turn, enters tapped: nothing yet
            mana_t += ld.mana;
            for (int k = 0; k < 5; ++k) { if (ld.colours & (1u << k)) { ++col_t[static_cast<std::size_t>(k)]; } }
        }
        const int free_drops = t - played;            // turns whose land drop needs a DRAWN land
        double p = 1.0;
        const int need = mana - mana_t;                // each drawn land counted as 1 mana, untapped
        if (need > 0) { p = need > free_drops ? 0.0 : HyperAtLeast(c.lib_n, c.lib_lands, t, need); }
        for (int k = 0; k < 5 && p > 0.0; ++k)
        {
            const int need_c = pips[static_cast<std::size_t>(k)] - col_t[static_cast<std::size_t>(k)];
            if (need_c <= 0) { continue; }
            p *= need_c > free_drops ? 0.0 : HyperAtLeast(c.lib_n, c.lib_src[static_cast<std::size_t>(k)], t, need_c);
        }
        p = std::max(p, prev);                         // castable by t implies castable by t+1
        out[static_cast<std::size_t>(t - 1)] = p;
        prev = p;
    }
    return out;
}

double CastFactor(const std::array<double, kHorizon>& p_by_turn)
{
    double f = 0.0, prev = 0.0, g = 1.0;
    for (double p : p_by_turn) { f += (p - prev) * g; prev = p; g *= kGamma; }
    return f + (1.0 - prev) * 0.02 * g;               // the stranded still order by value
}

double CastFactorFor(const Census& c, const CardDefinition& d, const std::vector<LandDrop>& kept,
                     int mana_override, const std::array<int, kHorizon>* extra,
                     const ColourCredit* extra_src)
{
    const ManaCost& mc = d.card.m_mana_cost;
    const std::array<int, 5> pips = { mc.white, mc.blue, mc.black, mc.red, mc.green };
    const int mana = mana_override >= 0 ? mana_override : mc.ManaValue();
    return CastFactor(CastProbByTurn(c, mana, pips, kept, extra, extra_src));
}
}   // namespace discard_dist

std::vector<int> DecisionProvider::CleanupDiscardCandidates(
    const GameState& s, const std::vector<std::string>* required_pieces) const
{
    return CleanupDiscardRanking(s, required_pieces);
}

// See DecisionProvider.h. The shed order ranks the ACTIVE player's hand -- the only caster in the
// goldfish, and the only player whose Brainstorm resolves -- so it is read only when `controller` is
// active; otherwise (never reached today) the hand order stands. Indices are de-duplicated and every
// hand index the shed order omits is appended in hand order, so the ranking is always total.
std::vector<int> DecisionProvider::PutBackRanking(const GameState& s, int controller) const
{
    const int n = static_cast<int>(s.players[controller].hand.size());
    std::vector<int> out;
    std::vector<char> seen(static_cast<std::size_t>(n), 0);
    if (controller == s.active_player_index)
    {
        for (int i : CleanupDiscardShedOrder(s, s.m_required_pieces))
        {
            if (i < 0 || i >= n || seen[static_cast<std::size_t>(i)]) { continue; }
            seen[static_cast<std::size_t>(i)] = 1;
            out.push_back(i);
        }
    }
    for (int i = 0; i < n; ++i) { if (!seen[static_cast<std::size_t>(i)]) { out.push_back(i); } }
    return out;
}

// DIAGNOSTIC ONLY (MTG_DISCARD_SHED_VERIFY, see CleanupDiscardShed): the per-shed loop the rollout
// cleanup used to run -- ask, shed, rebuild the hand, ask again -- re-derived on a scratch copy of
// the state so the one-consultation answer can be checked against it. Reported as card NAMES: the
// loop's own indices shift under it as cards are erased, which is exactly the bookkeeping this
// retires. Off by default and never on a shipped path; it copies a GameState and re-ranks per shed,
// which is strictly more work than either form.
std::vector<std::string> CleanupDiscardShedLoopReference(
    const GameState& state, const std::vector<std::string>* required_pieces,
    int count, int pinned_first, bool invert, bool staged_exempt)
{
    std::vector<std::string> out;
    GameState copy = state;
    Player& ap = copy.players[copy.active_player_index];
    int pin = pinned_first;
    for (int k = 0; k < count; ++k)
    {
        const std::vector<int> cd =
            ResolveProvider(copy).CleanupDiscardCandidates(copy, required_pieces);
        if (cd.empty()) { break; }
        std::size_t pick = 0;
        if (pin > 0)     { pick = std::min(static_cast<std::size_t>(pin), cd.size() - 1); }
        else if (invert) { pick = cd.size() - 1; }
        pin = -1;
        int idx = cd[pick];
        const int hand_n = static_cast<int>(ap.hand.size());
        if (staged_exempt && idx >= 0 && idx < hand_n && ap.hand[idx].m_is_staged)
        {
            idx = -1;
            for (int j = 0; j < hand_n; ++j)
            { if (!ap.hand[j].m_is_staged) { idx = j; break; } }
            if (idx < 0) { break; }
        }
        if (idx < 0 || idx >= hand_n) { break; }
        out.push_back(ap.hand[static_cast<std::size_t>(idx)].m_name.str());
        if (!MaybeReplaceGraveyardWithLibraryShuffle(copy, copy.active_player_index, ap.hand[idx]))
        { ap.graveyard.push_back(ap.hand[idx]); }
        ap.hand.erase(ap.hand.begin() + idx);
    }
    return out;
}

// The BASE Goblin Lackey put rule (see DecisionProvider::CombatCheatCandidates). Highest MV, ties
// by power, then by lowest card number -- exactly the ordering FireCombatDamageCheatIntoPlay
// computed inline before the hook existed, so index 0 reproduces the historical single pick and
// this port is byte-identical.
//
// The FULL ranked list is returned (not just the winner) because this decision wants a search: the
// put is free and lands after attackers are declared, so it is an Aether Vial-shaped "what do I want
// on board" choice, and MV is only a proxy for that. Ranked-best-first means a search over the axis
// inherits the historical pick as its tie-break winner.
// TEMPORARY A/B selector (MTG_LACKEY_RANK), per the heuristic-optimization loop: expose the rival
// orderings behind a runtime lever, sweep, report, then delete the losers. "mv" is the shipped rule.
//   mv     -- highest MV, ties by power, then lowest card number  (the historical engine rule)
//   low    -- LOWEST MV first. Deliberate anti-heuristic: it exists to BOUND the headroom. If the
//             best and worst orderings play nearly the same, the choice does not matter much and a
//             search axis over it cannot repay its cost, whatever ranking wins.
//   pow    -- highest power first (is the body what matters, or the mana you skipped paying?)
//   uncast -- highest MV among the cards you could NOT cast right now, then the rest by MV. The
//             put is free and lands after attackers are declared, so its whole value is the mana you
//             never paid; a card you were going to cast anyway converts far less of that.
enum class LackeyRank { Mv, Low, Pow, Uncast };
static LackeyRank LackeyRankMode()
{
    static const LackeyRank m = []() -> LackeyRank {
        const char* v = std::getenv("MTG_LACKEY_RANK");
        if (v == nullptr || *v == '\0') { return LackeyRank::Mv; }
        const std::string s = v;
        if (s == "low")    { return LackeyRank::Low; }
        if (s == "pow")    { return LackeyRank::Pow; }
        if (s == "uncast") { return LackeyRank::Uncast; }
        return LackeyRank::Mv;
    }();
    return m;
}

std::vector<int> DecisionProvider::CombatCheatCandidates(
    const GameState& s, int /*controller*/, const CardDefinition& /*source*/,
    const std::vector<int>& hand_indices) const
{
    const Player& ap = s.players[s.active_player_index];
    const LackeyRank mode = LackeyRankMode();
    // LETHAL FIRST (MTG_LACKEY_LETHAL, default ON). The put resolves in the combat-DAMAGE step, so a
    // creature whose ETB deals damage closes the game THIS turn, while any other body cannot attack
    // until the next one -- a full turn of the primary metric. Param-driven (etb_damage_any), not
    // card-named, so any deck with an ETB-damage creature in the cheat pool gets it.
    //
    // This is an ORDERING key, not a forced choice: it makes the lethal candidate index 0 so the
    // searched axis always scores it, and the search may still prefer another line.
    const int opp_life = s.players[1 - s.active_player_index].life;
    static const bool s_lethal_first = EnvOn("MTG_LACKEY_LETHAL", true);
    auto lethal_now = [&](int h) -> bool {
        if (!s_lethal_first) { return false; }
        const CardDefinition* d = CardDatabase::Instance().LookupCached(ap.hand[h]);
        return d != nullptr && d->params.etb_damage_any > 0
            && d->params.etb_damage_any >= opp_life;
    };
    // Affordability is only consulted by the `uncast` variant, and it is the expensive part, so it
    // is computed once per call and only when that variant is live.
    ManaPool pool;
    if (mode == LackeyRank::Uncast) { pool = AvailableManaPool(s); }
    auto key = [&](int h) {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(ap.hand[h]);
        const Card& c = d ? d->card : ap.hand[h];
        const int mv = c.m_mana_cost.ManaValue();
        const int pw = c.m_power.value_or(0);
        const int num = ap.hand[h].m_number;
        switch (mode)
        {
            case LackeyRank::Low:    return std::make_tuple(mv, -pw, num);
            case LackeyRank::Pow:    return std::make_tuple(-pw, -mv, num);
            case LackeyRank::Uncast: return std::make_tuple(pool.CanPay(c.m_mana_cost) ? 1 : 0,
                                                            -mv, num);
            case LackeyRank::Mv:
            default:                 return std::make_tuple(-mv, -pw, num);
        }
    };
    std::vector<int> out = hand_indices;
    std::stable_sort(out.begin(), out.end(), [&](int a, int b) {
        // Lethal-now outranks every ranking variant, including the anti-heuristic arms, so the
        // MTG_LACKEY_RANK sweep stays a test of the NON-lethal ordering rather than of this.
        const bool la = lethal_now(a), lb = lethal_now(b);
        if (la != lb) { return la; }
        return key(a) < key(b);
    });

    // DOMINANCE PRUNE (MTG_LACKEY_DOMINANCE, default ON). Drop a candidate that another candidate in
    // the same set beats on every axis the engine models, so it cannot consume a searched slot. This
    // is NOT a ranking preference -- it is "B can never be right while A is here", which is the only
    // safe reason to remove an option from a search entirely.
    //
    // Live case: Goblin King vs Goblin Chieftain. Same mana cost, same body, identical lord params
    // (+1/+1 to other Goblins); Chieftain additionally grants haste, while King's only differentiator
    // is mountainwalk, which the card data itself marks INERT in goldfishing (the opponent never
    // blocks). So King is dominated -- in THIS format, not in real Magic. Measured: the search chose
    // King 0 times in 62 triggers where Chieftain was also in hand.
    //
    // It matters because those two tie on mana value AND power, so the sort falls through to card
    // NUMBER (shuffle order) -- with both plus a Goblin Warchief in hand, a width-2 axis could spend
    // both slots on the lords and never score the Warchief, which is the best of the three.
    //
    // Param-derived, not name-keyed: same cost, same P/T, same lord effect, and a strict superset of
    // grant flags. A new card that happens to be dominated is handled without a code change.
    static const bool s_dominance = EnvOn("MTG_LACKEY_DOMINANCE", true);
    if (s_dominance && out.size() > 1)
    {
        auto def_of = [&](int h) { return CardDatabase::Instance().LookupCached(ap.hand[h]); };
        auto dominates = [&](int a, int b) {   // does a strictly dominate b?
            const CardDefinition* da = def_of(a);
            const CardDefinition* db = def_of(b);
            if (da == nullptr || db == nullptr || da == db) { return false; }
            const ManaCost& ca = da->card.m_mana_cost;
            const ManaCost& cb = db->card.m_mana_cost;
            if (ca.generic != cb.generic || ca.white != cb.white || ca.blue != cb.blue
                || ca.black != cb.black || ca.red != cb.red || ca.green != cb.green
                || ca.colorless != cb.colorless || ca.has_x != cb.has_x) { return false; }
            if (da->card.m_power != db->card.m_power || da->card.m_toughness != db->card.m_toughness)
            { return false; }
            const CardParams& pa = da->params;
            const CardParams& pb = db->params;
            if (pa.subtypes_affected != pb.subtypes_affected) { return false; }
            if (pa.power_bonus != pb.power_bonus || pa.tough_bonus != pb.tough_bonus) { return false; }
            if (pa.lord_excludes_self != pb.lord_excludes_self) { return false; }
            if (pa.etb_damage_any != pb.etb_damage_any) { return false; }
            // Same cost, body and lord effect: a wins iff it grants something b does not, and b
            // grants nothing a does not. Only MODELLED grants count -- an unmodelled ability is
            // inert by construction, which is exactly why this is a goldfish-only relation.
            const bool a_extra = (pa.grants_haste && !pb.grants_haste)
                              || (!pa.reduces_spell_subtype.empty() && pb.reduces_spell_subtype.empty());
            const bool b_extra = (pb.grants_haste && !pa.grants_haste)
                              || (!pb.reduces_spell_subtype.empty() && pa.reduces_spell_subtype.empty());
            return a_extra && !b_extra;
        };
        std::vector<int> kept;
        for (int cand : out)
        {
            bool dominated = false;
            for (int other : out) { if (dominates(other, cand)) { dominated = true; break; } }
            if (!dominated) { kept.push_back(cand); }
        }
        if (!kept.empty()) { out.swap(kept); }
    }
    return out;
}

// The BASE ETB-dig rule (see DecisionProvider::EtbDigCandidates): HEURISTIC FIRST, then the
// alternatives. Index 0 is the FIRST legal match in look order -- exactly what PerformEtbDig took
// inline before the hook existed -- so a non-branching caller (and MTG_ETBDIG_WIDTH=1) is
// byte-identical. The REST of the legal matches follow in look order so the searched axis has
// something to choose among; the base rule cannot rank them (look order is library order, i.e.
// shuffle order), which is precisely why this decision is handed to the search rather than to a
// better default. Same shape as TopDispositionCandidates.
std::vector<int> DecisionProvider::EtbDigCandidates(
    const GameState& /*s*/, int /*controller*/, const std::vector<Card>& /*examined*/,
    const std::vector<int>& legal) const
{
    return legal;
}

// Armored Skyhunter attack-dig put pick (see the DecisionProvider.h note). Rank the legal
// Aura/Equipment cards by the flat power they would grant -- equip_power_bonus for Equipment,
// aura_power_bonus for an Aura -- descending, ties to lower index (library order). Colossus
// Hammer (+10) therefore tops any pool it appears in, which is the deck's real line.
std::vector<int> DecisionProvider::AttackDigPutCandidates(
    const GameState& /*s*/, int /*controller*/,
    const std::vector<Card>& examined, const std::vector<int>& legal) const
{
    std::vector<int> ranked = legal;
    auto grant = [&](int i) -> int {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(examined[i]);
        if (d == nullptr) { return 0; }
        if (d->params.is_equipment) { return d->params.equip_power_bonus; }
        if (d->params.is_aura)      { return d->params.aura_power_bonus; }
        return 0;
    };
    std::stable_sort(ranked.begin(), ranked.end(),
                     [&](int a, int b) { return grant(a) > grant(b); });
    return ranked;
}

// Bruna, Light of Alabaster's gather subset (see the DecisionProvider.h note). THE EXACT GOLDFISH
// DOMINANCE COLLAPSE, and why it is exact (provider-owned one-option narrowing per the user's
// 2026-09-30 rule, PROVEN by the MTG_BRUNA_GATHER_FULL control arm -- see the Bruna ledger):
//   (i)   a GRAVEYARD Aura card has no other use in this deck (no recursion; Open the Armory hits the
//         library, Glittering Wish the sideboard) -- putting it onto an attacking Bruna is pure gain;
//   (ii)  a HAND Aura put now adds its full bonus THIS combat and keeps adding it every later turn
//         (Bruna attacks every turn -- flying, vigilance, nothing blocks), and saves its mana; no
//         card in the list triggers on an Aura being CAST; Arcanum Wings' swap is a PAID version of
//         the same put; a smaller hand never forces a discard. Colossification's ETB tap lands on an
//         ATTACKING Bruna and costs nothing (CR 506.4);
//   (iii) a BATTLEFIELD Aura moved from a NON-attacking host is a strict gain this combat and neutral
//         after (Bruna re-gathers every attack); from an ATTACKING host it is a zero-sum transfer
//         (no blockers: trample / flying / first strike are moot), never a loss;
//   (iv)  the counter-example is a HOST-DEPENDENT Aura -- Almost Perfect sets BASE 9/10, worth +4 on
//         Bruna (5/5) but +9 on a 0/1 dork, and moving it off an attacking dork LOSES power. So every
//         Aura carrying aura_set_base_power branches take/skip (2^m subsets, take-first; m <= 4, any
//         excess is taken), everything else is always taken. A COLOUR-CONDITIONAL Aura (Steel of
//         the Godhead: +1/+1 per white / blue condition) is host-dependent in general, but on a
//         gatherer that has every colour it names it is worth its maximum, so moving it there never
//         loses power -- Bruna is white and blue, so Steel is always taken; only a gatherer missing
//         a named colour would branch it.
// MTG_BRUNA_GATHER_FULL=1 is the PROOF's control arm only: the full powerset (n <= 10), take-all first.
std::vector<std::vector<int>> DecisionProvider::BrunaGatherCandidates(
    const GameState& /*s*/, int /*controller*/, const Permanent& bruna,
    const std::vector<AuraGatherCand>& cands) const
{
    const int n = static_cast<int>(cands.size());
    std::vector<std::vector<int>> out;
    static const bool full = EnvOn("MTG_BRUNA_GATHER_FULL");   // proof control arm; DEFAULT OFF
    if (full && n <= 10)
    {
        for (int mask = (1 << n) - 1; mask >= 0; --mask)
        {
            std::vector<int> sub;
            for (int i = 0; i < n; ++i) { if (mask & (1 << i)) { sub.push_back(i); } }
            out.push_back(std::move(sub));
        }
        return out;
    }
    std::vector<int> fixed, dep;
    for (int i = 0; i < n; ++i)
    {
        const CardDefinition* d = CardDatabase::Instance().Lookup(cands[static_cast<std::size_t>(i)].name);
        // A colour-conditional grant (Steel of the Godhead) is host-dependent too, UNLESS the
        // gathering attacker has every colour it conditions on: then it is worth its maximum on the
        // gatherer and moving it there can never lose power (Bruna is white AND blue -> always taken).
        bool colour_dep = false;
        if (d != nullptr)
        {
            for (const CardParams::AuraColorBonus& cb : d->params.aura_color_bonuses)
            { if (!bruna.card.HasColor(cb.color)) { colour_dep = true; break; } }
        }
        const bool host_dependent = d != nullptr && (d->params.aura_set_base_power >= 0 || colour_dep);
        if (host_dependent && dep.size() < 4) { dep.push_back(i); }
        else                                  { fixed.push_back(i); }
    }
    const int m = static_cast<int>(dep.size());
    for (int mask = (1 << m) - 1; mask >= 0; --mask)
    {
        std::vector<int> sub = fixed;
        for (int j = 0; j < m; ++j) { if (mask & (1 << j)) { sub.push_back(dep[static_cast<std::size_t>(j)]); } }
        std::sort(sub.begin(), sub.end());
        out.push_back(std::move(sub));
    }
    return out;
}

// Arcanum Wings' swap pick (see the DecisionProvider.h note): rank the legal hand Auras by DAMAGE,
// computed by actually performing the swap on a copy (so Almost Perfect's base set, a lost Aura's
// grant, Kor-style self-buffs and double strike are all priced exactly as combat realises them):
//   key 1: LETHAL THIS TURN -- the team's attack this turn (every creature that can still attack,
//          the host included only if it still can; an already-attacking host always counts -- a
//          Colossification tap is then free, CR 506.4) reaches the opponent's life;
//   key 2: if lethal, this turn's team damage; otherwise the host's damage over THIS turn and the
//          NEXT (this-turn damage if it can still attack, plus its power next turn);
//   key 3: lower hand index (deterministic).
// ROOT-CAUSED REFINEMENT (2026-10-05 proof run): the first version ranked on this-turn damage
// alone, so in a main phase it preferred Indrik Umbra (+4 now, the host still attacks) over
// Colossification (the ETB tap costs this turn's attack, +20 next turn); the fully-branched control
// arm committed Colossification there. When nothing is lethal this turn, +20 next turn is worth
// more than +4 now -- the two-turn sum prices exactly that, and the lethal key keeps "+4 now" when
// +4 now wins the game.
std::vector<int> DecisionProvider::AuraSwapRanking(
    const GameState& s, int controller, int wings_number, int host_number,
    bool host_attacking, const std::vector<int>& legal) const
{
    struct Scored { int idx; bool lethal; int key; };
    std::vector<Scored> sc;
    const int opp_life = s.players[1 - controller].life;
    for (int hi : legal)
    {
        GameState t = s;
        if (!ApplyAuraSwap(t, controller, wings_number, hi, /*respond_window=*/!host_attacking)) { continue; }
        const Permanent* h = nullptr;
        for (const Permanent& p : t.battlefield) { if (p.card.m_number == host_number) { h = &p; break; } }
        if (h == nullptr) { continue; }
        const int mult = CreatureHasDoubleStrike(*h, t) ? 2 : 1;
        const int pw = std::max(0, CombatPowerOf(*h, t)) * mult;
        const bool attacks = host_attacking || CanAttackFull(*h, t.battlefield, controller);
        // The team's attack this turn on the post-swap board (main phase: every creature that can
        // still attack; in combat the host is known to be attacking and the rest already declared,
        // so the host's own gain is the whole difference between options).
        int team = attacks ? pw : 0;
        if (!host_attacking)
        {
            for (const Permanent& q : t.battlefield)
            {
                if (q.controller_index != controller || q.card.m_number == host_number) { continue; }
                if (!CanAttackFull(q, t.battlefield, controller)) { continue; }
                team += std::max(0, CombatPowerOf(q, t)) * (CreatureHasDoubleStrike(q, t) ? 2 : 1);
            }
        }
        const bool lethal = team >= opp_life;
        sc.push_back({ hi, lethal, lethal ? team : (attacks ? pw : 0) + pw });
    }
    std::stable_sort(sc.begin(), sc.end(), [](const Scored& a, const Scored& b)
    {
        if (a.lethal != b.lethal) { return a.lethal; }
        if (a.key != b.key) { return a.key > b.key; }
        return a.idx < b.idx;
    });
    std::vector<int> out;
    for (const Scored& x : sc) { out.push_back(x.idx); }
    return out;
}

// Armored Skyhunter attach-host pick (see the DecisionProvider.h note): the ATTACKER whose
// realized damage this combat rises the most once the equipment lands on it. ds_after counts
// the incoming equipment (a bare Kor Duelist flips to double strike; Balan may cross his 2-
// equipment threshold), and equip_min_power (O-Naginata) filters illegal hosts. A non-attacker
// realizes nothing this combat, so attackers-only is the value-greedy default; the human
// chooser in the viewer may attach anywhere.
// Sigarda's Aid's free attach. Same per-host scorer as AttackDigAttachHost below, but over the
// candidate set the caller built (a main-phase ETB has no declared attackers yet). Ties to lower
// card number, so the pick is deterministic -- which matters because it feeds the sim key.
int DecisionProvider::EquipmentEtbAttachHost(
    const GameState& s, int controller, const Card& equip_card,
    const std::vector<int>& candidate_bf_indices) const
{
    const CardDefinition* ed = CardDatabase::Instance().LookupCached(equip_card);
    if (ed == nullptr || !ed->params.is_equipment) { return 0; }
    // A RECONFIGURE piece (Lizard Blades) entering is a 1/1 double-strike CREATURE, and attaching it
    // costs that body (it stops being a creature). So for it the "may" DECLINES unless some host
    // strictly gains -- best_delta starts at 0 instead of -1, and a 0-gain host (one that already
    // double-strikes, or has no power) never wins. PROVIDER HEURISTIC (disclosed): the base rule for
    // every other Equipment is unchanged (always attach to the best host), so every other deck is
    // byte-identical; the human keeps the full host list plus decline via attach_host.
    int best_num = 0, best_delta = (ed->params.reconfigure_cost.has_value() ? 0 : -1);
    for (int idx : candidate_bf_indices)
    {
        if (idx < 0 || idx >= static_cast<int>(s.battlefield.size())) { continue; }
        const Permanent& h = s.battlefield[idx];
        if (!h.card.IsCreature() && !h.is_animated) { continue; }
        if (h.card.m_number == equip_card.m_number) { continue; }   // never onto itself (CR 301.5c)
        const int pw_now = EquipGatePowerOf(h, s);
        const CardDefinition* hd = CardDatabase::Instance().LookupCached(h.card);
        const int  n_now  = CountEquipmentAttachedTo(s, controller, h.card.m_number);
        const bool ds_now = h.card.HasKeyword(Keyword::DoubleStrike)
                         || HasDoubleStrikeFromEquipment(h, s);
        bool ds_after = ds_now || ed->params.equip_grants_double_strike;   // Lizard Blades' grant
        if (hd != nullptr)
        {
            if (hd->params.double_strike_while_equipped && n_now + 1 >= 1) { ds_after = true; }
            if (hd->params.double_strike_min_equipment > 0
                && n_now + 1 >= hd->params.double_strike_min_equipment) { ds_after = true; }
        }
        const int dpw = EquipAttachDeltaFor(s, controller, h.card.m_number, ed->params).first;
        const int delta = (pw_now + dpw) * (ds_after ? 2 : 1) - pw_now * (ds_now ? 2 : 1);
        if (delta > best_delta
            || (delta == best_delta && best_num != 0 && h.card.m_number < best_num))
        {
            best_delta = delta;
            best_num   = h.card.m_number;
        }
    }
    return best_num;
}

int DecisionProvider::AttackDigAttachHost(
    const GameState& s, int /*controller*/, const Card& equip_card,
    const std::vector<int>& attacker_bf_indices) const
{
    const CardDefinition* ed = CardDatabase::Instance().LookupCached(equip_card);
    if (ed == nullptr || !ed->params.is_equipment) { return 0; }
    int best_num = 0, best_delta = -1;
    for (int idx : attacker_bf_indices)
    {
        if (idx < 0 || idx >= static_cast<int>(s.battlefield.size())) { continue; }
        const Permanent& h = s.battlefield[idx];
        if (!h.card.IsCreature() && !h.is_animated) { continue; }
        const int pw_now = EquipGatePowerOf(h, s);
        if (ed->params.equip_min_power > 0 && pw_now < ed->params.equip_min_power) { continue; }
        if (h.card.m_number == equip_card.m_number) { continue; }   // never onto itself (CR 301.5c)
        const CardDefinition* hd = CardDatabase::Instance().LookupCached(h.card);
        const int  n_now    = CountEquipmentAttachedTo(s, h.controller_index, h.card.m_number);
        const bool ds_now   = h.card.HasKeyword(Keyword::DoubleStrike)
                           || HasDoubleStrikeFromEquipment(h, s);
        bool ds_after = ds_now || ed->params.equip_grants_double_strike;   // Lizard Blades' grant
        if (hd != nullptr)
        {
            if (hd->params.double_strike_while_equipped && n_now + 1 >= 1) { ds_after = true; }
            if (hd->params.double_strike_min_equipment > 0
                && n_now + 1 >= hd->params.double_strike_min_equipment) { ds_after = true; }
        }
        // Shared delta helper, not the flat equip_power_bonus -- see EquipAttachDeltaFor. A
        // per-equipment scaler reads 0 there, which would rank every host identically; this host
        // picker and TurnSolver's rider_delta call the same helper so the two cannot disagree.
        const int dpw = EquipAttachDeltaFor(s, h.controller_index, h.card.m_number,
                                            ed->params).first;
        const int delta = (pw_now + dpw) * (ds_after ? 2 : 1)
                        - pw_now * (ds_now ? 2 : 1);
        if (delta > best_delta
            || (delta == best_delta && best_num != 0 && h.card.m_number < best_num))
        {
            best_delta = delta;
            best_num   = h.card.m_number;
        }
    }
    return best_num;
}

// Ardenn's beginning-of-combat attach -- see the DecisionProvider.h note. The objective is THIS
// combat's realised damage (BeginCombatHostDamage per host); per candidate target it is a greedy
// ascent over moves, each move scored on a scratch board (equipped_to / aura_attached_to re-pointed
// directly -- ApplyEquip is for the real apply) and undone, so haste from a moved Lightning Greaves,
// Kor Duelist's double strike flipping ON (or OFF, on the host a piece leaves), Balan's two-piece
// threshold, Golem-Skin Gauntlets' per-piece scaling and O-Naginata's power gate are all read from
// the board the move would produce, never estimated. Two move shapes: a single piece, and a BLOCK
// (every remaining piece on one other host, or every loose piece) -- the block is what lets a
// threshold no single piece crosses (two 0-power shields onto a bare Balan) register. A move only
// changes the target's and the leaving hosts' terms, so each score is O(board), not O(board^2).
DecisionProvider::BeginCombatAttachChoice DecisionProvider::BeginCombatAttach(
    const GameState& s, int controller, int /*source_num*/,
    const std::vector<int>& host_bf_indices, int pinned_host_num) const
{
    BeginCombatAttachChoice out;
    const int bf_size = static_cast<int>(s.battlefield.size());
    // `reconf`: a reconfigure piece (Lizard Blades) -- a creature while loose, NOT a creature while
    // attached (CR 702.151b). The scratch board toggles that in set_host so every score reads the
    // board the move would really produce, and its OWN attack term counts in a move's gain.
    struct Piece { int num; bool aura; int flat_pw; int min_power; int from; const CardParams* pp;
                   bool reconf = false; };
    std::vector<Piece> pieces;
    for (int i = 0; i < bf_size; ++i)
    {
        const Permanent& e = s.battlefield[i];
        if (e.controller_index != controller || e.def_absent || e.is_animated) { continue; }
        const CardDefinition* d = CardDatabase::Instance().LookupCached(e.card);
        if (d == nullptr) { continue; }
        if (d->params.is_equipment)
        {
            // Grafted Wargear ON a host: its re-host sacrifices that host -- a body traded for a few
            // points this turn, which this scorer cannot price. Never moved. A LOOSE Wargear attaches
            // like any other piece (a first attach is a no-op for its clause).
            if (d->params.equip_sacrifices_prior_host && e.equipped_to != 0) { continue; }
            pieces.push_back({ e.card.m_number, false, d->params.equip_power_bonus,
                               d->params.equip_min_power, e.equipped_to, &d->params,
                               d->params.reconfigure_cost.has_value() });
        }
        else if (d->params.is_aura && !d->params.is_land_aura)
        {
            pieces.push_back({ e.card.m_number, true, d->params.aura_power_bonus, 0,
                               e.aura_attached_to, &d->params });
        }
    }
    if (pieces.empty() || host_bf_indices.empty()) { return out; }

    auto find_perm = [&](GameState& b, int num) -> Permanent*
    {
        for (Permanent& p : b.battlefield)
        { if (p.controller_index == controller && p.card.m_number == num) { return &p; } }
        return nullptr;
    };
    auto host_dmg = [&](GameState& b, int num) -> int
    {
        if (num == 0) { return 0; }
        const Permanent* p = find_perm(b, num);
        return p ? BeginCombatHostDamage(b, *p) : 0;
    };
    auto set_host = [&](GameState& b, const Piece& pc, int to)
    {
        Permanent* p = find_perm(b, pc.num);
        if (p == nullptr) { return; }
        if (pc.aura) { p->aura_attached_to = to; } else { p->equipped_to = to; }
        // Creature-ness only, and deliberately NOT the real refresh: the gear sitting on the piece
        // stays pointed at it, so the undo (set_host back to `from`) is exact. That gear contributes
        // nothing while its holder is not a creature (BeginCombatHostDamage reads IsCreature), which
        // is the same damage the real apply's fall-off produces this combat.
        if (pc.reconf)
        {
            if (to != 0) { p->card.RemoveType(CardType::Creature); }
            else         { p->card.AddType(CardType::Creature); }
        }
    };
    // Legal on the board AS IT STANDS (the min-power gate reads the host's power with everything
    // attached so far, which is why a gated piece is ordered after the bonuses that lift it).
    auto legal_on = [&](GameState& b, const Piece& pc, int host_num) -> bool
    {
        if (pc.num == host_num) { return false; }   // never onto itself (CR 301.5c)
        if (pc.aura)
        {
            const std::vector<int> lt = LegalEnchantTargets(b, controller, *pc.pp);
            return std::find(lt.begin(), lt.end(), host_num) != lt.end();
        }
        if (pc.min_power <= 0) { return true; }
        const Permanent* h = find_perm(b, host_num);
        return h != nullptr && EquipGatePowerOf(*h, b) >= pc.min_power;
    };

    const int base_total = BeginCombatProjectedDamage(s, controller);
    int best_total = base_total, best_host = 0;
    std::size_t best_moves = 0;
    std::vector<int> best_order;
    // ONE scratch board for the whole call (this runs inside every attack projection on an Ardenn
    // board, so a GameState copy per candidate host would be the dominant cost): each host's moves
    // are applied to it and reverted before the next host is tried.
    GameState scratch = s;
    for (int hi : host_bf_indices)
    {
        if (hi < 0 || hi >= bf_size) { continue; }
        const Permanent& host = s.battlefield[hi];
        if (host.controller_index != controller) { continue; }
        if (!host.card.IsCreature() && !host.is_animated) { continue; }
        const int host_num = host.card.m_number;
        if (pinned_host_num != 0 && host_num != pinned_host_num) { continue; }
        std::vector<char> done(pieces.size(), 0);
        std::vector<int> order;
        int total = base_total;
        // Gain of moving `ks` onto host_num: applied on the scratch board in order, scored, undone.
        // INT_MIN = not a legal move (some piece could not attach at its turn).
        auto gain_of = [&](const std::vector<std::size_t>& ks) -> int
        {
            std::vector<int> touched{ host_num };
            for (std::size_t k : ks)
            {
                if (pieces[k].from != 0
                    && std::find(touched.begin(), touched.end(), pieces[k].from) == touched.end())
                { touched.push_back(pieces[k].from); }
                // A loose reconfigure piece is itself an attacker; attaching it ends that term.
                if (pieces[k].reconf
                    && std::find(touched.begin(), touched.end(), pieces[k].num) == touched.end())
                { touched.push_back(pieces[k].num); }
            }
            int before = 0;
            for (int t : touched) { before += host_dmg(scratch, t); }
            std::vector<std::size_t> applied;
            for (std::size_t k : ks)
            {
                if (!legal_on(scratch, pieces[k], host_num)) { continue; }
                set_host(scratch, pieces[k], host_num);
                applied.push_back(k);
            }
            int after = 0;
            for (int t : touched) { after += host_dmg(scratch, t); }
            for (std::size_t k : applied) { set_host(scratch, pieces[k], pieces[k].from); }
            if (applied.size() != ks.size()) { return std::numeric_limits<int>::min(); }
            return after - before;
        };
        for (;;)
        {
            std::vector<std::size_t> cand;
            for (std::size_t k = 0; k < pieces.size(); ++k)
            { if (!done[k] && pieces[k].from != host_num) { cand.push_back(k); } }
            if (cand.empty()) { break; }
            // Ungated pieces first, then by rising gate, biggest flat bonus first within a tier: the
            // order a block applies in, and the tie-break among equal gains.
            std::stable_sort(cand.begin(), cand.end(), [&](std::size_t a, std::size_t b)
            {
                if (pieces[a].min_power != pieces[b].min_power) { return pieces[a].min_power < pieces[b].min_power; }
                if (pieces[a].flat_pw   != pieces[b].flat_pw)   { return pieces[a].flat_pw   > pieces[b].flat_pw; }
                return pieces[a].num < pieces[b].num;
            });
            int best_gain = 0;
            std::vector<std::size_t> best_ks;
            for (std::size_t k : cand)
            {
                const int g = gain_of({ k });
                if (g > best_gain) { best_gain = g; best_ks = { k }; }
            }
            std::vector<int> froms;
            for (std::size_t k : cand)
            { if (std::find(froms.begin(), froms.end(), pieces[k].from) == froms.end()) { froms.push_back(pieces[k].from); } }
            for (int f : froms)
            {
                std::vector<std::size_t> ks;
                for (std::size_t k : cand) { if (pieces[k].from == f) { ks.push_back(k); } }
                if (ks.size() < 2) { continue; }
                const int g = gain_of(ks);
                if (g > best_gain) { best_gain = g; best_ks = ks; }
            }
            if (best_gain <= 0) { break; }
            for (std::size_t k : best_ks)
            {
                set_host(scratch, pieces[k], host_num);
                done[k] = 1;
                order.push_back(pieces[k].num);
            }
            total += best_gain;
        }
        if (pinned_host_num != 0)
        {
            // The human chose this host: also bring every LOOSE piece that costs nothing this combat
            // (gain 0 -- a shield onto the attacker), the natural reading of "attach any number ...
            // to target" once the target is given. Attached pieces still move only on a gain.
            for (std::size_t k = 0; k < pieces.size(); ++k)
            {
                if (done[k] || pieces[k].from != 0) { continue; }
                if (gain_of({ k }) < 0) { continue; }   // illegal (INT_MIN) or harmful
                set_host(scratch, pieces[k], host_num);
                done[k] = 1;
                order.push_back(pieces[k].num);
            }
        }
        const bool better =
               total > best_total
            || (total == best_total && best_host != 0 && order.size() < best_moves)
            || (total == best_total && best_host != 0 && order.size() == best_moves && host_num < best_host);
        if ((pinned_host_num != 0 && !order.empty()) || (total > base_total && better))
        {
            best_total = total; best_host = host_num; best_moves = order.size(); best_order = order;
        }
        // Revert this host's moves so the next candidate starts from the real board.
        for (std::size_t k = 0; k < pieces.size(); ++k)
        { if (done[k]) { set_host(scratch, pieces[k], pieces[k].from); } }
    }
    if (best_host == 0) { return out; }
    out.host_num   = best_host;
    out.piece_nums = best_order;
    return out;
}

// Raubahn's attack attach -- see the DecisionProvider.h note. ORDER ONLY: every entry of `legal` is
// returned (the search branches over all of them through Plan::attack_attach_choice), so this decides
// nothing but the default. Each pair is scored on the board it would really produce: a PLAIN piece
// (no reconfigure, no re-host sacrifice) changes nothing but its own equipped_to, so it is priced by
// a flip-and-restore on ONE scratch board (this runs inside every attack projection on a Raubahn
// board); a reconfigure piece (Lizard Blades stops being a creature, leaves combat and sheds its own
// gear) or a Grafted Wargear (re-host sacrifice) goes through the shared ApplyEquip on a copy. A pair
// the min-power gate refuses never reaches here (the engine folds it as a no-op), but is scored as
// the unchanged board if it does.
std::vector<DecisionProvider::AttackAttachCand> DecisionProvider::AttackAttachCandidates(
    const GameState& s, int controller, int /*source_num*/,
    const std::vector<AttackAttachCand>& legal, const std::vector<int>& atk_idx) const
{
    std::vector<AttackAttachCand> out = legal;
    if (out.size() <= 1) { return out; }
    std::vector<int> atk_nums;
    atk_nums.reserve(atk_idx.size());
    for (const int i : atk_idx)
    {
        if (i >= 0 && i < static_cast<int>(s.battlefield.size()))
        { atk_nums.push_back(s.battlefield[static_cast<std::size_t>(i)].card.m_number); }
    }
    GameState scratch = s;
    const int before = AttackersCombatDamage(scratch, atk_nums);
    std::vector<int> gain(out.size(), 0);
    for (std::size_t k = 0; k < out.size(); ++k)
    {
        const AttackAttachCand& c = out[k];
        if (c.equip_num == 0) { continue; }   // attach nothing: gain 0
        Permanent* ep = nullptr;
        for (Permanent& q : scratch.battlefield)
        { if (q.controller_index == controller && q.card.m_number == c.equip_num) { ep = &q; break; } }
        if (ep == nullptr) { continue; }
        const CardDefinition* ed = CardDatabase::Instance().LookupCached(ep->card);
        if (ed == nullptr || !CanAttachEquip(scratch, controller, c.equip_num, c.host_num)) { continue; }
        if (!ed->params.reconfigure_cost.has_value() && !ed->params.equip_sacrifices_prior_host)
        {
            const int was = ep->equipped_to;
            ep->equipped_to = c.host_num;
            gain[k] = AttackersCombatDamage(scratch, atk_nums) - before;
            ep->equipped_to = was;
            continue;
        }
        GameState after = s;
        ApplyEquip(after, controller, c.equip_num, c.host_num);
        gain[k] = AttackersCombatDamage(after, atk_nums) - before;
    }
    std::vector<std::size_t> ord(out.size());
    for (std::size_t k = 0; k < ord.size(); ++k) { ord[k] = k; }
    std::stable_sort(ord.begin(), ord.end(), [&](std::size_t a, std::size_t b)
    {
        if (gain[a] != gain[b]) { return gain[a] > gain[b]; }
        const bool na = out[a].equip_num == 0, nb = out[b].equip_num == 0;
        if (na != nb) { return na; }   // a tie goes to attaching nothing
        if (out[a].equip_num != out[b].equip_num) { return out[a].equip_num < out[b].equip_num; }
        return out[a].host_num < out[b].host_num;
    });
    std::vector<AttackAttachCand> ranked;
    ranked.reserve(out.size());
    for (const std::size_t k : ord) { ranked.push_back(out[k]); }
    return ranked;
}

int DecisionProvider::SoulbondPartner(
    const GameState& s, int controller, const Permanent& source,
    const std::vector<int>& candidate_bf_indices) const
{
    int best_num = 0, best_pw = -1;
    // TANDEM LOOKOUT (soulbond_damage_trigger_draw, NivMizzetCombo 2026-10-17): its payload is
    // "whenever this creature deals damage to an opponent, draw a card", so a partner that pings on
    // every draw (draw_trigger_damage, Niv-Mizzet) turns the pair into the unbounded draw/ping loop --
    // every other partner draws at most once per its own combat damage. The Niv ranks first, power
    // only breaks ties among the rest. Read from the SOURCE's definition, so every other soulbond
    // creature (Silverblade Paladin) keeps the pure power order -- byte-identical. ORDER only: the
    // caller's legal set is unchanged and a human still picks from all of it.
    const CardDefinition* sdef = source.def_absent ? nullptr : CardDatabase::Instance().LookupCached(source.card);
    const bool combo_pair = sdef != nullptr && sdef->params.soulbond_damage_trigger_draw;
    for (int idx : candidate_bf_indices)
    {
        if (idx < 0 || idx >= static_cast<int>(s.battlefield.size())) { continue; }
        const Permanent& c = s.battlefield[idx];
        if (c.card.m_number == source.card.m_number) { continue; }   // "ANOTHER unpaired creature"
        if (combo_pair)
        {
            const CardDefinition* cd = c.def_absent ? nullptr : CardDatabase::Instance().LookupCached(c.card);
            if (cd != nullptr && cd->params.draw_trigger_damage > 0) { return c.card.m_number; }
        }
        // Effective power as the board really sees it: printed + until-EOT bonuses, plus lords and
        // anthems, plus the characteristic-defining term. Adeline is printed 0/4 with
        // power_equals_creature_count, so DynamicBasePower is what stops her being valued at 0 --
        // she is routinely this deck's largest creature and therefore its best pair.
        // ONE formula with the enumerator's weak-partner gate (SoulbondCandidatePower).
        const int pw = SoulbondCandidatePower(s, controller, c);
        if (pw > best_pw || (pw == best_pw && best_num != 0 && c.card.m_number < best_num))
        {
            best_pw  = pw;
            best_num = c.card.m_number;
        }
    }
    return best_num;   // 0 = no legal partner (the caller's list was empty), i.e. stay unpaired
}

void DecisionProvider::LandfallCounterTargetOrder(const GameState& s, int controller,
                                                  std::vector<int>& class_reps) const
{
    // The Saga-chapter-II key (SagaChapterTargetCandidates): swings now, then effective power,
    // descending; stable, so ties keep the caller's battlefield order (oldest first). ORDER ONLY --
    // the search branches over every entry, so this decides nothing but the default.
    auto key = [&](int idx)
    {
        const Permanent& q = s.battlefield[static_cast<std::size_t>(idx)];
        const bool swings_now = !q.tapped && CanAttackFull(q, s.battlefield, controller);
        return (swings_now ? 1000 : 0) + q.EffectivePower();
    };
    // Keys computed ONCE per class (they read only the board): the comparator used to recompute both
    // sides per comparison, an O(n log n) x CanAttackFull cost on every Phylath landfall of a wide
    // Plant board (perf 2026-10-15). Same keys, same stable order.
    if (class_reps.size() < 2) { return; }
    std::vector<std::pair<int, int>> keyed;
    keyed.reserve(class_reps.size());
    for (int idx : class_reps) { keyed.emplace_back(key(idx), idx); }
    std::stable_sort(keyed.begin(), keyed.end(),
                     [](const std::pair<int, int>& a, const std::pair<int, int>& b)
                     { return a.first > b.first; });
    for (std::size_t i = 0; i < keyed.size(); ++i) { class_reps[i] = keyed[i].second; }
}

// The colours we NEED and LACK, as a 5-bit WUBRG mask: NEED = a coloured pip on a nonland card in
// hand, LACK = no permanent we control produces it. Read off definitions -- hand cards are name-only
// placeholders. The ONE reader for both LandSearchPickOrder and its memo key, so they cannot drift.
static unsigned LandSearchLackMask(const GameState& s, int controller)
{
    bool need[5] = { false, false, false, false, false };
    bool have[5] = { false, false, false, false, false };
    const Player& pl = s.players[static_cast<std::size_t>(controller)];
    for (const Card& c : pl.hand)
    {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(c);
        if (d == nullptr || d->card.IsLand()) { continue; }
        const ManaCost& mc = d->card.m_mana_cost;
        if (mc.white > 0) { need[0] = true; }
        if (mc.blue  > 0) { need[1] = true; }
        if (mc.black > 0) { need[2] = true; }
        if (mc.red   > 0) { need[3] = true; }
        if (mc.green > 0) { need[4] = true; }
    }
    // The result is need & ~have, so once every NEEDED colour is had nothing below can change it:
    // the walk stops there (and never starts when nothing is needed). Same mask, fewer reads.
    auto all_needed_had = [&]()
    {
        for (int i = 0; i < 5; ++i) { if (need[i] && !have[i]) { return false; } }
        return true;
    };
    if (!all_needed_had())
    {
        for (const Permanent& q : s.battlefield)
        {
            if (q.controller_index != controller || q.def_absent) { continue; }
            const CardDefinition* d = CardDatabase::Instance().LookupCached(q.card);
            if (d == nullptr) { continue; }
            bool grew = false;
            for (Color c : d->params.produces)
            {
                const int ci = static_cast<int>(c);
                if (ci >= 0 && ci < 5 && !have[ci]) { have[ci] = true; grew = true; }
            }
            if (grew && all_needed_had()) { break; }
        }
    }
    unsigned lack = 0;
    for (int i = 0; i < 5; ++i) { if (need[i] && !have[i]) { lack |= 1u << i; } }
    return lack;
}

bool DecisionProvider::LandSearchPickOrderKey(const GameState& s, int controller, std::uint64_t& key) const
{
    key = LandSearchLackMask(s, controller);
    return true;
}

void DecisionProvider::LandSearchPickOrder(const GameState& s, int controller, int count, int to_hand,
                                           bool basic_only, bool share_land_type,
                                           std::vector<std::vector<std::string>>& picks) const
{
    (void)count; (void)to_hand; (void)basic_only; (void)share_land_type;
    if (picks.size() < 2) { return; }
    // Colours we NEED (a coloured pip on a nonland card in hand) and LACK (no permanent we control
    // produces it) -- LandSearchLackMask, shared with the memo key above.
    const unsigned lack = LandSearchLackMask(s, controller);
    auto score = [&](const std::vector<std::string>& pick)
    {
        bool got[5] = { false, false, false, false, false };
        for (const std::string& nm : pick)
        {
            const CardDefinition* d = CardDatabase::Instance().Lookup(nm);
            if (d == nullptr) { continue; }
            for (Color c : d->params.produces)
            { const int ci = static_cast<int>(c); if (ci >= 0 && ci < 5) { got[ci] = true; } }
        }
        int cover = 0;
        for (int i = 0; i < 5; ++i) { if (((lack >> i) & 1u) && got[i]) { ++cover; } }
        return cover * 16 + static_cast<int>(pick.size());
    };
    std::vector<int> keys(picks.size());
    for (std::size_t i = 0; i < picks.size(); ++i) { keys[i] = score(picks[i]); }
    std::vector<std::size_t> order(picks.size());
    for (std::size_t i = 0; i < order.size(); ++i) { order[i] = i; }
    std::stable_sort(order.begin(), order.end(),
                     [&](std::size_t a, std::size_t b) { return keys[a] > keys[b]; });
    std::vector<std::vector<std::string>> out;
    out.reserve(picks.size());
    for (std::size_t i : order) { out.push_back(std::move(picks[i])); }
    picks = std::move(out);
}

// ---- LandfallProvider: the COLOUR-SEQUENCE fetch rule (USER 2026-10-16) -------------------------
// The user's rule for the Landfall list (13 Forest, 2 Mountain), built up over one exchange:
//   "Myriad landscape should search for Mountains unless there is only one left in the deck or we have
//    fewer than 2 green." ... "getting 2 green first makes sense as a general rule" ... "a common rule
//    might be to get 2 green then one red then another green then the final red in priority order
//    unless we have the myriad situation and need to fetch the reds together" ... "searching additional
//    green early is unlikely to hurt that much" ... "if the myriad landscape is on board and your only
//    remaining search effect you can work around it" ... "If one of the mountains is already in hand
//    we can count that also." ... and the point of it: "make the searches cheap here by pruning. This
//    should avoid wasted effort figuring out which land to get."
// So it is an ORDER (the front pick, LandSearchPickOrder) AND a PRUNE (LandSearchPickWidth = 1 for
// every basic search): the search no longer branches over which basic to fetch. Human play keeps the
// full list; MTG_UNPRUNE=landpick restores the autonomous fan for the standing A/B.
// Read generically off the deck rather than by name: MAIN = the colour with the most basic lands in our
// card pool (library + hand + battlefield + graveyard), SPLASH = the colour with the fewest (at least
// one) -- Forest / Mountain here. A pool with fewer than two basic colours keeps the base order and
// is not pruned. Sources: g = our permanents that make MAIN, r = our permanents that make SPLASH plus
// the splash BASICS in hand (a Mountain in hand will be played; a Gruul Turf in hand is NOT counted --
// it enters tapped -- though one on the battlefield is).
//   * Every BASIC search except Myriad, land by land (battlefield entries first, then hand): the next
//     colour of the sequence MAIN, MAIN, SPLASH, MAIN, SPLASH (g < 2 -> main; else r < 1 -> splash;
//     else g < 3 -> main; else r < 2 -> splash; else main), counting each land just fetched. A colour
//     the library no longer holds yields the other. THE MYRIAD SITUATION: a Myriad Landscape on our
//     battlefield is the only land-search source we have left (hand, battlefield, suspended) and >= 2
//     splash basics remain -- then MAIN throughout, so Myriad fetches the reds together.
//   * Myriad Landscape (share_land_type): the splash PAIR when >= 2 splash basics remain in the library
//     and g >= 2; otherwise the main pair.
//   * Primeval Titan (any land, two per trigger) -- the user's rule, same day: "you usually want one of
//     three: 1. Evolving Wilds/Terramorphic ... For additional landfall. 2. Gruul Turf - If you have no
//     land drop it gives you one. It also produces both colours. 3. Myriad Landscape - For additional
//     landfall, at the cost of mana." "Gruul turf is a one-of and I would make it automatic if you
//     don't have a land drop." "If we are out of basics in the deck search Gruul Turf followed by
//     Myriad Landscape, followed by Radiant Fountain and Haunted Fengraf. Evolving Wilds and
//     Terramorphic are poor in this case, but you would still search them at the end." "The only
//     other case for Gruul Turf would be if you are low on Green or Red mana ... if you have less than
//     3 total ... if you have 1 or less red". Otherwise "it would be Evolving Wilds/Terramorphic vs
//     Myriad Landscape but it depends on what mana you will have next turn and what you need to cast.
//     We might be able to get away with searching this". So (LandfallTitanAllowed): with no basic left
//     in the library, the one pick the fixed order gives; else, when Turf is wanted (no land card in
//     hand, g < 3 or r <= 1) the picks holding the Karoo; and among what is left the picks holding the
//     MOST Wilds / Myriad -- SEARCHED among those (up to Wilds+Wilds, Wilds+Myriad, Myriad+Myriad).
//     Wilds and Terramorphic are one class already (LandSearch.h's identity fold). A slot the rule's
//     lands cannot fill stays open (searched); a board with no Turf to want and no Wilds / Myriad left
//     is not narrowed at all. Then: "Primeval Titan must never search for a basic in my opinion." --
//     because "basics are a resource in the deck. You don't want to waste them when being able to
//     choose any land" (every other search here -- Rampant Growth, Cultivate, Search for Tomorrow,
//     Khalni, Myriad, Wilds -- can find ONLY a basic). (LandfallProvider::LandSearchAdmitsLand): the autonomous list is built without basics, so with
//     one nonbasic left Titan takes it alone, and with none it finds nothing ("up to two"). The human
//     prompt still offers every land, with the basic-holding picks ordered last.
// The resolving source is never counted as an "other" one: a fetch land / Myriad / Khalni is
// sacrificed as the cost and a spell is off the hand before it resolves (AIEngine::CastSpellFromHand
// erases it before the effect; the rollout's apply_one is its lockstep twin).
namespace
{
struct LandfallColourState
{
    int  main = -1, splash = -1;      // WUBRG index, -1 = none (rule off)
    int  lib_main = 0, lib_splash = 0;
    int  g = 0, r = 0;                // MAIN / SPLASH sources (r includes splash BASICS in hand)
    bool myriad_situation = false;    // an on-board Myriad is the only search left, >= 2 splash in library
};

int BasicColourOf(const CardDefinition* d)
{
    if (d == nullptr || !IsBasicLandCard(*d) || d->params.produces.size() != 1) { return -1; }
    const int ci = static_cast<int>(d->params.produces.front());
    return (ci >= 0 && ci < 5) ? ci : -1;
}

bool MakesColour(const CardDefinition* d, int ci)
{
    if (d == nullptr) { return false; }
    for (Color c : d->params.produces) { if (static_cast<int>(c) == ci) { return true; } }
    return false;
}

LandfallColourState ReadLandfallColours(const GameState& s, int controller)
{
    LandfallColourState r;
    const Player& pl = s.players[static_cast<std::size_t>(controller)];
    int basics[5] = { 0, 0, 0, 0, 0 };
    int lib_by[5] = { 0, 0, 0, 0, 0 };
    for (std::size_t i = 0; i < pl.library.size(); ++i)
    {
        const int ci = BasicColourOf(CardDatabase::Instance().LookupCached(pl.library[i]));
        if (ci >= 0) { ++basics[ci]; ++lib_by[ci]; }
    }
    for (const Card& c : pl.hand)
    { const int ci = BasicColourOf(CardDatabase::Instance().LookupCached(c)); if (ci >= 0) { ++basics[ci]; } }
    for (const Card& c : pl.graveyard)
    { const int ci = BasicColourOf(CardDatabase::Instance().LookupCached(c)); if (ci >= 0) { ++basics[ci]; } }
    std::vector<const CardDefinition*> mine;
    int sources = 0, myriads = 0, myriad_on_bf = 0;
    auto note_source = [&](const CardDefinition* d)
    {
        if (d == nullptr || d->params.land_search_count <= 0) { return false; }
        ++sources;
        if (d->params.land_search_share_land_type) { ++myriads; return true; }
        return false;
    };
    for (const Permanent& q : s.battlefield)
    {
        if (q.controller_index != controller || q.def_absent) { continue; }
        const CardDefinition* d = CardDatabase::Instance().LookupCached(q.card);
        if (d == nullptr) { continue; }
        const int ci = BasicColourOf(d);
        if (ci >= 0) { ++basics[ci]; }
        mine.push_back(d);
        if (note_source(d)) { ++myriad_on_bf; }
    }
    for (const Card& c : pl.hand) { note_source(CardDatabase::Instance().LookupCached(c)); }
    for (const SuspendedCard& sc : pl.suspended_cards) { note_source(CardDatabase::Instance().LookupCached(sc.card)); }
    for (int i = 0; i < 5; ++i)
    {
        if (basics[i] == 0) { continue; }
        if (r.main < 0 || basics[i] > basics[r.main]) { r.main = i; }
    }
    for (int i = 0; i < 5; ++i)
    {
        if (basics[i] == 0 || i == r.main) { continue; }
        if (r.splash < 0 || basics[i] < basics[r.splash]) { r.splash = i; }
    }
    if (r.splash < 0) { return r; }
    r.lib_main   = lib_by[r.main];
    r.lib_splash = lib_by[r.splash];
    for (const CardDefinition* d : mine)
    {
        if (MakesColour(d, r.main))   { ++r.g; }
        if (MakesColour(d, r.splash)) { ++r.r; }
    }
    // A splash BASIC in hand counts (it will be played untapped); a Gruul Turf in hand does NOT -- USER:
    // "I wouldn't count gruul turf just in case. The come into play tapped effect might slow us down.
    // Unless it is on the field already." (on the battlefield it is counted above, like any source).
    for (const Card& c : pl.hand)
    {
        if (BasicColourOf(CardDatabase::Instance().LookupCached(c)) == r.splash) { ++r.r; }
    }
    r.myriad_situation = myriad_on_bf > 0 && myriads == sources && r.lib_splash >= 2;
    return r;
}

// The rule's ONE pick for a basic search, in the pick list's representation (battlefield entries
// sorted, then hand entries sorted). Empty when the rule is off.
std::vector<std::string> LandfallRulePick(const LandfallColourState& r, int count, int to_hand,
                                          bool share_land_type, const std::string& main_name,
                                          const std::string& splash_name)
{
    std::vector<std::string> out;
    if (r.splash < 0) { return out; }
    if (share_land_type)
    {
        const bool splash = r.lib_splash >= 2 && r.g >= 2;
        const int  have   = splash ? r.lib_splash : r.lib_main;
        const int  n      = std::min(count, have);
        if (n <= 0)
        {
            const int m = std::min(count, splash ? r.lib_main : r.lib_splash);
            for (int i = 0; i < m; ++i) { out.push_back(splash ? main_name : splash_name); }
            return out;
        }
        for (int i = 0; i < n; ++i) { out.push_back(splash ? splash_name : main_name); }
        return out;
    }
    int g = r.g, rr = r.r, lm = r.lib_main, ls = r.lib_splash;
    std::vector<std::string> bf, hand;
    const int bf_slots = std::max(0, count - to_hand);
    for (int k = 0; k < count; ++k)
    {
        bool want_splash;
        if (r.myriad_situation) { want_splash = false; }
        else if (g < 2)         { want_splash = false; }
        else if (rr < 1)        { want_splash = true; }
        else if (g < 3)         { want_splash = false; }
        else if (rr < 2)        { want_splash = true; }
        else                    { want_splash = false; }
        if (want_splash && ls == 0) { want_splash = false; }
        if (!want_splash && lm == 0) { want_splash = true; }
        if (want_splash && ls == 0) { break; }   // nothing left to find
        if (want_splash) { --ls; ++rr; } else { --lm; ++g; }
        (k < bf_slots ? bf : hand).push_back(want_splash ? splash_name : main_name);
    }
    std::sort(bf.begin(), bf.end());
    std::sort(hand.begin(), hand.end());
    out = bf;
    out.insert(out.end(), hand.begin(), hand.end());
    return out;
}

// The class-representative NAME of each colour's basic among the picks (the list is built from
// library classes, so the names are the ones the list itself uses).
void LandfallColourNames(const std::vector<std::vector<std::string>>& picks, int main, int splash,
                         std::string& main_name, std::string& splash_name)
{
    for (const auto& pk : picks)
    {
        for (const std::string& nm : pk)
        {
            const int ci = BasicColourOf(CardDatabase::Instance().Lookup(nm));
            if (ci == main && main_name.empty())     { main_name = nm; }
            if (ci == splash && splash_name.empty()) { splash_name = nm; }
        }
    }
}

// Primeval Titan's land classes, read off the definition: the Karoo (Gruul Turf), the Myriad
// (a shared-type land search), the fetch (Evolving Wilds / Terramorphic Expanse), a basic, or other.
enum class TitanLand { Karoo, Myriad, Fetch, Basic, Other };

TitanLand TitanLandOf(const CardDefinition* d)
{
    if (d == nullptr)                         { return TitanLand::Other; }
    if (IsBasicLandCard(*d))                  { return TitanLand::Basic; }
    if (d->params.etb_bounce_land)            { return TitanLand::Karoo; }
    if (d->params.land_search_count > 0)
    { return d->params.land_search_share_land_type ? TitanLand::Myriad : TitanLand::Fetch; }
    return TitanLand::Other;
}

bool HandHasLand(const GameState& s, int controller)
{
    for (const Card& c : s.players[static_cast<std::size_t>(controller)].hand)
    {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(c);
        if (d != nullptr && d->card.IsLand()) { return true; }
    }
    return false;
}

// PROPOSED AMENDMENT to the user's Titan rule (2026-10-20, DEFAULT OFF -- the rule is the USER's, so
// adopting this is the USER's call): "the Wilds / Myriad pairs, searched" keeps only the picks holding
// the MOST Wilds / Myriad, so with two of them in the library a pick like Myriad + Radiant Fountain is
// unfindable at ANY budget. MTG_LANDFALL_TITAN_MIXED=1 also SEARCHES every pick holding at least one
// Wilds / Myriad (the other land any nonbasic: Fountain, Fengraf, Turf), listed AFTER the rule's own
// picks so a tie still takes the rule's pick. Found on overnight landfall s7007 g31 (2026-10-19
// rebaseline: T6 -> T7 at d3 b10, d5 b20 AND d8 b0): its T6 line is T4 Titan -> Myriad + Fountain,
// because the CRN reshuffle (Library::ShuffleByKey) would put Fountain on top and taking it leaves
// Avenger of Zendikar as the T5 draw; every rule pick (Wilds / Myriad pairs) draws Fountain, a Myriad
// or a Wilds instead -- a clairvoyant draw-steer, not a better land. MEASURED (held-out, paired): d3 b10
// 2,000 games 0.0000 (3 faster / 3 slower) at 1.43x units, PLAY 1,000 games 0.0000 (0 / 0) at 1.28x;
// g31 T6 at d8 b0 for 11.6M units (1.28x). docs/design/analysis-Landfall.md. Not applied to the Turf
// pool (Turf + one Wilds / Myriad is already the rule's pair there) or to the out-of-basics order. Part
// of LandSearchPickOrderKey (the pick-list memo is per thread and outlives a batch job).
static bool LandfallTitanMixed()
{
    static const bool on = EnvOn("MTG_LANDFALL_TITAN_MIXED");   // DEFAULT OFF (a proposal for the USER); =1 searches the mixed picks
    return heurarm::Flag(heurarm::LANDFALL_TITAN_MIXED, on);
}

// The user's Titan rule (see the block above): the indices of `picks` it keeps, in list order; EMPTY
// means "no narrowing" (every pick stays). Reads the pick list (a function of the library multiset),
// whether a land card is in hand, and g / r -- exactly what LandSearchPickOrderKey keys.
// `n_rule` (optional) receives how many of the returned indices are the rule's own picks; the rest
// (MTG_LANDFALL_TITAN_MIXED only) follow them, each part in list order.
std::vector<std::size_t> LandfallTitanAllowed(const GameState& s, int controller,
                                              const std::vector<std::vector<std::string>>& picks,
                                              std::size_t* n_rule = nullptr)
{
    std::vector<std::size_t> out;
    if (n_rule != nullptr) { *n_rule = 0; }
    if (picks.size() < 2) { return out; }
    std::vector<std::vector<TitanLand>> cls(picks.size());
    for (std::size_t i = 0; i < picks.size(); ++i)
    {
        for (const std::string& nm : picks[i]) { cls[i].push_back(TitanLandOf(CardDatabase::Instance().Lookup(nm))); }
    }
    // Read off the LIBRARY: the autonomous list holds no basic at all (LandSearchAdmitsLand).
    bool basics_left = false;
    for (const Card& c : s.players[static_cast<std::size_t>(controller)].library)
    {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(c);
        if (d != nullptr && d->card.IsLand() && IsBasicLandCard(*d)) { basics_left = true; break; }
    }
    if (!basics_left)
    {
        // Out of basics: Turf, Myriad, Radiant Fountain, Haunted Fengraf, any other land, Wilds -- the
        // pick whose lands rank best (sorted ranks compared lexicographically); ties keep list order.
        auto rank = [&](const std::string& nm, TitanLand t)
        {
            switch (t)
            {
                case TitanLand::Karoo:  return 0;
                case TitanLand::Myriad: return 1;
                case TitanLand::Fetch:  return 5;
                default: break;
            }
            return nm == "Radiant Fountain" ? 2 : nm == "Haunted Fengraf" ? 3 : 4;
        };
        std::size_t best = 0;
        std::vector<int> best_key;
        for (std::size_t i = 0; i < picks.size(); ++i)
        {
            std::vector<int> key;
            for (std::size_t j = 0; j < picks[i].size(); ++j) { key.push_back(rank(picks[i][j], cls[i][j])); }
            std::sort(key.begin(), key.end());
            // A longer pick (more lands) first: the maximal-pick fold leaves only full picks here anyway.
            key.insert(key.begin(), -static_cast<int>(key.size()));
            if (i == 0 || key < best_key) { best = i; best_key = std::move(key); }
        }
        out.push_back(best);
        if (n_rule != nullptr) { *n_rule = out.size(); }
        return out;
    }
    std::vector<std::size_t> pool;
    for (std::size_t i = 0; i < picks.size(); ++i) { pool.push_back(i); }
    const LandfallColourState r = ReadLandfallColours(s, controller);
    const bool short_colour = r.splash >= 0 && (r.g < 3 || r.r <= 1);
    bool turf_pool = false;
    if (!HandHasLand(s, controller) || short_colour)
    {
        std::vector<std::size_t> turf;
        for (std::size_t i : pool)
        { if (std::find(cls[i].begin(), cls[i].end(), TitanLand::Karoo) != cls[i].end()) { turf.push_back(i); } }
        if (!turf.empty()) { pool = std::move(turf); turf_pool = true; }
    }
    auto wm = [&](std::size_t i)
    {
        int n = 0;
        for (TitanLand t : cls[i]) { if (t == TitanLand::Fetch || t == TitanLand::Myriad) { ++n; } }
        return n;
    };
    int most = 0;
    for (std::size_t i : pool) { most = std::max(most, wm(i)); }
    if (most == 0)
    {
        if (turf_pool) { out = std::move(pool); }
        if (n_rule != nullptr) { *n_rule = out.size(); }
        return out;
    }
    for (std::size_t i : pool) { if (wm(i) == most) { out.push_back(i); } }
    if (n_rule != nullptr) { *n_rule = out.size(); }
    // The proposed amendment (LandfallTitanMixed, above): the picks holding fewer Wilds / Myriad but at
    // least one, searched AFTER the rule's own. Nothing to add when the rule already keeps every pick
    // holding one (most == 1), or in the Turf pool (its pairs are Turf + one Wilds / Myriad already).
    if (LandfallTitanMixed() && !turf_pool && most > 1)
    {
        for (std::size_t i : pool) { const int n = wm(i); if (n >= 1 && n < most) { out.push_back(i); } }
    }
    return out;
}
}   // namespace

bool LandfallProvider::LandSearchPickOrderKey(const GameState& s, int controller, std::uint64_t& key) const
{
    DecisionProvider::LandSearchPickOrderKey(s, controller, key);   // the base lack mask (5 bits)
    const LandfallColourState r = ReadLandfallColours(s, controller);
    key |= static_cast<std::uint64_t>(r.main + 1) << 5;
    key |= static_cast<std::uint64_t>(r.splash + 1) << 8;
    key |= static_cast<std::uint64_t>(std::min(r.g, 3)) << 11;
    key |= static_cast<std::uint64_t>(std::min(r.r, 2)) << 13;
    key |= static_cast<std::uint64_t>(r.myriad_situation ? 1 : 0) << 15;
    key |= static_cast<std::uint64_t>(HandHasLand(s, controller) ? 1 : 0) << 16;   // Titan's Turf test
    // The proposed Titan amendment widens the list; a per-job arm (heurarm) can flip it between jobs
    // that share this thread's memo, so it is part of the key.
    key |= static_cast<std::uint64_t>(LandfallTitanMixed() ? 1 : 0) << 17;
    // lib_main / lib_splash, and whether any basic is left for Titan, are functions of the library
    // multiset, which the memo key holds exactly.
    return true;
}

void LandfallProvider::LandSearchPickOrder(const GameState& s, int controller, int count, int to_hand,
                                           bool basic_only, bool share_land_type,
                                           std::vector<std::vector<std::string>>& picks) const
{
    DecisionProvider::LandSearchPickOrder(s, controller, count, to_hand, basic_only, share_land_type, picks);
    if (!basic_only)
    {
        // Titan: the rule's picks to the front, and within each part the picks holding a basic LAST
        // ("never search for a basic" -- the autonomous list has none; this keeps a basic off the human
        // prompt's default while a basic-free pick exists), each group keeping the base order.
        // Tier 0 = the rule's picks, 1 = the proposed amendment's extras (MTG_LANDFALL_TITAN_MIXED; empty
        // when it is off, so the order is the old in / out split), 2 = the rest.
        std::size_t n_rule = 0;
        const std::vector<std::size_t> keep = LandfallTitanAllowed(s, controller, picks, &n_rule);
        std::vector<char> tier(picks.size(), keep.empty() ? 0 : 2);
        for (std::size_t j = 0; j < keep.size(); ++j) { tier[keep[j]] = j < n_rule ? 0 : 1; }
        std::vector<char> basic(picks.size(), 0);
        for (std::size_t i = 0; i < picks.size(); ++i)
        {
            for (const std::string& nm : picks[i])
            {
                const CardDefinition* d = CardDatabase::Instance().Lookup(nm);
                if (d != nullptr && IsBasicLandCard(*d)) { basic[i] = 1; break; }
            }
        }
        std::vector<std::vector<std::string>> out;
        out.reserve(picks.size());
        for (int grp = 0; grp < 6; ++grp)
        {
            const char want_tier = static_cast<char>(grp / 2), want_basic = (grp % 2) ? 1 : 0;
            for (std::size_t i = 0; i < picks.size(); ++i)
            { if (tier[i] == want_tier && basic[i] == want_basic) { out.push_back(std::move(picks[i])); } }
        }
        picks = std::move(out);
        return;
    }
    if (picks.size() < 2) { return; }
    const LandfallColourState r = ReadLandfallColours(s, controller);
    if (r.splash < 0) { return; }
    std::string main_name, splash_name;
    LandfallColourNames(picks, r.main, r.splash, main_name, splash_name);
    const std::vector<std::string> want =
        LandfallRulePick(r, count, to_hand, share_land_type, main_name, splash_name);
    auto it = std::find(picks.begin(), picks.end(), want);
    if (it == picks.end() || it == picks.begin()) { return; }
    std::rotate(picks.begin(), it, it + 1);   // the rule's pick to the front; the rest keep their order
}

bool LandfallProvider::LandSearchAdmitsLand(const GameState& s, int controller, int count, int to_hand,
                                            bool basic_only, bool share_land_type, const CardDefinition& land) const
{
    (void)s; (void)controller; (void)count; (void)to_hand; (void)share_land_type;
    // USER 2026-10-16: "Primeval Titan must never search for a basic in my opinion." -- "basics are a
    // resource in the deck. You don't want to waste them when being able to choose any land." Titan's
    // is this list's only any-land search; a basic search admits its basics, of course.
    return basic_only || !IsBasicLandCard(land);
}

int LandfallProvider::LandSearchPickWidth(const GameState& s, int controller, int count, int to_hand,
                                          bool basic_only, bool share_land_type,
                                          const std::vector<std::vector<std::string>>& picks) const
{
    if (!basic_only)
    {
        // Titan: keep the rule's picks -- LandSearchPickOrder put them first, so they are a prefix (with
        // MTG_LANDFALL_TITAN_MIXED the amendment's extras follow them, still a prefix); a list the rule
        // does not narrow (or one that is not in that shape) keeps the full fan.
        const std::vector<std::size_t> keep = LandfallTitanAllowed(s, controller, picks);
        for (std::size_t i = 0; i < keep.size(); ++i)
        { if (keep[i] != i) { return static_cast<int>(picks.size()); } }
        return keep.empty() ? static_cast<int>(picks.size()) : static_cast<int>(keep.size());
    }
    if (picks.size() < 2) { return static_cast<int>(picks.size()); }
    const LandfallColourState r = ReadLandfallColours(s, controller);
    if (r.splash < 0) { return static_cast<int>(picks.size()); }
    std::string main_name, splash_name;
    LandfallColourNames(picks, r.main, r.splash, main_name, splash_name);
    // Prune to the rule's pick only when it IS the front (LandSearchPickOrder put it there); a state the
    // rule cannot express in this list keeps the full fan rather than pruning to an arbitrary entry.
    return picks.front() == LandfallRulePick(r, count, to_hand, share_land_type, main_name, splash_name)
        ? 1 : static_cast<int>(picks.size());
}

// ---- Base rules for the remaining ported built-ins -------------------------------------------
// Each reproduces the historical inline pick at index 0, so every port is byte-identical. See the
// hook declarations in DecisionProvider.h for what each rule says and where it looks weak.

std::vector<int> DecisionProvider::LightPawsAuraCandidates(
    const GameState& s, int controller, const Permanent& lightpaws,
    const std::vector<int>& legal) const
{
    const Player& ap = s.players[controller];
    // Rank by the power the Aura would REALIZE if attached now, not by a static coefficient: a
    // scaling Aura grants per matching permanent, so on a wide board its true contribution dwarfs a
    // flat +N. The fetched Aura is itself an enchantment you control, hence the +1 correction (see
    // the original note at the call site). MTG_LEGACY_LIGHTPAWS_STATIC restores the static rank.
    static const bool lp_static = EnvOn("MTG_LEGACY_LIGHTPAWS_STATIC");
    auto contrib = [&](int i) -> int {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(ap.library[i]);
        if (d == nullptr) { return 0; }
        if (lp_static) { return d->params.aura_power_bonus + d->params.aura_scale_power; }
        int c = d->params.aura_power_bonus;
        if (!d->params.aura_scale_kind.empty())
        {
            const int units = CountAuraScaleUnits(d->params.aura_scale_kind, lightpaws, s, controller) + 1;
            c += d->params.aura_scale_power * units;
        }
        return c;
    };
    auto mv = [&](int i) -> int {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(ap.library[i]);
        return d ? d->card.m_mana_cost.ManaValue() : -1;
    };
    // Where a SCALING Aura sits in the ranking (MTG_AURA_RANK_MODE):
    //   0 = legacy      power -> MV -> library order  (the historical rule)
    //   1 = scale-first SCALING -> power -> MV        (all scalers ahead of all flat Auras)
    //   2 = scale-last  power -> MV -> SCALING        (scaling breaks EXACT ties only)
    //   3 = conditional  scale-first WHEN another Aura is castable this/next turn, else mode 2
    //   4 = last-chance   scale-first ONLY on the last fetch, or for a scaler already in hand
    //                     (the USER's rule, 2026-08-25 -- see mode4_scale_first below)
    //
    // Both beat legacy decisively and by almost the same margin (12600 fresh games/arm, seeds
    // 9001-9006, d0+d3+d5): mode 1 -0.0067, mode 2 -0.0071, each 18 jobs better / 0 worse. The
    // shared win is real and comes from the same place -- realized power prices the board as it
    // stands, which systematically undervalues an Aura whose whole point is that it grows. Ethereal
    // Armor (+1/+1 per enchantment) and Audacity (+2/+2 flat) tie at two enchantments and the Armor
    // is strictly ahead from the third on; in an Auras deck a third is coming, and under legacy ~18
    // fetches per 250 games landed on the flat card by LIBRARY ORDER alone.
    //
    // Mode 1 is the default: scaling Auras COMPOUND with each other. Each one reads the count of
    // enchantments you control, so a third scaler does not add its own power -- it raises the power
    // of every scaler already attached. Realized power at fetch time cannot see that, and it is why
    // trading a scaler for a flat Aura of EQUAL current power is a much worse deal than it looks.
    //
    // Worked case (Auras gi=309, d3, full logs in the commit message): mode 1 fetches All That
    // Glitters then Ethereal Armor and wins T4 with THREE scaling Auras on board; mode 2 fetches
    // Armadillo Cloak (flat +2, MV 3 -- it wins the MV rung at equal power) and needs T5, despite
    // casting its Ancestral Mask a turn EARLIER. That is the whole argument in one game.
    //
    // Mode 2 measures 0.0003 ahead over 72000 disjoint games, and that gap is NOT a preference for
    // flat Auras: inspecting every divergent game, mode 2's wins come from the re-valuation changing
    // which Aura the search casts FROM HAND (a tempo side-effect), not from a better fetch. See
    // gi=1472, where mode 2 casts All That Glitters on T3 instead of Spirit Link and simply attacks
    // for more. Weighed against a mechanism that is real in every game, 0.0003 of cast-order churn
    // is not a reason to prefer the flat Aura.
    // DEFAULT = 4, the user's last-chance rule (2026-08-25). Measured against mode 1 on the Auras
    // deck, 500-per-seed held-out plus 400-per-seed train, 2700 games:
    //     train    2002 0.0000   3003 -0.0025   4004 -0.0025
    //     held-out 10010 +0.0020 11011 0.0000   12012 0.0000
    // i.e. a WASH on win turn (net -0.0030 summed), which is what the user predicted -- "this might
    // not provide that much benefit in terms of win-turn, but is a good idea in our heuristic". What
    // it buys is the BEHAVIOUR (200-game fetch census, MTG_TRACE=aura): Rancor 55 -> 63 fetches and
    // 4th -> 2nd most-fetched, while Ethereal Armor stays the most-fetched card at 97 (was 102) --
    // "we still want to get Ethereal Armor most of the time" holds. MTG_AURA_RANK_MODE=1 restores
    // the unconditional scale-first default for the A/B.
    static const int s_rank_mode = []{
        const char* e = std::getenv("MTG_AURA_RANK_MODE");
        return (e && *e) ? std::atoi(e) : 4;   // last-chance scale-first (see the note above)
    }();
    auto scales = [&](int i) -> bool {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(ap.library[i]);
        return d && !d->params.aura_scale_kind.empty() && d->params.aura_scale_power > 0;
    };
    // Mode 3 -- ask the question the other modes only guess at. A scaling Aura is worth taking while
    // it is a point behind IFF more enchantments are actually coming; otherwise the +3/+3 is simply
    // better and should win. So look at the HAND: is another Aura castable this turn or next?
    // If yes, prefer the scaler (it will be ahead shortly, and by more than one -- casting that Aura
    // fires Light-Paws again, so it adds TWO enchantments, itself and its fetch). If no, fall
    // through to the straight power comparison.
    // "This turn or next" is modelled as MV <= lands in play + 1 (next turn's land drop). Deliberately
    // generous: the failure it guards against is taking a scaler that never grows, and a hand with a
    // castable Aura in it is exactly the case where it does.
    auto another_aura_soon = [&]() -> bool {
        int lands = 0;
        for (const Permanent& p : s.battlefield)
        { if (p.controller_index == controller && p.card.IsLand()) { ++lands; } }
        const int reach = lands + 1;
        for (const Card& c : ap.hand)
        {
            const CardDefinition* d = CardDatabase::Instance().LookupCached(c);
            if (d && d->params.is_aura && d->card.m_mana_cost.ManaValue() <= reach) { return true; }
        }
        return false;
    };
    // Mode 4 -- the USER's rule (2026-08-25), reported as "Auras aren't fetched in the right order:
    // it prioritizes Ethereal Armor even though Rancor is better as you are about to play Rancor".
    // Mode 1 puts EVERY scaling Aura ahead of EVERY flat one unconditionally, so Ethereal Armor beats
    // Rancor no matter what is in hand or in the plan. The user's rule keeps the scaler for the cases
    // where it is the LAST chance at it, and takes the flat Aura otherwise:
    //
    //     take the SCALER  iff  this is the last 1-drop Aura fetch in the plan
    //                       OR  the scaler is about to be cast from hand before another fetch fires
    //     else             take the flat Aura
    //
    // "Last fetch in the plan" is the negation of another_aura_soon(): each Aura you CAST fires
    // Light-Paws again, so another castable Aura in hand IS another fetch coming. "About to be cast
    // before we can get it" is a same-NAME copy already in hand -- fetching it then duplicates
    // something the line delivers anyway, and the flat Aura is the one you cannot otherwise get.
    // Applied per-CANDIDATE (a scaler in hand does not speak for a scaler that is not), so the
    // comparator asks it of each side rather than flipping one global switch.
    auto in_hand_by_name = [&](int i) -> bool {
        const InternedName& nm = ap.library[i].m_name;
        for (const Card& c : ap.hand) { if (c.m_name == nm) { return true; } }
        return false;
    };
    const bool more_fetches_coming = another_aura_soon();
    // MTG_LP_FETCH_USER_RULE (heurarm LP_FETCH_USER_RULE, DEFAULT OFF -- the USER's open question Q20,
    // docs/design/auras-cast-order-2026-10-14.md). The rule above reads "last fetch" as "no Aura of ANY mana
    // value castable this turn OR NEXT", which is not what the USER said: the wording is the last fetch IN
    // THE PLAN, and a later fetch only matters if it could still TAKE this scaler. Under the arm a scaler
    // leads iff no later fetch of this turn's line can reach it:
    //   * the line's remaining Aura casts are the hand's Auras in the deck's own cast order, each kept while
    //     the mana left still pays it on top of the ones before it (AvailableManaPool = the untapped
    //     sources plus the prepaid float the plan's later casts drain -- the plan itself is not visible at a
    //     resolution, so "castable from what is left" stands in for "cast by the plan");
    //   * walking them in order: a SAME-NAME copy first means ours is cast before another fetch can take it
    //     (once it is controlled no fetch may name it) -> take it NOW, the USER's second clause; a cast of
    //     mana value >= the scaler's first means that cast's fetch can still take it -> take the flat Aura;
    //   * neither -> this is the last fetch that can reach it -> take it.
    // A scaler that leads competes with the other leaders on realized power, so a Mask (+2 per other
    // enchantment) beats a duplicate Armor (+1 each) whenever the Mask is also last-chance -- the draft's
    // finding (b): the pre-arm rule let the Armor copy in hand outrank a Mask unconditionally.
    static const bool s_lp_user_rule_env = EnvOn("MTG_LP_FETCH_USER_RULE");   // DEFAULT OFF (measurement arm)
    const bool lp_user_rule = s_rank_mode == 4
                           && heurarm::Flag(heurarm::LP_FETCH_USER_RULE, s_lp_user_rule_env);
    std::vector<const Card*> line_auras;   // the rest of this turn's Aura casts, in cast order
    if (lp_user_rule)
    {
        std::vector<std::pair<int, const Card*>> hand_auras;
        for (const Card& c : ap.hand)
        {
            const CardDefinition* d = CardDatabase::Instance().LookupCached(c);
            if (d && d->params.is_aura && !d->params.is_land_aura) { hand_auras.emplace_back(CastOrderRank(s, *d), &c); }
        }
        std::stable_sort(hand_auras.begin(), hand_auras.end(),
                         [](const auto& x, const auto& y) { return x.first < y.first; });
        const ManaPool left = AvailableManaPool(s);
        ManaCost committed;
        for (const auto& [rank, c] : hand_auras)
        {
            (void)rank;
            const CardDefinition* d = CardDatabase::Instance().LookupCached(*c);
            const ManaCost need = AddManaCosts(committed, d->card.m_mana_cost);
            if (!left.CanPay(need)) { continue; }
            committed = need;
            line_auras.push_back(c);
        }
    }
    auto last_chance = [&](int i) -> bool {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(ap.library[i]);
        const int m = d ? d->card.m_mana_cost.ManaValue() : 0;
        for (const Card* c : line_auras)
        {
            if (c->m_name == ap.library[i].m_name) { return true; }   // our copy goes first: last chance
            const CardDefinition* hd = CardDatabase::Instance().LookupCached(*c);
            if (hd && hd->card.m_mana_cost.ManaValue() >= m) { return false; }   // its fetch can still take it
        }
        return true;
    };
    // Under mode 4 a scaling candidate keeps its head start only when this is the last fetch, or when
    // that very Aura would otherwise arrive from hand first.
    // MTG_LP_FETCH_MV_AWARE (heurarm LP_FETCH_MV_AWARE, DEFAULT OFF -- the NARROW reading of Q20). Found
    // root-causing the Auras order's slower games (docs/design/auras-cast-order-2026-10-14.md section 6): the
    // approved order casts a 2-drop plain Aura before the 1-drops, and the "another Aura castable this turn or
    // next" test then calls its fetch not-last because a 1-drop is still in hand -- although a 1-drop's fetch
    // (mana value <= 1) can never take All That Glitters. This arm keeps mode 4's horizon and its same-name
    // clause and changes only that: an Aura in hand counts as a later fetch for a candidate iff its own mana
    // value reaches the candidate's. (The broader MTG_LP_FETCH_USER_RULE also drops "or next turn", which the
    // measurement found takes a growing scaler over a bigger flat Aura on the last fetch of a turn whose next
    // turn still casts Auras -- same section.)
    static const bool s_lp_mv_aware_env = EnvOn("MTG_LP_FETCH_MV_AWARE");   // DEFAULT OFF (measurement arm)
    const bool lp_mv_aware = s_rank_mode == 4 && !lp_user_rule
                          && heurarm::Flag(heurarm::LP_FETCH_MV_AWARE, s_lp_mv_aware_env);
    auto later_fetch_reaches = [&](int i) -> bool {
        int lands = 0;
        for (const Permanent& p : s.battlefield)
        { if (p.controller_index == controller && p.card.IsLand()) { ++lands; } }
        const int reach = lands + 1;
        const int need  = mv(i);
        for (const Card& c : ap.hand)
        {
            const CardDefinition* d = CardDatabase::Instance().LookupCached(c);
            if (!d || !d->params.is_aura) { continue; }
            const int hmv = d->card.m_mana_cost.ManaValue();
            if (hmv <= reach && hmv >= need) { return true; }
        }
        return false;
    };
    auto mode4_scale_first = [&](int i) -> bool {
        if (lp_user_rule) { return scales(i) && last_chance(i); }
        if (lp_mv_aware)  { return scales(i) && (!later_fetch_reaches(i) || in_hand_by_name(i)); }
        return scales(i) && (!more_fetches_coming || in_hand_by_name(i));
    };
    const bool scale_first_now = (s_rank_mode == 1)
                              || (s_rank_mode == 3 && another_aura_soon());
    std::vector<int> out = legal;
    // Every comparison is strict, so the FIRST library index wins any remaining tie -- which
    // stable_sort preserves (that is what keeps mode 0 byte-identical to the historical scan).
    std::stable_sort(out.begin(), out.end(), [&](int a, int b) {
        if (s_rank_mode == 4)
        {
            const bool sa = mode4_scale_first(a), sb = mode4_scale_first(b);
            if (sa != sb) { return sa; }        // only a scaler this is the last chance at leads
        }
        else if (scale_first_now)
        {
            const bool sa = scales(a), sb = scales(b);
            if (sa != sb) { return sa; }        // all scaling Auras ahead of all flat ones
        }
        const int ca = contrib(a), cb = contrib(b);
        if (ca != cb) { return ca > cb; }       // then greatest realized power
        const int ma = mv(a), mb = mv(b);
        if (ma != mb) { return ma > mb; }       // then highest mana value
        if (s_rank_mode == 2 || s_rank_mode == 3)
        {
            const bool sa = scales(a), sb = scales(b);
            if (sa != sb) { return sa; }        // exact-tie preference (also mode 3's fallback)
        }
        return false;
    });
    // Contention probe (MTG_TRACE=aura) -- is this fetch a real decision, or does the top pick win
    // outright? The triage question for whether to BRANCH this tutor rather than take front(): a
    // fetched Aura PERSISTS (unlike the legend-rule keep, whose differences the next untap erased),
    // so a wrong pick here is not self-correcting. `gap` is the realized-power margin over the
    // runner-up: gap=0 means the heuristic broke a genuine tie and the search never saw the choice.
    // Real resolution only, so rollout re-evaluations do not flood it.
    if (TRACE_ON("aura") && g_real_resolution && !out.empty())
    {
        const int top = contrib(out.front());
        const int second = out.size() > 1 ? contrib(out[1]) : top;
        TRACE("aura", "legal=%zu gap=%d pick=%s(%d) runnerup=%s", out.size(), top - second,
              ap.library[out.front()].m_name.str().c_str(), top,
              out.size() > 1 ? ap.library[out[1]].m_name.str().c_str() : "-");
    }
    return out;
}

std::vector<std::string> DecisionProvider::TutorHandPutList(
    const GameState& s, int controller, const CardParams& pp, int max_puts) const
{
    // Default (deck-agnostic): library order over the cards passing the tutor's type + numeric
    // filters, one entry per COPY, truncated to max_puts. See the header contract; an archetype
    // provider overrides with a ranking (missing combo outlet first, then a dork).
    std::vector<std::string> out;
    for (const Card& lc : s.players[controller].library)
    {
        if (static_cast<int>(out.size()) >= max_puts) { break; }
        const CardDefinition* d    = CardDatabase::Instance().LookupCached(lc);
        const Card&           card = d ? d->card : lc;
        bool type_ok = false;
        for (const std::string& t : pp.tutor_types)
        { if (CardMatchesTypeName(card, t)) { type_ok = true; break; } }
        if (type_ok && TutorNumericFilterOk(card, pp)) { out.push_back(lc.m_name.str()); }
    }
    return out;
}

std::vector<std::string> DecisionProvider::SacTutorPutList(
    const GameState& s, int controller, const CardParams& /*pp*/, int max_puts) const
{
    // Defense of the Heart default: deterministic closed-form immediate-drain maximisation.
    // Enumerate singles + ordered pairs of library creature NAMES (repeats allowed up to copy
    // count) and score the burst each sequence realises the moment it enters, using the same
    // arithmetic the engine's resolution applies (see PerformUpkeepSacTutor):
    //   - a gift-maker's tokens each drain the CURRENT enter-watch total (Suture Priests);
    //   - a sweeper kills every opp creature with toughness - damage <= debuff, each death
    //     draining the CURRENT death-watch total (Massacre Wurms, incl. the newcomer itself);
    //   - a watcher entering EARLIER in the sequence raises the multiplier for later cards.
    // Total printed power breaks ties (attack value). Fires at most once per game per copy
    // (the permanent is sacrificed), so the ~O(names^2) scan is cheap.
    const Player& ap  = s.players[controller];

    int enter_drain = 0, death_drain = 0;
    std::vector<int> opp_margin;   // per opp creature: effective toughness - marked damage
    for (const Permanent& p : s.battlefield)
    {
        if (p.controller_index == controller)
        {
            const CardDefinition* d = CardDatabase::Instance().LookupCached(p.card);
            if (d)
            {
                enter_drain += d->params.opp_creature_enters_life_loss;
                death_drain += d->params.opp_dies_life_loss;
            }
        }
        else if (p.card.IsCreature() || p.is_animated)
        {
            opp_margin.push_back(p.EffectiveToughness() - p.damage);
        }
    }

    // Distinct library creature names + copy counts. Keyed by the card's canonical
    // CardDefinition* (LookupCached returns the SAME pointer for every copy of a name), which is
    // byte-identical to name-keying -- one definition per name -- but skips the per-card std::string
    // construction (`.str()`) and string hashing that showed up hot on this DotH-heavy deck. The map
    // is only ever count-queried, never iterated, so the pointer key's arbitrary order is irrelevant;
    // `names` (a vector) still carries the library first-occurrence order that the enumeration below
    // depends on.
    std::vector<const CardDefinition*>            names;
    std::map<const CardDefinition*, int>          copies;
    for (const Card& lc : ap.library)
    {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(lc);
        if (!d || !d->card.IsCreature()) { continue; }
        if (copies[d]++ == 0) { names.push_back(d); }
    }
    if (names.empty() || max_puts <= 0) { return {}; }

    auto seq_value = [&](const std::vector<const CardDefinition*>& seq) -> long long {
        int P = enter_drain, W = death_drain;
        std::vector<int> margin = opp_margin;
        long long burst = 0, power = 0;
        // All puts enter SIMULTANEOUSLY (see PerformUpkeepSacTutor), so EVERY newcomer's
        // watchers are live before any enter-trigger resolves: a double Massacre Wurm drains
        // 4 per swept creature, not 2+0.
        for (const CardDefinition* d : seq)
        {
            P += d->params.opp_creature_enters_life_loss;
            W += d->params.opp_dies_life_loss;
        }
        // Then the enter-triggers resolve in list order (gifts before sweeps when we order
        // them that way -- the ordered-pair enumeration below tries both). Sweeps STACK the
        // until-EOT debuff on survivors, mirroring the engine's temp_tough_bonus: the second
        // sweep of a double-Wurm put kills at cumulative -4/-4. Gifted tokens appended after
        // a sweep only see later sweeps (CR 611.2c set-locking), also mirrored here.
        for (const CardDefinition* d : seq)
        {
            const CardParams& cp = d->params;
            if (cp.etb_opp_creates_tokens > 0)
            {
                burst += static_cast<long long>(cp.etb_opp_creates_tokens) * P;
                for (int k = 0; k < cp.etb_opp_creates_tokens; ++k)   // gifts -> sweep fodder
                { margin.push_back(std::max(1, cp.etb_created_token_toughness)); }
            }
            if (cp.etb_opp_creatures_debuff > 0)
            {
                std::size_t live = 0;
                for (int& m : margin)
                {
                    m -= cp.etb_opp_creatures_debuff;
                    if (m > 0) { margin[live++] = m; }
                    else       { burst += W; }
                }
                margin.resize(live);
            }
            power += std::max(0, d->card.m_power.value_or(0));
        }
        return burst * 64 + power;   // burst dominates; power is a pure tiebreak
    };

    std::vector<const CardDefinition*> best_seq;
    long long best_val = -1;
    // Singles.
    for (const CardDefinition* a : names)
    {
        std::vector<const CardDefinition*> seq{a};
        long long v = seq_value(seq);
        if (v > best_val) { best_val = v; best_seq = seq; }
    }
    // Ordered pairs (same-name pairs allowed when >= 2 copies remain in the library).
    if (max_puts >= 2)
    {
        for (const CardDefinition* a : names)
        for (const CardDefinition* b : names)
        {
            if (a == b && copies[a] < 2) { continue; }
            std::vector<const CardDefinition*> seq{a, b};
            long long v = seq_value(seq);
            if (v > best_val) { best_val = v; best_seq = seq; }
        }
    }

    std::vector<std::string> out;
    out.reserve(best_seq.size());
    for (const CardDefinition* d : best_seq) { out.push_back(d->card.m_name.str()); }
    return out;
}

std::vector<int> DecisionProvider::SacrificeLandCandidates(
    const GameState& s, int /*controller*/, const std::vector<int>& land_indices) const
{
    // Historical rule: the first TAPPED land if any, else the first land. Reproduced as "tapped
    // before untapped, stable within each band" -- index 0 is the same land as before.
    //
    // MTG_SAC_SPAWN_LAND_LAST (DEFAULT ON, adopted 2026-08-26 (=0 disables) -- overhaul ledger cg30):
    // a token-spawn land (Forbidden Orchard, taps_spawn_opp_token) is a per-turn damage engine
    // (one opponent Spirit per turn = Suture Priest drip + Massacre Wurm death payoff), and a
    // sacrifice destroys it PERMANENTLY -- the same irrecoverable-source shape as the fuel-dork
    // tap rank (Deathrite). Tapped-first alone eats it whenever the turn's payment happened to
    // tap it before the sac fires (under MTG_DORK_TAP_LAST's lands-first order, reliably), and
    // the sac target is NOT a search branch, so no budget/depth recovers the loss: cg30's T4 win
    // exists for the executor (forced-walk proof in the ledger) but every searched line sacked
    // the Orchard and scored 5. Since MTG_SAC_AXIS the target IS a branch (Plan::sac_pins), and
    // this ranking is its PRIOR: the branch order for cutoffs, and the only decision on the
    // plan-less paths (d0 greedy, rollouts) and for the base plan's default.
    //
    // Band order under the lever (USER doctrine, 2026-08-25: "sacrifice Orchard last. Anything
    // else is a better choice except maybe the bounceland"): fungible lands first (tapped-first
    // within), then BOUNCELANDS (etb_bounce_land -- a Karoo taps for two, so it is 2 mana/turn
    // of ongoing production vs a fungible land's 1), then spawn lands strictly last. A board
    // with only spawn lands is unchanged.
    static const bool s_spawn_last = EnvOn("MTG_SAC_SPAWN_LAND_LAST", true);
    std::vector<int> out = land_indices;
    std::stable_sort(out.begin(), out.end(), [&](int a, int b) {
        if (s_spawn_last)
        {
            auto band = [&](int i) {
                const CardDefinition* d = CardDatabase::Instance().LookupCached(s.battlefield[i].card);
                if (d == nullptr) { return 0; }
                if (d->params.taps_spawn_opp_token) { return 2; }
                if (d->params.etb_bounce_land)      { return 1; }
                return 0;
            };
            const int ba = band(a), bb = band(b);
            if (ba != bb) { return ba < bb; }
        }
        return s.battlefield[a].tapped && !s.battlefield[b].tapped;
    });
    return out;
}

static bool BounceReplayEntersUntapped(const GameState& s, int controller, int idx,
                                       const CardDefinition& d);

std::vector<int> DecisionProvider::BounceLandCandidates(
    const GameState& s, int controller, int /*self_index*/,
    const std::vector<int>& legal) const
{
    // SPARE THE ENCHANTED LAND (MTG_BOUNCE_SPARE_AURA, default ON; 2026-09-15). Returning a land
    // that carries an Aura sends the Aura to the graveyard (CR 303.4d) -- the bounce costs a card
    // AND the ramp it bought, which no tapped/untapped tempo can repay. claude_s12_gi11 T3: the
    // search's Trace of Abundance rode Brushland and its Azorius Chancery then bounced that very
    // land, so its "ramp" turn ended with the Aura in the graveyard. Ranked below every other
    // option rather than excluded (the bounce is mandatory; with one land it is still the pick).
    static const bool s_spare_aura_env = EnvOn("MTG_BOUNCE_SPARE_AURA", true);
    const bool spare_aura = heurarm::Flag(heurarm::BOUNCE_SPARE_AURA, s_spare_aura_env);
    // KAROO TAP-IN-RESPONSE + the USER's order, ONE lever (KarooTapInResponseOn, EngineFlags.h).
    const bool tap_in_response = KarooTapInResponseOn();
    const bool precise_replay  = BounceReplayPreciseOn();
    auto carries_aura = [&](const Permanent& land) -> bool {
        for (const Permanent& q : s.battlefield)
        { if (q.aura_attached_to != 0 && q.aura_attached_to == land.card.m_number) { return true; } }
        return false;
    };
    auto score = [&](int i) -> long {
        const Permanent& p = s.battlefield[i];
        const CardDefinition* d = CardDatabase::Instance().LookupCached(p.card);
        const bool is_karoo = d && d->params.etb_bounce_land;
        // MTG_BOUNCE_REPLAY_PRECISE: the replay as the board will see it (a reveal land with nothing
        // to reveal re-enters tapped) instead of the enters_tapped param alone.
        const bool enters_untapped = precise_replay
            ? (d != nullptr && BounceReplayEntersUntapped(s, controller, i, *d))
            : !(d && (d->params.enters_tapped || d->params.enters_tapped_with_depletion > 0));
        long v = 0;
        if (is_karoo)        { v -= 1000; }   // never re-trigger the bounce loop
        if (tap_in_response)
        {
            // USER 2026-10-06 (Hinata: a tapped Mystic Monastery was recommended over an untapped
            // Forbidden Orchard): "Generally the Orchard is better to bounce because the monastery
            // will come into play tapped again." That holds BECAUSE the returned land is tapped for
            // mana in response (BounceKarooLand -> FloatKarooBouncedLand), so an untapped FLOATABLE
            // land costs nothing this phase -- it joins the already-tapped lands in the no-loss
            // tier, and the REPLAY's tempo decides among them. Its predicate is the apply's own
            // (KarooBounceFloatable), so the ranking never assumes a float the apply will not make:
            // an untapped land that cannot be tapped for free (a painland) keeps the old rank. Last,
            // a spent land beats an untapped floatable one that replays equally well (its float
            // dies at the end of the phase; the untapped land would still be there for main 2).
            // With no untapped floatable land on the board this is the base ordering exactly.
            const bool no_loss = p.tapped || (d != nullptr && KarooBounceFloatable(s, p, *d));
            if (no_loss)         { v += 100; }
            if (enters_untapped) { v += 20;  }
            if (p.tapped)        { v += 5;   }
        }
        else
        {
            if (p.tapped)        { v += 100;  }   // already spent -> no mana lost this turn
            if (enters_untapped) { v += 10;   }   // clean replay
        }
        if (spare_aura && carries_aura(p)) { v -= 500; }   // the Aura would die with the bounce
        return v;
    };
    // The original scan kept a strict `>` winner, so the LOWEST index wins ties -- stable_sort on a
    // descending score over an ascending input reproduces that. Each candidate's score is computed
    // ONCE (it reads only the board, never the order): the comparator used to recompute both sides
    // on every comparison -- an O(n log n) x board-width aura scan per bounce, and a fetched Gruul
    // Turf bounces inside every Landfall rollout (perf 2026-10-15). Same keys, same stable order.
    std::vector<std::pair<long, int>> keyed;
    keyed.reserve(legal.size());
    for (int i : legal) { keyed.emplace_back(score(i), i); }
    std::stable_sort(keyed.begin(), keyed.end(),
                     [](const std::pair<long, int>& a, const std::pair<long, int>& b)
                     { return a.first > b.first; });
    std::vector<int> out;
    out.reserve(keyed.size());
    for (const auto& kv : keyed) { out.push_back(kv.second); }
    // THE USER'S DEFAULT (MTG_BOUNCE_USER_RULE): a tapped land that re-enters untapped and makes no
    // colour another kept land does not is THE pick -- the front, so the d0 runner, the playout beyond
    // the horizon, the base plan and the prompt's default all take it (BounceSearchCandidates offers
    // nothing else).
    if (BounceUserRuleActive())
    {
        const int pick = BounceUserRulePick(s, controller, legal, out);
        if (pick >= 0 && out.front() != pick)
        {
            out.erase(std::remove(out.begin(), out.end(), pick), out.end());
            out.insert(out.begin(), pick);
        }
    }
    return out;
}

// Does this battlefield land enter UNTAPPED when it is replayed -- on the board the bounce leaves (the
// land itself gone, the Karoo on the battlefield)? A basic does; a tapland, a Karoo and a depletion
// land do not; a fastland / checkland / shock / reveal / control land only if its condition would hold.
static bool BounceReplayEntersUntapped(const GameState& s, int controller, int idx,
                                       const CardDefinition& d)
{
    const CardParams& q = d.params;
    if (q.etb_bounce_land || q.enters_tapped_with_depletion > 0) { return false; }
    if (q.etb_pay_life_to_untap > 0)
    { return s.players[static_cast<std::size_t>(controller)].life > q.etb_pay_life_to_untap; }
    if (!q.etb_untap_reveal_subtypes.empty()) { return LandControlUntapMet(s, d) || LandCanReveal(s, d); }
    if (!q.etb_untap_control_subtypes.empty()) { return LandControlUntapMet(s, d); }
    if (q.fastland_max_other_lands >= 0)
    {
        int other = 0;   // the lands the replay will see: every land we control now, but this one
        for (int i = 0; i < static_cast<int>(s.battlefield.size()); ++i)
        {
            const Permanent& p = s.battlefield[static_cast<std::size_t>(i)];
            if (i != idx && p.controller_index == controller && p.card.IsLand()) { ++other; }
        }
        return other <= q.fastland_max_other_lands;
    }
    if (!q.checkland_subtypes.empty())
    {
        for (int i = 0; i < static_cast<int>(s.battlefield.size()); ++i)
        {
            const Permanent& p = s.battlefield[static_cast<std::size_t>(i)];
            if (i == idx || p.controller_index != controller || !p.card.IsLand()) { continue; }
            const CardDefinition* od = CardDatabase::Instance().LookupCached(p.card);
            const SubtypeSet& subs = od ? od->card.m_subtypes : p.card.m_subtypes;
            for (const std::string& want : q.checkland_subtypes)
            { for (const std::string& st : subs) { if (st == want) { return true; } } }
        }
        return false;
    }
    return !q.enters_tapped;
}

bool DecisionProvider::BounceUserRuleActive() const { return BounceUserRuleOn(); }

// Hinata carries its own rule (MTG_HINATA_BOUNCE_RULE), so it is live here whatever the base default.
bool HinataProvider::BounceUserRuleActive() const
{
    return (HinataBounceRuleOn() && KarooTapInResponseOn()) || BounceUserRuleOn();
}

int DecisionProvider::BounceUserRulePick(const GameState& s, int controller, const std::vector<int>& legal,
                                         const std::vector<int>& order, int* qualifying_names) const
{
    if (qualifying_names != nullptr) { *qualifying_names = 0; }
    // AMENDMENT (MTG_BOUNCE_RULE_AMEND; Dragons s7007 gi959). Haven of the Spirit Dragon's colours are
    // CREATURE-ONLY: counting them as colours it "makes" let a kept Haven cover every colour, so the
    // rule returned the tapped Mountain and kept the Haven -- and from that board even an unbounded
    // depth-8 search wins a turn later (T6, against T5 with the Haven returned). Amended: a land's
    // USABLE colours exclude creature-only ones, on both sides of the coverage test.
    const bool amend = BounceRuleAmendOn();
    // The colours one land makes, as a WUBRG bitmask (colourless makes none) -- INCLUDING what a land
    // Aura on it adds (Wild Growth's {G}): an enchanted land stays, so its whole output covers.
    auto colours = [&](const Permanent& p) -> unsigned {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(p.card);
        if (d == nullptr) { return 0u; }
        unsigned m = static_cast<unsigned>(LandAuraColorMask(s, p)) & 31u;
        if (amend && d->params.colored_creature_only) { return m; }   // creature-only colours: not usable
        for (Color c : EffectiveProducesFor(s, controller, *d, &p))
        {
            switch (c)
            {
                case Color::White: m |= 1u;  break;
                case Color::Blue:  m |= 2u;  break;
                case Color::Black: m |= 4u;  break;
                case Color::Red:   m |= 8u;  break;
                case Color::Green: m |= 16u; break;
                default: break;
            }
        }
        return m;
    };
    // The returnable candidates: `legal` less the Karoo / Aura exclusions BounceSearchCandidates makes
    // while any other land is returnable (the order already ranks them last).
    static const bool s_spare_aura_env = EnvOn("MTG_BOUNCE_SPARE_AURA", true);
    const bool spare_aura = heurarm::Flag(heurarm::BOUNCE_SPARE_AURA, s_spare_aura_env);
    auto is_karoo = [&](int i) {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(s.battlefield[static_cast<std::size_t>(i)].card);
        return d != nullptr && d->params.etb_bounce_land;
    };
    auto enchanted = [&](int i) {
        const int num = s.battlefield[static_cast<std::size_t>(i)].card.m_number;
        for (const Permanent& q : s.battlefield) { if (q.aura_attached_to != 0 && q.aura_attached_to == num) { return true; } }
        return false;
    };
    auto has_aura = [&](int i) { return spare_aura && enchanted(i); };
    std::vector<int> pool = legal;
    auto drop_if_others = [&](auto pred) {
        bool other = false;
        for (int i : pool) { if (!pred(i)) { other = true; break; } }
        if (other) { pool.erase(std::remove_if(pool.begin(), pool.end(), pred), pool.end()); }
    };
    drop_if_others(is_karoo);
    drop_if_others(has_aura);
    std::vector<std::string> names;   // distinct qualifying names
    int pick = -1;
    // Our lands' colour masks (WUBRG bits 0..4) with kIsOurLand marking "a land we control", filled on
    // first use below -- see (3).
    constexpr unsigned kIsOurLand = 1u << 8;
    std::vector<unsigned> land_col;
    for (int i : order)   // the provider's order decides among several (amended: several -> the search)
    {
        if (std::find(pool.begin(), pool.end(), i) == pool.end()) { continue; }
        const Permanent& p = s.battlefield[static_cast<std::size_t>(i)];
        if (!p.tapped) { continue; }                                                   // (1)
        // USER: "we need an exemption for cases where the land has an aura on it of course." Never
        // the rule's pick, whatever the exclusions above left (the Aura would die with the bounce).
        if (enchanted(i)) { continue; }
        const CardDefinition* d = CardDatabase::Instance().LookupCached(p.card);
        if (d == nullptr || !BounceReplayEntersUntapped(s, controller, i, *d)) { continue; }   // (2)
        // (3) Each of our lands' colours computed ONCE per call (colours() reads only the board, so a
        // land's mask is the same for every candidate): it was recomputed for every land, per
        // candidate -- O(candidates x lands) EffectiveProducesFor calls on every Karoo bounce, and a
        // Titan-fetched Gruul Turf bounces inside every Landfall rollout (perf 2026-10-15). Same masks,
        // same OR, same answer.
        if (land_col.empty())
        {
            land_col.assign(s.battlefield.size(), 0u);
            for (int j = 0; j < static_cast<int>(s.battlefield.size()); ++j)
            {
                const Permanent& o = s.battlefield[static_cast<std::size_t>(j)];
                if (o.controller_index == controller && o.card.IsLand())
                { land_col[static_cast<std::size_t>(j)] = colours(o) | kIsOurLand; }
            }
        }
        unsigned kept = 0u;
        for (int j = 0; j < static_cast<int>(land_col.size()); ++j)
        {
            if (j != i && (land_col[static_cast<std::size_t>(j)] & kIsOurLand) != 0u)
            { kept |= land_col[static_cast<std::size_t>(j)] & 31u; }
        }
        const unsigned mine = colours(p);
        if ((mine & ~kept) != 0u) { continue; }
        const std::string nm = p.card.m_name.str();
        if (std::find(names.begin(), names.end(), nm) == names.end()) { names.push_back(nm); }
        if (pick < 0) { pick = i; }
    }
    if (qualifying_names != nullptr) { *qualifying_names = static_cast<int>(names.size()); }
    // Amended: the rule decides only when ONE land (identical copies fold) qualifies. When two
    // DIFFERENT lands both qualify, which one goes is a real decision -- it is next turn's board,
    // since the returned land usually waits behind another land drop -- and no fixed order gets it
    // right: Dragons s7007 gi959 needed the Haven returned (T5; the Mountain gives T6 even at d8
    // unbounded), s7007 gi888 needed the Mountain returned with the same two lands on offer (T5 vs
    // T6 at d8 unbounded), and a "fewest colours" order sent Selesnya's Blighted Steppe back over
    // Branchloft Pathway (s7007 gi75 / gi404, a turn each). Those boards go to the search.
    if (amend && names.size() > 1) { return -1; }
    return pick;
}

// THE USER'S HINATA KAROO RULE (see the declaration). Generic in everything but its ordering: the
// "colour the deck needs less" is DERIVED from the coloured pips of every nonland card the controller
// owns in the game (library, hand, graveyard, battlefield), so nothing about Mountain or Island is
// hardcoded -- on Hinata2 the derivation gives red < blue, i.e. "the mountain would go".
int HinataProvider::BounceUserRulePick(const GameState& s, int controller, const std::vector<int>& legal,
                                       const std::vector<int>& order, int* qualifying_names) const
{
    if (!HinataBounceRuleOn())
    { return DecisionProvider::BounceUserRulePick(s, controller, legal, order, qualifying_names); }
    if (qualifying_names != nullptr) { *qualifying_names = 0; }
    // Pip need per colour (WUBRG), over the deck as the game holds it.
    int need[5] = { 0, 0, 0, 0, 0 };
    auto add_pips = [&](const Card& c) {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(c);
        if (d == nullptr || d->card.IsLand()) { return; }
        const ManaCost& mc = d->card.m_mana_cost;
        need[0] += mc.white; need[1] += mc.blue; need[2] += mc.black; need[3] += mc.red; need[4] += mc.green;
    };
    const Player& me = s.players[static_cast<std::size_t>(controller)];
    for (const Card& c : me.library)   { add_pips(c); }
    for (const Card& c : me.hand)      { add_pips(c); }
    for (const Card& c : me.graveyard) { add_pips(c); }
    for (const StagedCard& c : me.staged_cards)       { add_pips(c.card); }
    for (const SuspendedCard& c : me.suspended_cards) { add_pips(c.card); }
    for (const Permanent& p : s.battlefield) { if (p.owner_index == controller && !p.is_token) { add_pips(p.card); } }
    // The colours a land makes, WUBRG bits 0..4 (colourless makes none). The candidates are never
    // enchanted, so a land Aura's colour cannot enter here.
    auto colours = [&](const Permanent& p) -> unsigned {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(p.card);
        if (d == nullptr) { return 0u; }
        unsigned m = 0u;
        for (Color c : EffectiveProducesFor(s, controller, *d, &p))
        {
            switch (c)
            {
                case Color::White: m |= 1u;  break;
                case Color::Blue:  m |= 2u;  break;
                case Color::Black: m |= 4u;  break;
                case Color::Red:   m |= 8u;  break;
                case Color::Green: m |= 16u; break;
                default: break;
            }
        }
        return m;
    };
    auto karoo_at = [&](int i) {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(s.battlefield[static_cast<std::size_t>(i)].card);
        return d != nullptr && d->params.etb_bounce_land;
    };
    bool non_karoo = false;
    for (int i : legal) { if (!karoo_at(i)) { non_karoo = true; break; } }
    struct Key { int colours; int copies; int need; int pos; int idx; };
    std::vector<Key> keys;
    std::vector<std::string> names;
    for (int pos = 0; pos < static_cast<int>(order.size()); ++pos)
    {
        const int i = order[static_cast<std::size_t>(pos)];
        if (std::find(legal.begin(), legal.end(), i) == legal.end()) { continue; }
        if (non_karoo && karoo_at(i)) { continue; }
        const Permanent& p = s.battlefield[static_cast<std::size_t>(i)];
        bool enchanted = false;   // the Aura exemption: never return an enchanted land
        for (const Permanent& a : s.battlefield)
        { if (a.aura_attached_to != 0 && a.aura_attached_to == p.card.m_number) { enchanted = true; break; } }
        if (enchanted) { continue; }
        const CardDefinition* d = CardDatabase::Instance().LookupCached(p.card);
        if (d == nullptr || !BounceReplayEntersUntapped(s, controller, i, *d)) { continue; }
        // An untapped land is returned only when its mana floats (the adopted tap-in-response
        // model): otherwise returning it throws its mana away, which is not what the rule assumes.
        if (!p.tapped && !(KarooFloatModelled() && KarooBounceFloatable(s, p, *d))) { continue; }
        const unsigned m = colours(p);
        int n_col = 0, n_need = 0;
        for (int c = 0; c < 5; ++c) { if (m & (1u << c)) { ++n_col; n_need += need[c]; } }
        int copies = 0;
        for (const Permanent& o : s.battlefield)
        { if (o.controller_index == controller && o.card.IsLand() && o.card.m_name == p.card.m_name) { ++copies; } }
        keys.push_back({ n_col, copies, n_need, pos, i });
        const std::string nm = p.card.m_name.str();
        if (std::find(names.begin(), names.end(), nm) == names.end()) { names.push_back(nm); }
    }
    if (keys.empty()) { return DecisionProvider::BounceUserRulePick(s, controller, legal, order, qualifying_names); }
    if (qualifying_names != nullptr) { *qualifying_names = static_cast<int>(names.size()); }
    // Fewest colours, then most copies, then the less-needed colour, then the base order.
    const Key* best = &keys.front();
    for (const Key& k : keys)
    {
        const auto rank = [](const Key& x) { return std::make_tuple(x.colours, -x.copies, x.need, x.pos); };
        if (rank(k) < rank(*best)) { best = &k; }
    }
    return best->idx;
}

// THE USER'S LANDFALL KAROO RULE (2026-10-16), for every Gruul Turf bounce (the land drop and a
// Titan-fetched Turf alike): "I would bounce in reverse order from colour requirements. So bounce any
// come-into-play-untapped land starting with the unnecessary first and then progressively more
// necessary. Colourless producing lands can go first, then extra red or green." The candidates are
// Hinata's: a land that re-enters untapped, already tapped or with its mana floated (the adopted
// tap-in-response model), never another Karoo or an enchanted land while another is returnable. The
// REQUIREMENT of a colour is the most pips of it on one nonland card we own in the game (Genesis Wave
// GGG, Omnath RR here -- the 3 green / 2 red the fetch rule builds toward); a land's SPARE is our lands
// making its colour, less that requirement (a two-colour land: its scarcer colour). Order: colourless,
// then the most spare, then tapped before untapped, then more copies, then the provider's order. The
// pick is returned with NO search (BounceSearchCandidates' user-rule tier); MTG_UNPRUNE=karoobounce
// reopens the search. No candidate -> the base rule.
int LandfallProvider::BounceUserRulePick(const GameState& s, int controller, const std::vector<int>& legal,
                                         const std::vector<int>& order, int* qualifying_names) const
{
    if (qualifying_names != nullptr) { *qualifying_names = 0; }
    int req[5] = { 0, 0, 0, 0, 0 };
    auto add_req = [&](const Card& c) {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(c);
        if (d == nullptr || d->card.IsLand()) { return; }
        const ManaCost& mc = d->card.m_mana_cost;
        req[0] = std::max(req[0], static_cast<int>(mc.white)); req[1] = std::max(req[1], static_cast<int>(mc.blue));
        req[2] = std::max(req[2], static_cast<int>(mc.black)); req[3] = std::max(req[3], static_cast<int>(mc.red));
        req[4] = std::max(req[4], static_cast<int>(mc.green));
    };
    const Player& me = s.players[static_cast<std::size_t>(controller)];
    for (const Card& c : me.library)   { add_req(c); }
    for (const Card& c : me.hand)      { add_req(c); }
    for (const Card& c : me.graveyard) { add_req(c); }
    for (const StagedCard& c : me.staged_cards)       { add_req(c.card); }
    for (const SuspendedCard& c : me.suspended_cards) { add_req(c.card); }
    for (const Permanent& p : s.battlefield) { if (p.owner_index == controller && !p.is_token) { add_req(p.card); } }
    // The colours a land makes, WUBRG bits 0..4 (colourless makes none).
    auto colours = [&](const Permanent& p) -> unsigned {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(p.card);
        if (d == nullptr) { return 0u; }
        unsigned m = static_cast<unsigned>(LandAuraColorMask(s, p)) & 31u;
        for (Color c : EffectiveProducesFor(s, controller, *d, &p))
        {
            const int ci = static_cast<int>(c);
            if (ci >= 0 && ci < 5) { m |= 1u << ci; }
        }
        return m;
    };
    int sources[5] = { 0, 0, 0, 0, 0 };
    for (const Permanent& p : s.battlefield)
    {
        if (p.controller_index != controller || !p.card.IsLand()) { continue; }
        const unsigned m = colours(p);
        for (int c = 0; c < 5; ++c) { if (m & (1u << c)) { ++sources[c]; } }
    }
    auto karoo_at = [&](int i) {
        const CardDefinition* d = CardDatabase::Instance().LookupCached(s.battlefield[static_cast<std::size_t>(i)].card);
        return d != nullptr && d->params.etb_bounce_land;
    };
    bool non_karoo = false;
    for (int i : legal) { if (!karoo_at(i)) { non_karoo = true; break; } }
    struct Key { int tier; int spare_neg; int untapped; int copies_neg; int pos; int idx; };
    std::vector<Key> keys;
    std::vector<std::string> names;
    for (int pos = 0; pos < static_cast<int>(order.size()); ++pos)
    {
        const int i = order[static_cast<std::size_t>(pos)];
        if (std::find(legal.begin(), legal.end(), i) == legal.end()) { continue; }
        if (non_karoo && karoo_at(i)) { continue; }
        const Permanent& p = s.battlefield[static_cast<std::size_t>(i)];
        bool enchanted = false;   // the Aura exemption: never return an enchanted land
        for (const Permanent& a : s.battlefield)
        { if (a.aura_attached_to != 0 && a.aura_attached_to == p.card.m_number) { enchanted = true; break; } }
        if (enchanted) { continue; }
        const CardDefinition* d = CardDatabase::Instance().LookupCached(p.card);
        if (d == nullptr || !BounceReplayEntersUntapped(s, controller, i, *d)) { continue; }
        if (!p.tapped && !(KarooFloatModelled() && KarooBounceFloatable(s, p, *d))) { continue; }
        const unsigned m = colours(p);
        int spare = 0;
        bool coloured = false;
        for (int c = 0; c < 5; ++c)
        {
            if (!(m & (1u << c))) { continue; }
            const int v = sources[c] - req[c];
            spare = coloured ? std::min(spare, v) : v;
            coloured = true;
        }
        int copies = 0;
        for (const Permanent& o : s.battlefield)
        { if (o.controller_index == controller && o.card.IsLand() && o.card.m_name == p.card.m_name) { ++copies; } }
        keys.push_back({ coloured ? 1 : 0, coloured ? -spare : 0, p.tapped ? 0 : 1, -copies, pos, i });
        const std::string nm = p.card.m_name.str();
        if (std::find(names.begin(), names.end(), nm) == names.end()) { names.push_back(nm); }
    }
    if (keys.empty()) { return DecisionProvider::BounceUserRulePick(s, controller, legal, order, qualifying_names); }
    if (qualifying_names != nullptr) { *qualifying_names = static_cast<int>(names.size()); }
    const Key* best = &keys.front();
    for (const Key& k : keys)
    {
        const auto rank = [](const Key& x)
        { return std::make_tuple(x.tier, x.spare_neg, x.untapped, x.copies_neg, x.pos); };
        if (rank(k) < rank(*best)) { best = &k; }
    }
    return best->idx;
}

// ---- LandfallProvider::CastOrderRank -- THE USER'S LANDFALL ORDER (2026-10-16) ------------------------
//
// USER, in order: "the tricky part about this deck is that you need to actually play lands, cast
// acceleration spells and activate abilities intentionally after the landfall creatures (or Khalni
// Heart) drop to get as much landfall as possible. That said, if mana is insufficient and the mana source
// must be played first you play it the other way around." -- "activations of Khalni Heart and Myriad
// Landscape would go at the end. Similarily cards like Rampant Growth and Search for Tomorrow suspend can
// go late. Cultivate, Search for Tomorrow Cast and land plays want to go late, but may be forced to go
// earlier for mana reasons (if they play or allow playing an untapped land)." -- "it isn't that they
// move earlier, it is that we test them in two spots and we prefer the one after the landfall sources."
// -- "They do move earlier than other spells though (and abilities)."
//
// So, per main phase: landfall sources, then the MANA-MAKING land entries (the land drop, the Search
// for Tomorrow cast, Cultivate), then the other spells, then the abilities. Tiers, all read off params:
//    1 a landfall WATCHER (CardDefinition::landfall_watcher -- Khalni, Baloths, Omnath, Avenger, Phylath,
//      Courser): first, so every land that enters this main triggers it.
//    2 a land-entering spell that makes MANA this turn: an untapped basic (Search for Tomorrow cast,
//      LandSearchPutsUntapped) or a basic to HAND, i.e. a land drop (Cultivate). Ahead of the other
//      spells it can fund; its SECOND spot, before the watchers, is searched (CastOrderingCandidates).
//    3 a cast that puts NO land (Terastodon).
//    4 a REVEAL-AND-PUT spell (Genesis Wave): its lands trigger the watchers already cast.
//    5 the other land-entering spells (Primeval Titan's ETB, Rampant Growth): their lands enter tapped.
// The rest of the rule is not a cast rank: the land drop's two spots are Plan::land_slot (first, or after
// the watchers), the land-search activations run in the main's trailing pass (Khalni's crack, Myriad,
// Evolving Wilds), and the Search for Tomorrow SUSPEND is a pre-cast action that puts no land this turn.
// Ties keep plan order. MTG_LANDFALL_ORDER=0 -> the generic rank, no ordering search (heurarm
// LANDFALL_ORDER, per job).
static bool LandfallOrderEnabled()
{
    static const bool on = EnvOn("MTG_LANDFALL_ORDER", true);   // DEFAULT ON (the USER's rule); =0 -> generic
    return heurarm::Flag(heurarm::LANDFALL_ORDER, on);
}

static bool LandfallManaLandEntry(const CardDefinition& def)
{
    const CardParams& p = def.params;
    return p.land_search_on_resolve && (LandSearchPutsUntapped(def) || p.land_search_to_hand > 0);
}

// THE FULL ORDER (USER: "we should actually make it a full order with all of the cards with a distinct
// number in case we choose to do condemnation later"). rank = 100 * tier + 10 * mana value + k: the tier
// from params (above), cheapest first inside a tier, and k the reviewed sequence where one tier holds two
// cards of one mana value -- Phylath before Rampaging Baloths, Avenger before Omnath (neither pair
// triggers the other: by name), Search for Tomorrow before Cultivate (its untapped basic can pay for
// Cultivate; Cultivate's basic only pays as the land drop). The deck's twelve spells then read:
//   120 Khalni Heart Expedition   130 Courser of Kruphix   161 Phylath   162 Rampaging Baloths
//   171 Avenger of Zendikar       172 Omnath               231 Search for Tomorrow   232 Cultivate
//   380 Terastodon                430 Genesis Wave         520 Rampant Growth        560 Primeval Titan
// A card off this list ties only on (tier, mana value) and then goes by NAME (CastOrderTotalByName).
static int LandfallTier(const CardDefinition& def)
{
    const CardParams& p = def.params;
    if (def.landfall_watcher)                                         { return 1; }
    if (LandfallManaLandEntry(def))                                   { return 2; }
    if (p.reveal_x_put_permanents)                                    { return 4; }
    if (p.land_search_on_resolve || p.land_search_on_enter_or_attack) { return 5; }
    return 3;
}

int LandfallProvider::CastOrderRank(const GameState& s, const CardDefinition& def) const
{
    if (!LandfallOrderEnabled()) { return DeckProvider::CastOrderRank(s, def); }
    const int mv = std::min(def.card.m_mana_cost.ManaValue(), 9);
    static const std::pair<const char*, int> kWithinManaValue[] = {
        {"Phylath, World Sculptor", 1}, {"Rampaging Baloths", 2},
        {"Avenger of Zendikar", 1},     {"Omnath, Locus of Rage", 2},
        {"Search for Tomorrow", 1},     {"Cultivate", 2},
    };
    int k = 0;
    for (const auto& [name, kk] : kWithinManaValue) { if (def.card.m_name == name) { k = kk; break; } }
    return 100 * LandfallTier(def) + 10 * mv + k;
}

bool LandfallProvider::CastOrderTotalByName() const { return LandfallOrderEnabled(); }

const char* LandfallProvider::CastOrderTierName(int rank) const
{
    if (!LandfallOrderEnabled()) { return DeckProvider::CastOrderTierName(rank); }
    switch (rank / 100)
    {
        case 1:  return "LANDFALL SOURCE (Khalni, Courser, Phylath, Baloths, Avenger, Omnath): first -- every land after it triggers it (USER)";
        case 2:  return "MANA-MAKING LAND ENTRY (Search for Tomorrow cast, Cultivate): after the sources, before the other spells; the spot BEFORE the sources is also searched (USER)";
        case 3:  return "PUTS NO LAND (Terastodon)";
        case 4:  return "REVEAL-AND-PUT (Genesis Wave): its lands reach the sources already cast";
        case 5:  return "TAPPED LAND ENTRY (Rampant Growth, Primeval Titan): late (USER)";
        default: return nullptr;
    }
}

// THE SECOND SPOT (USER: "we test them in two spots and we prefer the one after the landfall sources").
// A plan casting a tier-2 spell (Search for Tomorrow, Cultivate) AND a landfall source gets two
// orderings through the engine's cast-ordering search: the approved order FIRST (so it survives the
// end-state dedup and wins an exact tie), then the same order with the tier-2 casts moved ahead of the
// sources -- what pays for a source the approved order cannot, or counts one more land for Avenger /
// Phylath. Every other plan returns no candidates and is left exactly as it was (no searched_order, no
// extra apply).
// ---- LandfallProvider::CleanupDiscardCandidates -- the analyze-deck 5i BUCKET policy -----------------------
//
// Authored 2026-10-16 (ledger Stage 5i) on the USER's "Can you work on the discard heuristic?" -- "As always,
// there should be a bucketed policy". PROVISIONAL until the USER signs it off; default ON,
// MTG_LANDFALL_BUCKET_DISCARD=0 restores the generic max-MV ranking. Cleanup is the only discard this deck
// meets (~1 shed per 44 games, every observed one a tie), so the value is doctrine and rollout fidelity.
//
// THE BUCKETS (quota-first, net of board, sub-quotas fungible upward, distance-to-playable, ONE index):
//   MANA      parent quota P = max(Lq, 7 - board lands): enough mana cards to reach the curve top (Avenger,
//             Omnath at 7), never fewer than the land quota.
//     LANDS   sub-quota Lq = colour coverage + 2 while the board holds < 4 lands, else + 1 (+ 2 when the hand
//             holds two land KINDS -- USER: "2 lands of different types could still be okay later") -- never 0: every
//             land is a landfall trigger. COLOUR COVERAGE first: for each colour the hand's spells need
//             (green; red for Phylath / Omnath) that no battlefield land makes, the best hand land making it
//             (a basic-fetcher counts while a basic of that colour is in the library). Then by stage (USER:
//             "Evolving Wilds/Terramorphic are good late, but poor early. Myriad Landscape is good unless we
//             need untapped mana"): needing an untapped drop next turn, basic > colourless > Myriad > Gruul
//             Turf > Wilds; else Myriad first, Wilds second LATE (4+ lands or a landfall source out) and
//             last EARLY, then basic > Gruul Turf > colourless.
//     RAMP    sub-quota P - Lq (Rampant Growth, Search for Tomorrow, Cultivate, Khalni Heart Expedition):
//             castability first, then by stage (USER: "Search is good early. Others like Cultivate are
//             better later") -- under 3 lands out Search > Rampant Growth > Khalni > Cultivate, later
//             Cultivate > Search > Rampant Growth > Khalni. Fungible upward: a hand short of ramp keeps more
//             lands, a hand short of lands more ramp, up to P.
//             KHALNI only with lands coming down (USER 2026-10-17, MTG_LANDFALL_KHALNI_NEEDS_RAMP): ramp when
//             the hand and board bring its three landfalls by the turn after it is cast; otherwise only a
//             ramp spot the other ramp leaves (ahead of extra lands but Myriad), else it sheds after a capped copy.
//   THREATS   the catch-all, FLOOR 2 (USER: "2 threats sounds fine"). PHYLATH FIRST (USER: "it seems to be the
//             fastest"), the rest by CASTABILITY (USER: "If we can't cast the threat we should use another"),
//             the shared discard_dist factor (Genesis Wave priced at X = 3); exact ties by the author's rank
//             Avenger > Primeval Titan > Rampaging Baloths > Genesis Wave > Omnath > Terastodon > Courser.
//             AT MOST ONE Primeval Titan (USER: no kill potential in this list) and one copy of a legend,
//             net of board.
//   CAPPED    a copy beyond its cap: shed right after a dead card.
//   THREAT GATE (MTG_LANDFALL_DISCARD_GATE, default ON, USER 2026-10-17): castable first (kept ramp credited), rank among them.
//   DEAD      a legendary whose namesake is on our battlefield (Phylath, Omnath): no quota, shed first.
// Keep order: colour coverage, lands to Lq, ramp to its sub-quota, the fungible fill to P, the threat floor,
// the rest of the threats ("extra spells should always be threats"), the mana overflow, a Khalni the rule
// does not keep, a capped copy, then the dead. The
// shed is the LAST of that order, returned as ONE index (5i rule 5) through CleanupDiscardRankingWithOrder;
// MTG_LANDFALL_DISCARD_FAN=1 (testing only) returns the whole order for the rule-vs-searched check.
static bool LandfallBucketDiscardEnabled()
{
    static const bool on = EnvOn("MTG_LANDFALL_BUCKET_DISCARD", true);   // DEFAULT ON (provisional); =0 -> generic
    return heurarm::Flag(heurarm::LANDFALL_BUCKET_DISCARD, on);
}
// USER 2026-10-17: "Khalni can be counted as ramp, but I wouldn't keep it unless we have enough other ramp
// active to activate it quickly." See the MANA section below.
static bool LandfallKhalniNeedsRamp()
{
    static const bool on = EnvOn("MTG_LANDFALL_KHALNI_NEEDS_RAMP", true);   // DEFAULT ON (the USER's rule)
    return heurarm::Flag(heurarm::LANDFALL_KHALNI_NEEDS_RAMP, on);
}
// The castability gate, from the rule-vs-searched labels (2026-10-17; USER approved the same day).
static bool LandfallDiscardGate()
{
    static const bool on = EnvOn("MTG_LANDFALL_DISCARD_GATE", true);   // DEFAULT ON (USER 2026-10-17); =0 -> castability order
    return heurarm::Flag(heurarm::LANDFALL_DISCARD_GATE, on);
}

std::vector<int> LandfallProvider::CleanupDiscardCandidates(
    const GameState& s, const std::vector<std::string>* required_pieces) const
{
    if (!LandfallBucketDiscardEnabled()) { return DeckProvider::CleanupDiscardCandidates(s, required_pieces); }
    const int me = s.active_player_index;
    const Player& ap = s.players[me];
    const int n = static_cast<int>(ap.hand.size());
    if (n <= 0) { return DeckProvider::CleanupDiscardCandidates(s, required_pieces); }
    auto def_of = [](const Card& c) { return CardDatabase::Instance().LookupCached(c); };
    auto makes = [](const CardDefinition* d, Color col)
    { return d != nullptr && std::find(d->params.produces.begin(), d->params.produces.end(), col)
                             != d->params.produces.end(); };
    auto is_fetcher = [](const CardDefinition* d)
    { return d != nullptr && d->card.IsLand() && d->params.land_search_count > 0 && d->params.land_search_basic_only; };
    bool basic_in_library[2] = { false, false };   // [0] green (Forest), [1] red (Mountain)
    for (const Card& c : ap.library)
    {
        const CardDefinition* d = def_of(c);
        if (d == nullptr || !IsBasicLandCard(*d)) { continue; }
        if (makes(d, Color::Green)) { basic_in_library[0] = true; }
        if (makes(d, Color::Red))   { basic_in_library[1] = true; }
    }
    const Color kCols[2] = { Color::Green, Color::Red };
    auto source_of = [&](const CardDefinition* d, int k)   // makes colour k now, or fetches a basic of it
    { return makes(d, kCols[k]) || (is_fetcher(d) && basic_in_library[k]); };

    // ---- board census (net of board) -------------------------------------------------------------
    int board_lands = 0, board_src[2] = { 0, 0 };
    std::vector<std::string> board_legends;
    for (const Permanent& perm : s.battlefield)
    {
        if (perm.controller_index != me) { continue; }
        const CardDefinition* d = def_of(perm.card);
        if (perm.card.IsLand())
        {
            ++board_lands;
            for (int k = 0; k < 2; ++k) { if (source_of(d, k)) { ++board_src[k]; } }
        }
        if (perm.card.HasSupertype(Supertype::Legendary)) { board_legends.push_back(perm.card.m_name.str()); }
    }

    // ---- roles -----------------------------------------------------------------------------------
    auto pips = [](const CardDefinition* d, int k)
    { return d == nullptr ? 0 : static_cast<int>(k == 0 ? d->card.m_mana_cost.green : d->card.m_mana_cost.red); };
    auto is_ramp = [](const CardDefinition* d)
    { return d != nullptr && !d->card.IsLand() && !d->card.IsCreature()
             && (d->params.land_search_on_resolve || d->params.landfall_quest_counters > 0); };
    // LANDS by stage (USER: "the multiple landfall cards like Evolving Wilds/Terramorphic are good late, but
    // poor early. Myriad Landscape is good unless we need untapped mana."). NEED UNTAPPED: a spell in hand
    // costs exactly board lands + 1, so next turn casts it only off an untapped drop -- then the untapped
    // lands lead (basic > colourless) and the tapped ones trail (Myriad > Gruul Turf > Wilds). Otherwise
    // Myriad leads; Wilds / Terramorphic follow it LATE (4+ lands out, or a landfall source already on our
    // battlefield) and go to the back EARLY, behind the basics, Gruul Turf and the colourless lands.
    bool source_on_board = false, needs_untapped = false;
    for (const Permanent& perm : s.battlefield)
    {
        if (perm.controller_index != me) { continue; }
        const CardDefinition* d = def_of(perm.card);
        if (d != nullptr && d->landfall_watcher) { source_on_board = true; break; }
    }
    for (int i = 0; i < n; ++i)
    {
        const CardDefinition* d = def_of(ap.hand[i]);
        if (d != nullptr && !d->card.IsLand() && d->card.m_mana_cost.ManaValue() == board_lands + 1)
        { needs_untapped = true; break; }
    }
    const bool land_late = board_lands >= 4 || source_on_board;
    auto land_value = [&](const CardDefinition* d)   // higher = kept first
    {
        if (d == nullptr) { return 0; }
        const bool myriad = d->params.land_search_count >= 2;
        const bool wilds  = !myriad && d->card.IsLand() && d->params.land_search_count > 0;
        const bool turf   = d->params.etb_bounce_land;
        const bool basic  = !myriad && !wilds && !turf && IsBasicLandCard(*d);
        if (needs_untapped) { return basic ? 5 : (!myriad && !wilds && !turf) ? 4 : myriad ? 3 : turf ? 2 : 1; }
        if (myriad) { return 5; }
        if (wilds)  { return land_late ? 4 : 1; }
        if (basic)  { return 3; }
        if (turf)   { return 2; }
        return land_late ? 1 : 2;                              // colourless utility (Fountain, Fengraf)
    };
    // RAMP by stage (USER: "Same with acceleration. Search is good early. Others like Cultivate are better
    // later."): castability first, as for the threats, then -- EARLY, under 3 lands out, while a {G} suspend
    // still lands the basic on curve -- Search for Tomorrow > Rampant Growth > Khalni > Cultivate; LATER
    // Cultivate (two lands, one a card) > Search for Tomorrow > Rampant Growth > Khalni.
    const bool early = board_lands < 3;
    auto ramp_value = [early](const CardDefinition* d)   // higher = kept first
    {
        const bool cultivate = d->params.land_search_to_hand > 0;
        const bool search    = !cultivate && LandSearchPutsUntapped(*d);
        const bool growth    = !cultivate && !search && d->params.land_search_on_resolve;
        if (early) { return search ? 4 : growth ? 3 : cultivate ? 1 : 2; }
        return cultivate ? 4 : search ? 3 : growth ? 2 : 1;
    };
    // USER 2026-10-16: "I would actually keep Phylath first as it seems to be the fastest. (low mana + can
    // pump creatures that are not summoning sick next turn)".
    static const std::pair<const char*, int> kThreatRank[] = {   // higher = kept first
        {"Phylath, World Sculptor", 8}, {"Avenger of Zendikar", 7}, {"Primeval Titan", 6},
        {"Rampaging Baloths", 5}, {"Genesis Wave", 4}, {"Omnath, Locus of Rage", 3},
        {"Terastodon", 2}, {"Courser of Kruphix", 1},
    };
    auto threat_rank = [&](const Card& c)
    { for (const auto& [name, r] : kThreatRank) { if (c.m_name == name) { return r; } } return 0; };
    // USER 2026-10-16: "no more than 1 titan because Titan does not have the kill potential in the current
    // list". A per-card cap, net of board: a copy beyond it is no threat and sheds right after a dead legend.
    static const std::pair<const char*, int> kThreatCap[] = { {"Primeval Titan", 1} };
    auto threat_cap = [&](const Card& c)
    {
        for (const auto& [name, cap] : kThreatCap) { if (c.m_name == name) { return cap; } }
        return c.HasSupertype(Supertype::Legendary) ? 1 : -1;   // the legend rule: a 2nd copy is a blank here
    };
    std::vector<std::pair<std::string, int>> capped_seen;   // name -> copies counted (board first)
    auto over_cap = [&](const Card& c)
    {
        const int cap = threat_cap(c);
        if (cap < 0) { return false; }
        auto it = std::find_if(capped_seen.begin(), capped_seen.end(),
                               [&](const auto& e) { return c.m_name == e.first.c_str(); });
        if (it == capped_seen.end())
        {
            int on_board = 0;
            for (const Permanent& perm : s.battlefield)
            { if (perm.controller_index == me && perm.card.m_name == c.m_name) { ++on_board; } }
            capped_seen.emplace_back(c.m_name.str(), on_board);
            it = capped_seen.end() - 1;
        }
        return ++it->second > cap;
    };

    std::vector<int> dead, capped, lands, ramp, threats;
    bool need[2] = { false, false };
    for (int i = 0; i < n; ++i)
    {
        const Card& c = ap.hand[i];
        if (c.m_is_staged) { continue; }
        const CardDefinition* d = def_of(c);
        if (CleanupDiscardIsLand(c)) { lands.push_back(i); continue; }
        if (c.HasSupertype(Supertype::Legendary)
            && std::find(board_legends.begin(), board_legends.end(), c.m_name.str()) != board_legends.end())
        { dead.push_back(i); continue; }
        if (over_cap(c)) { capped.push_back(i); continue; }
        for (int k = 0; k < 2; ++k) { if (pips(d, k) > 0) { need[k] = true; } }
        (is_ramp(d) ? ramp : threats).push_back(i);
    }
    std::stable_sort(lands.begin(), lands.end(), [&](int a, int b)
    { return land_value(def_of(ap.hand[a])) > land_value(def_of(ap.hand[b])); });
    // Castability (the shared discard_dist factor; every hand land as a drop, best first, since the land
    // quota is not settled yet): Search for Tomorrow priced at its {G} suspend while early.
    const discard_dist::Census census = discard_dist::BuildCensus(s, me);
    std::vector<discard_dist::LandDrop> hand_drops;
    for (int i : lands) { hand_drops.push_back(discard_dist::LandDropOf(def_of(ap.hand[i]))); }
    std::vector<double> ramp_fac(static_cast<std::size_t>(n), 0.0);
    for (int i : ramp)
    {
        const CardDefinition* d = def_of(ap.hand[i]);
        const bool suspend = early && d->params.land_search_to_hand == 0 && LandSearchPutsUntapped(*d);
        ramp_fac[static_cast<std::size_t>(i)] = discard_dist::CastFactorFor(census, *d, hand_drops, suspend ? 1 : -1);
    }
    std::stable_sort(ramp.begin(), ramp.end(), [&](int a, int b)
    {
        const double fa = ramp_fac[static_cast<std::size_t>(a)], fb = ramp_fac[static_cast<std::size_t>(b)];
        if (fa != fb) { return fa > fb; }
        return ramp_value(def_of(ap.hand[a])) > ramp_value(def_of(ap.hand[b]));
    });

    // ---- MANA: colour coverage, the land sub-quota, the ramp sub-quota, the fungible fill to P ----
    std::vector<int> keep;
    std::vector<char> kept(static_cast<std::size_t>(n), 0);
    auto take = [&](int i) { keep.push_back(i); kept[static_cast<std::size_t>(i)] = 1; };
    int cover = 0;
    for (int k = 0; k < 2; ++k)
    {
        if (!need[k] || board_src[k] > 0) { continue; }
        for (int i : lands)
        {
            if (!kept[static_cast<std::size_t>(i)] && source_of(def_of(ap.hand[i]), k)) { take(i); ++cover; break; }
        }
    }
    // Two land drops early; later one -- or two when the hand holds two land KINDS (USER: "Keeping 2 lands of
    // different types could still be okay later for flexibility"). Kinds: Myriad, a basic-fetcher (Wilds /
    // Terramorphic, one class), Gruul Turf, a green basic, a red basic, a colourless land.
    auto land_kind = [&](const CardDefinition* d)
    {
        if (d == nullptr)                        { return 0; }
        if (d->params.land_search_count >= 2)    { return 1; }
        if (d->params.land_search_count > 0)     { return 2; }
        if (d->params.etb_bounce_land)           { return 3; }
        if (makes(d, Color::Green))              { return 4; }
        if (makes(d, Color::Red))                { return 5; }
        return 6;
    };
    bool two_kinds = false;
    for (std::size_t x = 0; x < lands.size() && !two_kinds; ++x)
        for (std::size_t y = x + 1; y < lands.size(); ++y)
            if (land_kind(def_of(ap.hand[lands[x]])) != land_kind(def_of(ap.hand[lands[y]]))) { two_kinds = true; break; }
    const int land_quota  = cover + ((board_lands < 4 || two_kinds) ? 2 : 1);
    const int mana_parent = std::max(land_quota, 7 - board_lands);
    int kept_lands = cover, mana_kept = cover;   // mana CARDS kept, the colour lands first
    for (int i : lands)
    {
        if (kept_lands < land_quota && !kept[static_cast<std::size_t>(i)])
        { take(i); ++kept_lands; ++mana_kept; }
    }
    // KHALNI (USER 2026-10-17, MTG_LANDFALL_KHALNI_NEEDS_RAMP): "Khalni can be counted as ramp, but I wouldn't
    // keep it unless we have enough other ramp active to activate it quickly", "Khalni is not great unless you
    // have a lot of lands coming down", and "it should still be kept if we cannot fill our ramp spots
    // otherwise". LANDS COMING DOWN, from the hand and the battlefield only (no hoped-for draws): it is kept
    // as ramp when its three landfalls arrive by the end of the turn after it is cast -- the land drops from
    // lands in hand (at most 2), plus the other kept ramp (Rampant Growth / Search for Tomorrow / Cultivate 1
    // each), plus fetch lands in hand or uncracked on our battlefield (Evolving Wilds / Terramorphic 1,
    // Myriad 2). Otherwise it is kept only to fill a ramp spot the other ramp leaves -- ahead of the extra lands
    // except Myriad (below), while the mana target is still short -- and sheds right after a capped copy.
    const bool khalni_rule = LandfallKhalniNeedsRamp();
    auto is_khalni = [&](int i)
    { const CardDefinition* d = def_of(ap.hand[i]); return d != nullptr && d->params.landfall_quest_counters > 0; };
    std::vector<int> weak;
    for (int i : ramp)
    {
        if (khalni_rule && is_khalni(i)) { continue; }
        if (mana_kept < mana_parent) { take(i); ++mana_kept; }
    }
    std::vector<int> khalni_late;   // a Khalni short of lands coming down: a ramp spot only nothing else fills
    if (khalni_rule)
    {
        int landfalls = std::min(2, static_cast<int>(lands.size()));
        for (int i : lands)
        { const CardDefinition* d = def_of(ap.hand[i]); if (d != nullptr) { landfalls += d->params.land_search_count; } }
        for (int i : keep)
        {
            const CardDefinition* d = def_of(ap.hand[i]);
            if (d != nullptr && !d->card.IsLand() && d->params.land_search_on_resolve) { ++landfalls; }
        }
        for (const Permanent& perm : s.battlefield)
        {
            if (perm.controller_index != me || !perm.card.IsLand()) { continue; }
            const CardDefinition* d = def_of(perm.card);
            if (d != nullptr) { landfalls += d->params.land_search_count; }
        }
        constexpr int kKhalniLandfalls = 3;   // its quest: cracked the turn after it is cast
        for (int i : ramp)
        {
            if (!is_khalni(i)) { continue; }
            if (landfalls < kKhalniLandfalls) { khalni_late.push_back(i); continue; }
            if (mana_kept < mana_parent) { take(i); ++mana_kept; }
        }
    }
    // Fungible upward: a hand short of ramp keeps more lands, up to the parent. A Khalni short of lands coming
    // down still precedes those lands -- "It is more ramp than land except arguably Myriad Landscape" (USER
    // 2026-10-17) -- so the fill is Myriad, then that Khalni, then the other lands.
    auto fill_land = [&](int i)
    {
        if (mana_kept < mana_parent && !kept[static_cast<std::size_t>(i)])
        { take(i); ++kept_lands; ++mana_kept; }
    };
    if (!khalni_late.empty())
    {
        for (int i : lands)
        { const CardDefinition* d = def_of(ap.hand[i]); if (d != nullptr && d->params.land_search_count >= 2) { fill_land(i); } }
        for (int i : khalni_late)
        {
            if (mana_kept < mana_parent) { take(i); ++mana_kept; }
            else                         { weak.push_back(i); }
        }
    }
    for (int i : lands) { fill_land(i); }

    // ---- THREATS: Phylath first, then CASTABILITY, then the rank -----------------------------------
    // USER: "keep Phylath first as it seems to be the fastest" and "The order of the others could be based on
    // castability. If we can't cast the threat we should use another." Castability is the shared model
    // (discard_dist, docs/design/discard-distance-model.md; USER 2026-10-10 "a smarter model"): P(castable)
    // over our next four turns from the board's mana, the KEPT hand lands played one per turn, and the
    // library's land / colour density, discounted per turn of delay. Genesis Wave is priced at X = 3, the
    // least worth casting. The rank (the author's) breaks exact ties only.
    std::vector<discard_dist::LandDrop> kept_drops;
    for (int i : keep)
    {
        const CardDefinition* d = def_of(ap.hand[i]);
        if (d != nullptr && d->card.IsLand()) { kept_drops.push_back(discard_dist::LandDropOf(d)); }
    }
    // THE GATE (MTG_LANDFALL_DISCARD_GATE, amendment A; the labels' one regret, s2312103 T2, shed Avenger
    // because the land-only model read it uncastable beside Titan and Wave). The kept RAMP is credited as
    // mana -- one spell a turn from our next turn, its basic usable the turn after (a kept Khalni two basics,
    // a turn later still for its counters), red first while the threat is short of red -- and a threat is
    // CASTABLE when P(castable within our next four turns) >= 0.5. The castable come first and the rank
    // decides among them ("If we can't cast the threat we should use another"); the rest keep castability
    // then the rank. Phylath stays first.
    const bool gate = LandfallDiscardGate();
    std::array<int, discard_dist::kHorizon> credit{};   // basics the kept ramp has added by our t-th next turn
    if (gate)
    {
        int j = 0;
        for (int i : keep)
        {
            const CardDefinition* d = def_of(ap.hand[i]);
            if (d == nullptr || !is_ramp(d)) { continue; }
            const bool khalni = d->params.landfall_quest_counters > 0;
            const int from = j + 2 + (khalni ? 1 : 0), amount = khalni ? 2 : 1;
            for (int t = from; t <= discard_dist::kHorizon; ++t) { credit[static_cast<std::size_t>(t - 1)] += amount; }
            ++j;
        }
    }
    int red_have = census.board_src[3];
    for (const discard_dist::LandDrop& ld : kept_drops) { if (ld.colours & (1u << 3)) { ++red_have; } }
    std::vector<double> fac(static_cast<std::size_t>(n), 0.0);
    std::vector<char> castable(static_cast<std::size_t>(n), 0);
    for (int i : threats)
    {
        const CardDefinition* d = def_of(ap.hand[i]);
        if (d == nullptr) { continue; }
        const int cost = d->params.reveal_x_put_permanents ? d->card.m_mana_cost.ManaValue() + 3 : -1;
        if (!gate) { fac[static_cast<std::size_t>(i)] = discard_dist::CastFactorFor(census, *d, kept_drops, cost); continue; }
        const ManaCost& mc = d->card.m_mana_cost;
        const std::array<int, 5> pips = { mc.white, mc.blue, mc.black, mc.red, mc.green };
        const int red_short = std::max(0, static_cast<int>(mc.red) - red_have);
        discard_dist::ColourCredit cc{};
        for (int t = 0; t < discard_dist::kHorizon; ++t)
        {
            const int c = credit[static_cast<std::size_t>(t)], r = std::min(c, red_short);
            cc[static_cast<std::size_t>(t)][3] = r;
            cc[static_cast<std::size_t>(t)][4] = c - r;
        }
        const std::array<double, discard_dist::kHorizon> p =
            discard_dist::CastProbByTurn(census, cost >= 0 ? cost : mc.ManaValue(), pips, kept_drops, &credit, &cc);
        fac[static_cast<std::size_t>(i)] = discard_dist::CastFactor(p);
        castable[static_cast<std::size_t>(i)] = p[discard_dist::kHorizon - 1] >= 0.5 ? 1 : 0;
    }
    auto phylath_first = [&](int i) { return ap.hand[i].m_name == "Phylath, World Sculptor"; };
    std::stable_sort(threats.begin(), threats.end(), [&](int a, int b)
    {
        const bool pa = phylath_first(a), pb = phylath_first(b);
        if (pa != pb) { return pa; }
        const int ra = threat_rank(ap.hand[a]), rb = threat_rank(ap.hand[b]);
        if (gate)
        {
            const bool ca = castable[static_cast<std::size_t>(a)] != 0, cb = castable[static_cast<std::size_t>(b)] != 0;
            if (ca != cb) { return ca; }
            if (ca && ra != rb) { return ra > rb; }
        }
        const double fa = fac[static_cast<std::size_t>(a)], fb = fac[static_cast<std::size_t>(b)];
        if (fa != fb) { return fa > fb; }
        if (ra != rb) { return ra > rb; }
        return CleanupDiscardManaValue(ap.hand[a]) < CleanupDiscardManaValue(ap.hand[b]);
    });
    for (int i : threats) { take(i); }   // the floor (2) and the catch-all share one order: best first

    // ---- overflow: the mana beyond its parent, a Khalni the rule does not keep, a capped copy, the dead
    for (int i : ramp)
    {
        if (!kept[static_cast<std::size_t>(i)] && std::find(weak.begin(), weak.end(), i) == weak.end()) { take(i); }
    }
    for (int i : lands) { if (!kept[static_cast<std::size_t>(i)]) { take(i); } }
    for (int i : weak)  { take(i); }
    for (int i : capped) { take(i); }
    for (int i : dead)  { take(i); }

    // The floor matters when the quotas over-fill the hand: a shed then comes out of the mana quota
    // before it reaches the two best threats. Re-rank so the threat floor sits above the mana quota.
    constexpr int kThreatFloor = 2;
    std::vector<int> order;   // keep order, best first, with the floor moved ahead of the mana quotas
    {
        const std::size_t n_floor = std::min<std::size_t>(kThreatFloor, threats.size());
        for (std::size_t k = 0; k < n_floor; ++k) { order.push_back(threats[k]); }
        for (int i : keep)
        { if (std::find(order.begin(), order.end(), i) == order.end()) { order.push_back(i); } }
    }
    std::vector<int> shed(order.rbegin(), order.rend());
    std::vector<int> ranked = CleanupDiscardRankingWithOrder(s, required_pieces, shed);
    static const bool s_fan = EnvOn("MTG_LANDFALL_DISCARD_FAN");   // TESTING ONLY: the whole order
    if (!s_fan && ranked.size() > 1) { ranked.resize(1); }
    return ranked;
}

// ONE index per consultation, and the next one moves with the hand (the land quota and the threats'
// castability read the hand's lands): a multi-card shed re-asks after every shed.
bool LandfallProvider::CleanupDiscardShedStable() const { return !LandfallBucketDiscardEnabled(); }

// THE SPOTS (USER: the land drop is tested "in two spots and we prefer the one after the landfall
// sources"; "activations of Khalni Heart and Myriad Landscape would go at the end"). The engine also
// tried the land BETWEEN two sources and the land-search activations before an Avenger / Phylath; this
// drops those spots (TurnSolver's land_slot / land_search_act_slot emission). MTG_LANDFALL_SPOTS=0 keeps
// every spot (heurarm LANDFALL_SPOTS).
static bool LandfallSpotsEnabled()
{
    static const bool on = EnvOn("MTG_LANDFALL_SPOTS", true);   // DEFAULT ON (the USER's rule); =0 -> every spot
    return heurarm::Flag(heurarm::LANDFALL_SPOTS, on);
}

bool LandfallProvider::LandEntrySpotsRule(const GameState& s) const { (void)s; return LandfallSpotsEnabled(); }

bool LandfallProvider::WantsCastOrderingSearch() const { return LandfallOrderEnabled(); }

bool LandfallProvider::CastOrderingCandidates(const GameState& s, const std::vector<Action>& plan_actions,
                                              const std::vector<Action>& reorder,
                                              std::vector<std::vector<int>>& out) const
{
    (void)plan_actions;
    out.clear();
    if (!LandfallOrderEnabled()) { return true; }
    auto def_of = [](const Action& a) -> const CardDefinition*
    { return a.def ? a.def : CardDatabase::Instance().Lookup(a.card_name); };
    std::vector<int> canon(reorder.size());
    for (std::size_t i = 0; i < canon.size(); ++i) { canon[i] = static_cast<int>(i); }
    std::stable_sort(canon.begin(), canon.end(), [&](int x, int y) { return CastOrderLess(s, reorder[x], reorder[y]); });
    std::vector<int> early, rest;
    bool source = false;
    for (int i : canon)
    {
        const CardDefinition* d = def_of(reorder[static_cast<std::size_t>(i)]);
        if (d != nullptr && d->landfall_watcher) { source = true; }
        (d != nullptr && LandfallManaLandEntry(*d) ? early : rest).push_back(i);
    }
    if (early.empty() || !source) { return true; }
    out.push_back(canon);
    early.insert(early.end(), rest.begin(), rest.end());
    out.push_back(std::move(early));
    return true;
}

std::vector<int> DecisionProvider::BounceSearchCandidates(
    const GameState& s, int controller, int self_index, const std::vector<int>& legal,
    int* why) const
{
    // The ORDER is BounceLandCandidates' (whichever provider overrides it); this only decides how
    // much of it the search sees. See the header for the rules and why each is (near-)sound.
    const std::vector<int> ranked = BounceLandCandidates(s, controller, self_index, legal);
    auto set_why = [&](int r) { if (why != nullptr) { *why = r; } };
    if (ranked.size() <= 1) { set_why(kBounceOnly); return ranked; }
    if (DecisionUnpruned(UnprunedGate::KarooBounce)) { set_why(kBounceUnpruned); return ranked; }

    static const bool s_spare_aura_env = EnvOn("MTG_BOUNCE_SPARE_AURA", true);
    const bool spare_aura = heurarm::Flag(heurarm::BOUNCE_SPARE_AURA, s_spare_aura_env);
    struct Info { int idx; bool karoo, aura, tapped, clean, refresh; int dep; std::string name; };
    std::vector<Info> info;
    info.reserve(ranked.size());
    for (int i : ranked)
    {
        const Permanent& p = s.battlefield[static_cast<std::size_t>(i)];
        const CardDefinition* d = CardDatabase::Instance().LookupCached(p.card);
        Info f;
        f.idx    = i;
        f.karoo  = d != nullptr && d->params.etb_bounce_land;
        f.aura   = false;
        if (spare_aura)
        {
            for (const Permanent& q : s.battlefield)
            { if (q.aura_attached_to != 0 && q.aura_attached_to == p.card.m_number) { f.aura = true; break; } }
        }
        f.tapped = p.tapped;
        f.clean  = BounceReplayPreciseOn()
                 ? (d != nullptr && BounceReplayEntersUntapped(s, controller, i, *d))
                 : !(d != nullptr && (d->params.enters_tapped || d->params.enters_tapped_with_depletion > 0));
        f.dep    = 0;
        for (const Counter& c : p.counters) { if (c.type == Counter::Type::Depletion) { f.dep += c.count; } }
        // A spent DEPLETION land the replay would refresh (Remote Farm on its last counter): returning
        // it trades next turn's tempo for fresh counters -- a real alternative, never folded away.
        f.refresh = p.tapped && d != nullptr && d->params.enters_tapped_with_depletion > 0
                 && f.dep < d->params.enters_tapped_with_depletion;
        f.name   = p.card.m_name.str();
        info.push_back(std::move(f));
    }
    // Exclusions that hold while ANY other land is returnable (the order already ranks them last).
    auto drop_if_others = [&](auto pred) {
        bool any_other = false;
        for (const Info& f : info) { if (!pred(f)) { any_other = true; break; } }
        if (!any_other) { return; }
        info.erase(std::remove_if(info.begin(), info.end(), pred), info.end());
    };
    drop_if_others([](const Info& f) { return f.karoo; });
    drop_if_others([](const Info& f) { return f.aura; });

    // THE USER'S DEFAULT (MTG_BOUNCE_USER_RULE) comes FIRST: a tapped land that re-enters untapped and
    // makes no colour no other kept land makes is returned with no search. It sharpens the
    // tapped-clean rule below (its pick is always one of those lands) and outranks the depletion-refresh
    // alternative and the colour-by-colour contest with a land in hand. BounceLandCandidates already
    // made it the front.
    if (BounceUserRuleActive())
    {
        int names = 0;
        const int pick = BounceUserRulePick(s, controller, legal, ranked, &names);
        if (bouncestats::Enabled() && g_bounce_searched_site && names > 1)
        { bouncestats::UserMulti(); }
        if (pick >= 0) { set_why(kBounceUserRule); return { pick }; }
    }

    bool hand_land = false;
    for (const Card& c : s.players[static_cast<std::size_t>(controller)].hand)
    { if (c.IsLand()) { hand_land = true; break; } }
    bool any_free_clean = false, any_tapped = false;
    for (const Info& f : info)
    {
        if (f.tapped) { any_tapped = true; }
        if (f.tapped && f.clean) { any_free_clean = true; }
    }
    bool cut_tapped_clean = false, cut_dominated = false;
    std::vector<const Info*> keep;
    for (const Info& f : info)
    {
        if (any_free_clean)
        {
            // A spent land with a clean replay costs nothing: only those (and a refreshing depletion
            // land) stay.
            if (!(f.tapped && (f.clean || f.refresh))) { cut_tapped_clean = true; continue; }
        }
        else if (any_tapped && !f.tapped && !f.clean)
        {
            cut_dominated = true;   // untapped AND re-enters tapped: a tapped land loses less
            continue;
        }
        keep.push_back(&f);
    }
    // Folds, walking in the provider's order so each group keeps the provider's preferred copy.
    std::vector<std::string> seen;
    std::vector<int> out;
    bool folded_identical = false, folded_replay = false;
    for (const Info* f : keep)
    {
        std::string key;
        if (f->tapped && !f->refresh && !hand_land)
        {
            key = std::string("T*") + (f->clean ? "c" : "t");    // replay fold (no other land in hand)
        }
        else
        {
            key = std::string(f->tapped ? "T|" : "U|") + f->name + "|" + std::to_string(f->dep);
        }
        if (std::find(seen.begin(), seen.end(), key) != seen.end())
        {
            if (key[1] == '*') { folded_replay = true; } else { folded_identical = true; }
            continue;
        }
        seen.push_back(key);
        out.push_back(f->idx);
    }
    // The front is the d0 / beyond-horizon pick and the human prompt's default; the narrowing must
    // never drop it. (No rule above can -- each removes only what the order ranks below a survivor --
    // but the invariant is what the base plan's -1 pin relies on, so it is enforced, not assumed.)
    if (out.empty() || out.front() != ranked.front())
    {
        out.erase(std::remove(out.begin(), out.end(), ranked.front()), out.end());
        out.insert(out.begin(), ranked.front());
    }
    if (out.size() > kBounceSearchWidth) { out.resize(kBounceSearchWidth); }
    // The census tag: contested, else the first rule (in this order) that removed something.
    (void)folded_identical;
    set_why(out.size() > 1       ? kBounceContested
          : cut_tapped_clean     ? kBounceTappedClean
          : cut_dominated        ? kBounceDominated
          : folded_replay        ? kBounceReplayFold
          :                        kBounceIdentical);   // identical copies, or the Karoo / Aura exclusions
    return out;
}

std::vector<int> DecisionProvider::BurnCreatureTargetCandidates(
    const GameState& s, int /*active*/, int damage,
    const std::vector<int>& opp_creatures) const
{
    // Killable first (so the death rider fires), stable otherwise -> index 0 is the first killable
    // creature, or the first creature when none is killable. Exactly FindBurnKillTarget.
    std::vector<int> out = opp_creatures;
    std::stable_sort(out.begin(), out.end(), [&](int a, int b) {
        return s.battlefield[a].EffectiveToughness() <= damage
            && s.battlefield[b].EffectiveToughness() >  damage;
    });
    return out;
}

std::vector<int> DecisionProvider::LifegainRemovalCandidates(
    const GameState& s, int /*active*/, const std::vector<int>& opp_creatures) const
{
    std::vector<int> out = opp_creatures;
    std::stable_sort(out.begin(), out.end(), [&](int a, int b) {
        return s.battlefield[a].EffectivePower() > s.battlefield[b].EffectivePower();
    });
    return out;
}

std::vector<int> DecisionProvider::OwnPumpTargetCandidates(
    const GameState& s, int /*controller*/, const std::vector<int>& own_attackers) const
{
    std::vector<int> out = own_attackers;
    std::stable_sort(out.begin(), out.end(), [&](int a, int b) {
        return s.battlefield[a].EffectivePower() > s.battlefield[b].EffectivePower();
    });
    return out;
}

